            //PEGDiv_MoveDirection_LtoR = true;               //  가공 방향 (true: 왼쪽에서 오른쪽으로 이동하면서 가공, 스테이지는 오른쪽에서 왼쪽으로 이동)
        }

        public void Module_Allocation()
        {
            ModuleCollection m_collectionModules;
            m_collectionModules = Equipment.Modules;

            foreach (Module module in m_collectionModules)
            {
                if (module.Name == "Loader")
                {
                    loader = module as Loader;
                }

                if (module.Name == "Unloader")
                {
                    unloader = module as Unloader;
                }

                if (module.Name == "Bds")
                {
                    bds = module as Bds;
                }

                if (module.Name == "Vision")
                {
                    vision = module as Vision;
                }
            }
        }

