        public string ConvertDecimalToHex(string m_strDecimalNumber)
        {
            int decimalNumber = 0;
            decimalNumber = Convert.ToInt32(m_strDecimalNumber);

            if (decimalNumber < 0 || decimalNumber > 9999)
            {
                return "NG";
            }

            return decimalNumber.ToString("X4");
        }

