        #region Serial Comm. - Electro Pneumatic Regulator

        public void ElectroPneumaticRegulator_Comm_Init()
        {
            string m_strPortName = "COM7";
            int m_nBaudRate = 115200;
            int m_nDataBits = 8;
            StopBits m_stopBits = StopBits.One;
            Parity m_parity = Parity.None;
            Handshake m_handshake = Handshake.None;

            //  Comm. Port 설정
            m_strPortName = string.Format("COM{0}", Equipment.stCommunicationSet[(int)Equipment.CommList.ElectroPneumaticRegulator].Serial_CommPort + 1);

            //  Baud Rate 설정
            switch (Equipment.stCommunicationSet[(int)Equipment.CommList.ElectroPneumaticRegulator].Serial_CommBaudRate)
            {
                case 0: m_nBaudRate = 1200; break;
                case 1: m_nBaudRate = 2400; break;
                case 2: m_nBaudRate = 4800; break;
                case 3: m_nBaudRate = 9600; break;
                case 4: m_nBaudRate = 19200; break;
                case 5: m_nBaudRate = 38400; break;
                case 6: m_nBaudRate = 57600; break;
                case 7: m_nBaudRate = 115200; break;
                default: m_nBaudRate = 9600; break;
            }

            //  Data Bits 설정
            switch (Equipment.stCommunicationSet[(int)Equipment.CommList.ElectroPneumaticRegulator].Serial_CommDataBits)
            {
                case 0: m_nDataBits = 5; break;
                case 1: m_nDataBits = 6; break;
                case 2: m_nDataBits = 7; break;
                case 3: m_nDataBits = 8; break;
                default: m_nDataBits = 8; break;
            }

            //  Stop Bits 설정
            switch (Equipment.stCommunicationSet[(int)Equipment.CommList.ElectroPneumaticRegulator].Serial_CommStopBits)
            {
                case 0: m_stopBits = StopBits.One; break;
                case 1: m_stopBits = StopBits.OnePointFive; break;
                case 2: m_stopBits = StopBits.Two; break;
                default: m_stopBits = StopBits.One; break;
            }

            //  Parity 설정
            switch (Equipment.stCommunicationSet[(int)Equipment.CommList.ElectroPneumaticRegulator].Serial_CommParity)
            {
                case 0: m_parity = Parity.None; break;
                case 1: m_parity = Parity.Odd; break;
                case 2: m_parity = Parity.Even; break;
                default: m_parity = Parity.None; break;
            }

            //  Flow Control 설정
            switch (Equipment.stCommunicationSet[(int)Equipment.CommList.ElectroPneumaticRegulator].Serial_CommFlowControl)
            {
                case 0: m_handshake = Handshake.None; break;
                case 1: m_handshake = Handshake.XOnXOff; break;
                case 2: m_handshake = Handshake.RequestToSend; break;
                case 3: m_handshake = Handshake.RequestToSendXOnXOff; break;
                default: m_handshake = Handshake.None; break;
            }

            if (!Equipment.stCommunicationSet[(int)Equipment.CommList.ElectroPneumaticRegulator].Connect)
                return;

            m_electroRegulator_Comm = new SerialCommElectroPneumaticRegulatorPort();
            m_electroRegulator_Comm.DataReceivedHandler = ElectroPneumaticRegulator_DataReceivedHandler;
            m_electroRegulator_Comm.DisconnectedHandler = ElectroPneumaticRegulator_DisconnectedHandler;
            if (!m_electroRegulator_Comm.OpenComm(m_strPortName, m_nBaudRate, m_nDataBits, m_stopBits, m_parity, m_handshake))
            {
                string text = string.Format("{0} Port Open Failed! (Electro Pneumatic Regulator)", m_strPortName);
                MessageBox.Show(text);
            }

            //  포트 연결되면 데이터 읽기 시작
            m_nEPROCommStep = (int)EPROComm_Step.Start;
        }

        private void ElectroPneumaticRegulator_DataReceivedHandler(byte[] receiveData)
        {
            //  전공 레귤레이터
            //  종단 코드 : CR.LF

            string @string = Encoding.Default.GetString(receiveData);

            m_strElectroRegulator_Comm_ReceivedData += @string;
            if (m_strElectroRegulator_Comm_ReceivedData.Length >= 1)
            {
                if (m_strElectroRegulator_Comm_ReceivedData.Length >= 2 && m_strElectroRegulator_Comm_ReceivedData[m_strElectroRegulator_Comm_ReceivedData.Length - 2] == '\r' && m_strElectroRegulator_Comm_ReceivedData[m_strElectroRegulator_Comm_ReceivedData.Length - 1] == '\n')
                {
                    m_bElectroRegulator_CommData_Received = true;

                    //MessageBox.Show(m_strElectroRegulator_Comm_ReceivedData);

                    //m_strElectroRegulator_Comm_ReceivedData = "";
                }
            }
        }

        private void ElectroPneumaticRegulator_DisconnectedHandler()
        {
            Console.WriteLine("Electro Pneumatic Regulator serial COM7 disconnected");
        }

        public bool ElectroPneumaticRegulatorComm_Pressure_Set(double m_dkPa)
        {
            bool m_bRet = false;

            double m_dMinPressure = -1.3;
            double m_dMaxPressure = -80.0;
            double m_dPressureTotalStep = 1023.0;
            double m_dPressurePerStep = (m_dMaxPressure - m_dMinPressure) / m_dPressureTotalStep;

            string m_strStepToString = "";
            int m_nCalcStep = 0;

            if ((m_dkPa > -1.3) || (m_dkPa < -80.0))
            {
                Console.WriteLine("Electro Pneumatic Regulator out of range (Available Range : -1.3kPa ~ -80.0kPa)");
                MessageBox.Show("Electro Pneumatic Regulator out of range\r\n\r\n[Available Range : -1.3kPa ~ -80.0kPa]", "Information!!");
                return m_bRet;
            }

            m_nCalcStep = (int)((m_dkPa - m_dMinPressure) / (m_dMaxPressure - m_dMinPressure) * m_dPressureTotalStep);

            if (m_electroRegulator_Comm == null)
                return m_bRet;

            m_strStepToString = m_nCalcStep.ToString();

            if (m_strStepToString.Length < 1)
            {
                return m_bRet;
            }

            string m_strSendData = "";
            byte[] m_cSendCmd = null;

            m_cSendCmd = new byte[m_strStepToString.Length + 6];            //  6 : 'SET ' + CR + LF

            m_cSendCmd[0] = (byte)'S';
            m_cSendCmd[1] = (byte)'E';
            m_cSendCmd[2] = (byte)'T';
            m_cSendCmd[3] = (byte)' ';

            for ( int i = 0; i < m_strStepToString.Length; i++)
            {
                m_cSendCmd[4 + i] = (byte)m_strStepToString[i];
            }

            m_cSendCmd[4 + m_strStepToString.Length] = chrCR;
            m_cSendCmd[4 + m_strStepToString.Length + 1] = chrLF;

            m_strSendData = Encoding.Default.GetString(m_cSendCmd);

            if (m_electroRegulator_Comm.IsOpen)
            {
                m_electroRegulator_Comm.Send(m_strSendData);
                m_bRet = true;
            }

            return m_bRet;
        }

        public double ElectroPneumaticRegulatorComm_ReceivedData_ConvertTo_Pressure(string m_strReceivedData)
        {
            double m_dRet = 0.0;
            double m_dMinPressure = -1.3;
            double m_dMaxPressure = -80.0;
            double m_dPressureTotalStep = 1023.0;
            double m_dPressurePerStep = (m_dMaxPressure - m_dMinPressure) / m_dPressureTotalStep;
            int m_nPressureStep = 0;
            int m_nLaserCommRecvData_LF_Count = 0;
            string m_strFront = "";
            bool m_bDataOK = true;

            //  데이터 체크 (2개가 붙어서 들어오는 경우가 있어서... ctrLF 가 1개인지 확인)
            for (int i = 0; i < m_strReceivedData.Length; i++)
            {
                if (m_strReceivedData[i] == chrCR)
                    m_nLaserCommRecvData_LF_Count++;
            }

            if (m_strReceivedData.Length < 1)
            {
                return m_dRet;
            }

            if (m_strReceivedData.Length > 10)
            {
                m_strFront = m_strReceivedData.Substring(0, 7);
                if (m_strFront == "UNKNOWN")
                {
                    m_bDataOK = false;
                }
            }

            if ((m_nLaserCommRecvData_LF_Count == 1) && m_bDataOK)
            {
                m_nPressureStep = Convert.ToInt32(m_strReceivedData);
                m_dRet = m_dMinPressure + ((double)m_nPressureStep / m_dPressureTotalStep) * (m_dMaxPressure - m_dMinPressure);
            }
            else
            {
                m_strElectroRegulator_Comm_ReceivedData = "";
            }

            return m_dRet;
        }

