        #region Serial Comm. - Rapid LX Laser

        public void RapidLxLaser_Comm_Init()
        {
            string m_strPortName = "COM11";
            int m_nBaudRate = 19200;
            int m_nDataBits = 8;
            StopBits m_stopBits = StopBits.One;
            Parity m_parity = Parity.None;
            Handshake m_handshake = Handshake.None;

            //  Comm. Port 설정
            m_strPortName = string.Format("COM{0}", Equipment.stCommunicationSet[(int)Equipment.CommList.Laser].Serial_CommPort + 1);

            //  Baud Rate 설정
            switch (Equipment.stCommunicationSet[(int)Equipment.CommList.Laser].Serial_CommBaudRate)
            {
                case 0: m_nBaudRate = 1200; break;
                case 1: m_nBaudRate = 2400; break;
                case 2: m_nBaudRate = 4800; break;
                case 3: m_nBaudRate = 9600; break;
                case 4: m_nBaudRate = 19200; break;
                case 5: m_nBaudRate = 38400; break;
                case 6: m_nBaudRate = 57600; break;
                case 7: m_nBaudRate = 115200; break;
                default: m_nBaudRate = 9600; break;
            }

            //  Data Bits 설정
            switch (Equipment.stCommunicationSet[(int)Equipment.CommList.Laser].Serial_CommDataBits)
            {
                case 0: m_nDataBits = 5; break;
                case 1: m_nDataBits = 6; break;
                case 2: m_nDataBits = 7; break;
                case 3: m_nDataBits = 8; break;
                default: m_nDataBits = 8; break;
            }

            //  Stop Bits 설정
            switch (Equipment.stCommunicationSet[(int)Equipment.CommList.Laser].Serial_CommStopBits)
            {
                case 0: m_stopBits = StopBits.One; break;
                case 1: m_stopBits = StopBits.OnePointFive; break;
                case 2: m_stopBits = StopBits.Two; break;
                default: m_stopBits = StopBits.One; break;
            }

            //  Parity 설정
            switch (Equipment.stCommunicationSet[(int)Equipment.CommList.Laser].Serial_CommParity)
            {
                case 0: m_parity = Parity.None; break;
                case 1: m_parity = Parity.Odd; break;
                case 2: m_parity = Parity.Even; break;
                default: m_parity = Parity.None; break;
            }

            //  Flow Control 설정
            switch (Equipment.stCommunicationSet[(int)Equipment.CommList.Laser].Serial_CommFlowControl)
            {
                case 0: m_handshake = Handshake.None; break;
                case 1: m_handshake = Handshake.XOnXOff; break;
                case 2: m_handshake = Handshake.RequestToSend; break;
                case 3: m_handshake = Handshake.RequestToSendXOnXOff; break;
                default: m_handshake = Handshake.None; break;
            }

            if (!Equipment.stCommunicationSet[(int)Equipment.CommList.Laser].Connect && !m_bRapidLxLaser_UserConnect)
                return;

            m_rapidLxLaser_Comm = new SerialCommRapidLxLaserPort();
            m_rapidLxLaser_Comm.DataReceivedHandler = RapidLxLaser_DataReceivedHandler;
            m_rapidLxLaser_Comm.DisconnectedHandler = RapidLxLaser_DisconnectedHandler;
            if (!m_rapidLxLaser_Comm.OpenComm(m_strPortName, m_nBaudRate, m_nDataBits, m_stopBits, m_parity, m_handshake))
            {
                string text = string.Format("{0} Port Open Failed! (Rapid LX Laser)", m_strPortName);
                MessageBox.Show(text);
            }

            //  포트 연결되면 데이터 읽기 시작
            m_nLaserCommStep = (int)LaserComm_Step.Start;
        }

        private void RapidLxLaser_DataReceivedHandler(byte[] receiveData)
        {
            //  Coherent Laser
            //  종단 코드 : CR.LF

            string @string = Encoding.Default.GetString(receiveData);

            if (m_bRapidLxLaser_CommData_Received)                              //  데이터를 받을 준비가 되어 있지 않으면 Out
                return;

            m_strRapidLxLaser_Comm_ReceivedData += @string;
            if (m_strRapidLxLaser_Comm_ReceivedData.Length >= 1)
            {
                if (m_strRapidLxLaser_Comm_ReceivedData.Length >= 2 && m_strRapidLxLaser_Comm_ReceivedData[m_strRapidLxLaser_Comm_ReceivedData.Length - 2] == '\r' && m_strRapidLxLaser_Comm_ReceivedData[m_strRapidLxLaser_Comm_ReceivedData.Length - 1] == '\n')
                {
                    m_bRapidLxLaser_CommData_Received = true;

                    //MessageBox.Show(m_strRapidLxLaser_Comm_ReceivedData);

                    //m_strRapidLxLaser_Comm_ReceivedData = "";
                }
            }
        }

        private void RapidLxLaser_DisconnectedHandler()
        {
            Console.WriteLine("Rapid LX Laser serial COM11 disconnected");
        }

