            m_strAmpData = m_dAmpRR.ToString();

            m_cSendCmd = new byte[9 + m_strAmpData.Length + 2];            //  9 + Data Length + 2 : 'RRAMPSET' + ' ' + AmpData + CR + LF

            m_cSendCmd[0] = (byte)'R';
