            m_cSendCmd[2] = (byte)'A';
            m_cSendCmd[3] = (byte)'M';
            m_cSendCmd[4] = (byte)'P';
            m_cSendCmd[5] = (byte)'S';
            m_cSendCmd[6] = (byte)'E';
            m_cSendCmd[7] = (byte)'T';
            m_cSendCmd[8] = (byte)' ';

            for (int i = 0; i < m_strAmpData.Length; i++)
            {
                m_cSendCmd[9 + i] = (byte)m_strAmpData[i];
            }

            m_cSendCmd[9 + m_strAmpData.Length] = chrCR;
            m_cSendCmd[9 + m_strAmpData.Length + 1] = chrLF;

            m_strSendData = Encoding.Default.GetString(m_cSendCmd);

            if (m_rapidLxLaser_Comm.IsOpen)
            {
                m_rapidLxLaser_Comm.Send(m_strSendData);
