        public bool LaserSensor_Socket_ReadValue ()             //  측정값 출력
        {
            //  측정값 출력
            //  지정한 한 개의 OUT 측정값을 출력.
            //  MS,m,x\r

            //  m : 측정값 취득 요구 옵션
            //  0 : 측정값만
            //  1 : 측정값 + 측정 결과 정보
            //  2 : 측정값 + 판정 결과
            //  3 : 측정값 + 측정 결과 정보+판정 결과
            //  4 : 카운트 값＋측정 값
            //  5 : 카운트 값＋측정 값＋측정 결과 정보
            //  6 : 카운트 값＋측정 값＋판정 결과
            //  7 : 카운트 값＋측정 값＋측정 결과 정보＋판정 결과

            //  x : 측정값 취득 대상 OUT 번호
            //  OUT 번호 : 1 ~ 8
           
            bool m_bRet = false;

            string m_strSendData = "";
            byte[] m_cSendCmd = null;

            m_cSendCmd = new byte[7];

            m_cSendCmd[0] = (byte)'M';
            m_cSendCmd[1] = (byte)'S';
            m_cSendCmd[2] = (byte)',';
            m_cSendCmd[3] = (byte)'0';
            m_cSendCmd[4] = (byte)',';
            m_cSendCmd[5] = (byte)'1';
            m_cSendCmd[6] = chrCR;

            if (m_SocketLaserHeightSensor.isConnected)
            {
                m_SocketLaserHeightSensor.Send(m_cSendCmd);
                m_bRet = true;
            }

            return m_bRet;
        }

