        public void MapData_Apply(int m_nMapDataType)
        {
            switch(m_nMapDataType)
            {
                case (int)nMapData_Type.MapData_Stage_Scanner:
                    if ((Stage != null) && (interpolator_Scanner != null))
                    {
                        Stage.Interpolator = interpolator_Scanner;
                    }
                    break;


                case (int)nMapData_Type.MapData_Stage_FineCam:
                    if ((Stage != null) && (interpolator_FineCam != null))
                    {
                        Stage.Interpolator = interpolator_FineCam;
                    }

                    break;


                case (int)nMapData_Type.MapData_Stage_CalPos_Scanner:
                    if ((Stage != null) && (interpolator_CalPos_Scanner != null))
                    {
                        Stage.Interpolator = interpolator_CalPos_Scanner;
                    }

                    break;


                case (int)nMapData_Type.MapData_Stage_CalPos_FineCam:
                    if ((Stage != null) && (interpolator_CalPos_FineCam != null))
                    {
                        Stage.Interpolator = interpolator_CalPos_FineCam;
                    }

                    break;
            }
        }

