                //        //MC_Func.MC_EStop(i);
                //    }

                //    if (!Equipment.User_QMC_Engineer)                   //  QMC 관리자가 아닐 경우에만 Home Flag 를 false 로
                //    {
                //        m_bHomeOK = false;                              //  안전센서 감지 시 무조건 장비 초기화 해야 함
                //    }

                //    if (!Equipment.User_QMC_Engineer && Config.ParamConfig.AreaSensor_ServoOff_Usage)           //  안전센서 감지 시 Servo Off 할 경우
                //    {
                //        for (int i = 0; i < (int)AxisAjinEnum.Max; i++)
                //        {
                //            MC_Func.MC_SetServoOnOff(i, false);
                //        }
                //    }
                //}
            }            


            switch (m_nHomeStep)
            {
                case (int)Home_Step.Start:
                    Log.Write("SLD-200", Equipment.User_Name, "Machine Initialize", "시작");

                    Equipment.MachineStop_byAlarm = false;

                    m_nHomeAxisCount = 0;
                    m_bHomeOK = false;
                    m_bHomeProgressForm_Close = false;

                    m_nTotalAxisCount = (int)LoaderParameter.MotionKey.Max + (int)UnloaderParameter.MotionKey.Max + (int)WorkStageParameter.MotionKey.Max;

                    loader.MC_Func.MC_MotorStop((int)LoaderParameter.AxisAjinEnum.Z0, 2000);
                    loader.MC_Func.MC_MotorStop((int)LoaderParameter.AxisAjinEnum.Z1, 2000);
                    loader.MC_Func.MC_MotorStop((int)LoaderParameter.AxisAjinEnum.TR_X, 2000);
                    loader.MC_Func.MC_MotorStop((int)LoaderParameter.AxisAjinEnum.TR_Z, 2000);
                    loader.MC_Func.MC_MotorStop((int)LoaderParameter.AxisAjinEnum.ALN_X, 2000);
                    loader.MC_Func.MC_MotorStop((int)LoaderParameter.AxisAjinEnum.ALN_Y, 2000);
                    unloader.MC_Func.MC_MotorStop((int)UnloaderParameter.AxisAjinEnum.Z0, 2000);
                    unloader.MC_Func.MC_MotorStop((int)UnloaderParameter.AxisAjinEnum.Z1, 2000);
                    unloader.MC_Func.MC_MotorStop((int)UnloaderParameter.AxisAjinEnum.TR_X, 2000);
                    unloader.MC_Func.MC_MotorStop((int)UnloaderParameter.AxisAjinEnum.TR_Z, 2000);
                    MC_Func.MC_MotorStop((int)WorkStageParameter.AxisAjinEnum.X, 2000);
                    MC_Func.MC_MotorStop((int)WorkStageParameter.AxisAjinEnum.Y, 2000);
                    MC_Func.MC_MotorStop((int)WorkStageParameter.AxisAjinEnum.Z, 2000);


                    //  Loader 파츠 사용 변수 초기화
                    loader.m_nLoaderTransferMoveType = (int)LoaderTransferMoveType.Cycle_None; //  Transfer Move Type
                    loader.m_nLoader_Transfer_Step = (int)Loader_Transfer_Step.None;
                    loader.m_nStacker0_ModulePickupWaitingPos_Step = (int)StackerModulePickupWaitingPos_Step.None;
                    loader.m_nStacker1_ModulePickupWaitingPos_Step = (int)StackerModulePickupWaitingPos_Step.None;
                    loader.m_nMAlign_Step = (int)MAlign_Step.None;

                    loader.m_bStacker0_Complete = false;
                    loader.m_bStacker1_Complete = false;

                    loader.m_bMAlignZone_ModuleExist = false;

                    loader.m_bLoader_Transfer_ModulePickUpfromStacker_Complete = false;                //  Stacker 에서 Module Pick Up 완료 여부
                    loader.m_bLoader_Transfer_ModulePickUpfromMAligner_Complete = false;               //  M-Aligner 에서 Module Pick Up 완료 여부
                    loader.m_bLoader_Transfer_ModulePutDowntoMAligner_Complete = false;                //  M-Aligner 에 Module Put Down 완료 여부
                    loader.m_bLoader_Transfer_ModulePutDowntoWorkStage_Complete = false;               //  Work Stage 에 Module Put Down 완료 여부

                    loader.m_bStacker0_Run_byUser = false;                     //  Stacker0 Module Pick Up Cycle
                    loader.m_bStacker1_Run_byUser = false;                     //  Stacker1 Module Pick Up Cycle

                    loader.m_bLD_LPort_Complete = false;                               //  L-Port 동작 완료 여부
                    loader.m_bLD_RPort_Complete = false;                               //  R-Port 동작 완료 여부
                    loader.m_bLD_TR_ModulePickUp_LPort_Complete = false;               //  Transfer L-Port Module Pick Up 동작 완료 여부
                    loader.m_bLD_TR_ModulePickUp_RPort_Complete = false;               //  Transfer R-Port Module Pick Up 동작 완료 여부
                    loader.m_bLD_TR_ModulePutDown_MAligner_Complete = false;           //  Transfer Module Put Down 동작 완료 여부
                    loader.m_bLD_MAligner_Exist = false;                               //  M-Aligner 로 Module Pick & Place
                    loader.m_bLD_MAlign_Complete = false;                              //  M-Aligner 동작 완료 여부
                    loader.m_bLD_TR_ModulePickUp_MAligner_Complete = false;            //  M-Aligner Module Pick Up 동작 완료 여부
                    loader.m_bLD_WorkStage_LoadingComplete = false;                    //  Work Stage 로 Module Loading 완료 여부


                    //  Unloader 파츠 사용 변수 초기화
                    unloader.m_nUnloader_Transfer_Step = (int)Unloader_Transfer_Step.None;
                    unloader.m_nStacker0_ModulePutdownWaitingPos_Step = (int)StackerModulePutdownWaitingPos_Step.None;
                    unloader.m_nStacker1_ModulePutdownWaitingPos_Step = (int)StackerModulePutdownWaitingPos_Step.None;

                    unloader.m_bStacker0_Complete = false;
                    unloader.m_bStacker1_Complete = false;

                    unloader.m_bUnloader_Transfer_ModulePickUpfromWorkStage_Complete = false;        //  Work Stage 에서 Module Pick Up 완료 여부
                    unloader.m_bUnloader_Transfer_ModulePutDowntoStacker0_Complete = false;          //  Stacker0 에 Module Put Down 완료 여부
                    unloader.m_bUnloader_Transfer_ModulePutDowntoStacker1_Complete = false;          //  Stacker1 에 Module Put Down 완료 여부
                    unloader.m_bUnloader_Transfer_ModulePutDowntoNG_Complete = false;                //  NG-Port 에 Module Put Down 완료 여부


                    //  Main 파츠 사용 변수 초기화
                    m_bMainWorkCycle_Complete = false;
                    m_bMainWorkCycle_ResultOK = false;
                    m_bMainWorkCycle_ResultOK_toRPort = true;
                    m_nMainWork_Step = (int)MainWork_Step.None;                                 //  Main Work Step
                    m_nMainWorkCycleType = (int)MainWorkCycleType.Cycle_None;                   //  자동 운전 시 사용하는 변수
                    m_bMainWorkCycle_DryRun = false;


                    loader.timer_LoaderWork.Enabled = false;



                    if (Equipment.Machine_LaserType_CO2)
                    {
                        MC_Func.MC_MotorStop((int)WorkStageParameter.AxisAjinEnum.MASK_Y, 2000);
                    }

                    m_nHomeStep = (int)Home_Step.AxisAlarmCheck;
                    break;


                case (int)Home_Step.AxisAlarmCheck:                                         //  서보 축 알람 체크

                    //  0 ~ 13 번 축 까지 있음. (0:Stage X,             1:Stage V,              2:Scanner Z,                3:Mask Y,
                    //                          4:Loader Stacker 0,     5:Loader Stacker 1,     6:Loader Transfer X,        7:Loader Transfer Z,        8:Align X, 9:Align Y,
                    //                          10:Unloader Stacker 0,  11:Unloader Stacker 1,  12:Unloader Transfer X,     13:Unloader Transfer Z)

                    if (m_nHomeAxisCount <= m_nTotalAxisCount)
                    {
                        if (MC_Func.MC_IsAlarm(m_nHomeAxisCount))
                        {
                            m_nHomeStep = (int)Home_Step.AlarmAxisServoOff;
                        }
                        else
                        {
                            MC_Func.MC_SetServoOnOff(m_nHomeAxisCount, true);
                            m_nHomeAxisCount++;
                        }
                    }
                    else
                    {
                        m_nHomeStep = (int)Home_Step.AlnX_01mm_Move;                        //  Aligner X축 0.1mm 이동 검증 시작
                    }
                    break;


                case (int)Home_Step.AlarmAxisServoOff:                                      //  알람 축 서보 Off
                    MC_Func.MC_SetServoOnOff(m_nHomeAxisCount, false);

                    m_nHomeStep = (int)Home_Step.AlarmAxisServoOffCheck;
                    break;


                case (int)Home_Step.AlarmAxisServoOffCheck:                                 //  알람 축 서보 Off 확인
                    if (!MC_Func.MC_IsServoOn(m_nHomeAxisCount))
                    {
                        TickCount_Start((int)TickType.TICK_HOME);

                        m_nHomeStep = (int)Home_Step.AlarmAxisAlarmResetOn;
                    }
                    break;


                case (int)Home_Step.AlarmAxisAlarmResetOn:                                  //  알람 축 리셋 신호 On
                    if (TickCount_Elapsed((int)TickType.TICK_HOME) > 300)
                    {
                        MC_Func.MC_AlarmReset(m_nHomeAxisCount, true);

                        TickCount_Start((int)TickType.TICK_HOME);

                        m_nHomeStep = (int)Home_Step.AlarmAxisAlarmResetOff;
                    }
                    break;


                case (int)Home_Step.AlarmAxisAlarmResetOff:                                 //  알람 축 리셋 신호 Off (30ms delay 후 Off)
                    if (TickCount_Elapsed((int)TickType.TICK_HOME) > 300)
                    {
                        MC_Func.MC_AlarmReset(m_nHomeAxisCount, false);

                        TickCount_Start((int)TickType.TICK_HOME);

                        m_nHomeStep = (int)Home_Step.AlarmAxisServoOn;
                    }
                    break;


                case (int)Home_Step.AlarmAxisServoOn:                                       //  알람 축 서보 On
                    if (TickCount_Elapsed((int)TickType.TICK_HOME) > 300)
                    {
                        MC_Func.MC_SetServoOnOff(m_nHomeAxisCount, true);

                        m_nHomeStep = (int)Home_Step.AlarmAxisServoOnCheck;
                    }
                    break;


                case (int)Home_Step.AlarmAxisServoOnCheck:                                  //  알람 축 서보 On 확인
                    if (MC_Func.MC_IsServoOn(m_nHomeAxisCount))
                    {
                        m_nHomeAxisCount++;

                        m_nHomeStep = (int)Home_Step.AxisAlarmCheck;
                    }
                    break;


                case (int)Home_Step.AlnX_01mm_Move:                                    //  Aligner X축 0.1mm 이동 시작

                    Log.Write("SLD-200", Equipment.User_Name, "Machine Initialize", "Aligner X 축 0.1mm 이동 시작");

                    loader.loaderParameter.stLoaderPosParam = loader.loaderParameter.GetPositionInformation("Ready");

                    //  Target 좌표 재설정 (현재 위치에서 0.1mm 이동
                    loader.loaderParameter.stLoaderPosParam.dTarget[(int)LoaderParameter.MotionKey.ALN_X] = loader.MC_Func.MC_GetEncPos((int)LoaderParameter.AxisAjinEnum.ALN_X) + 0.1;

                    MC_Func.MC_MovePosition((int)LoaderParameter.AxisAjinEnum.ALN_X,
                                        loader.loaderParameter.stLoaderPosParam.dTarget[(int)LoaderParameter.MotionKey.ALN_X],
                                        loader.loaderParameter.stLoaderPosParam.dVel[(int)LoaderParameter.MotionKey.ALN_X],
                                        loader.loaderParameter.stLoaderPosParam.dAcc[(int)LoaderParameter.MotionKey.ALN_X],
                                        loader.loaderParameter.stLoaderPosParam.dDec[(int)LoaderParameter.MotionKey.ALN_X]);

                    TickCount_Start((int)TickType.TICK_HOME);

                    m_nHomeStep = (int)Home_Step.AlnX_01mm_Move_DoneCheck;
                    break;


                case (int)Home_Step.AlnX_01mm_Move_DoneCheck:                          //  Aligner X축 0.1mm 이동 완료 확인

                    if ((TickCount_Elapsed((int)TickType.TICK_HOME) > 100) &&
                        MC_Func.MC_GetDone((int)LoaderParameter.AxisAjinEnum.ALN_X) && MC_Func.MC_PosTolerance((int)LoaderParameter.AxisAjinEnum.ALN_X, loader.loaderParameter.stLoaderPosParam.dTarget[(int)LoaderParameter.MotionKey.ALN_X]) &&
                        /*(loader.loaderParameter.stLoaderPosParam.dTarget[(int)LoaderParameter.MotionKey.ALN_X] >= (loader.MC_Func.MC_GetCmdPos((int)LoaderParameter.AxisAjinEnum.ALN_X) - 0.002)) &&
                        (loader.loaderParameter.stLoaderPosParam.dTarget[(int)LoaderParameter.MotionKey.ALN_X] <= (loader.MC_Func.MC_GetCmdPos((int)LoaderParameter.AxisAjinEnum.ALN_X) + 0.002)) &&*/
                        (loader.MC_Func.MC_GetCmdPos((int)LoaderParameter.AxisAjinEnum.ALN_X) >= (loader.MC_Func.MC_GetEncPos((int)LoaderParameter.AxisAjinEnum.ALN_X) - 0.002)) &&
                        (loader.MC_Func.MC_GetCmdPos((int)LoaderParameter.AxisAjinEnum.ALN_X) <= (loader.MC_Func.MC_GetEncPos((int)LoaderParameter.AxisAjinEnum.ALN_X) + 0.002)))
                    {
                        Log.Write("SLD-200", Equipment.User_Name, "Machine Initialize", "Aligner X 축 0.1mm 이동 완료");

                        m_nHomeStep = (int)Home_Step.MaskY_AlnXY_HomeStart;
                    }
                    else if (TickCount_Elapsed((int)TickType.TICK_HOME) >= 3000)
                    {
                        Log.Write("SLD-200", Equipment.User_Name, "Machine Initialize", "Aligner X 축 0.1mm 이동 검증 시간 초과. (Timeout)");

                        //  알람 정지 (LED Bar - Red Blink)
                        Equipment.MachineStop_byAlarm = true;

                        timer_Motion_Home.Enabled = false;
                        m_btimer_Motion_Home_Stop = true;

                        m_bHomeProgressForm_Close = true;

                        m_nHomeStep = (int)Home_Step.None;

                        MessageBox.Show("Aligner X 축 0.1mm 이동 검증 실패.\r\n\r\n[장비 초기화 금지!!  지령값 확인 필요!!!]", "Error", MessageBoxButtons.OK, MessageBoxIcon.Error);
                    }
                    break;


                case (int)Home_Step.MaskY_AlnXY_HomeStart:                                  //  Mask Y, Aligner XY축 홈 실행

                    Log.Write("SLD-200", Equipment.User_Name, "Machine Initialize", "MaskY, Aligner XY 축 초기화 시작");

                    if (Equipment.Machine_LaserType_CO2)
                    {
                        MC_Func.MC_HomeSearch((int)WorkStageParameter.AxisAjinEnum.MASK_Y);
                    }

                    MC_Func.MC_HomeSearch((int)LoaderParameter.AxisAjinEnum.ALN_X);
                    MC_Func.MC_HomeSearch((int)LoaderParameter.AxisAjinEnum.ALN_Y);

                    TickCount_Start((int)TickType.TICK_HOME);

                    m_nHomeStep = (int)Home_Step.MaskY_AlnXY_HomeCompleteCheck;
                    break;


                case (int)Home_Step.MaskY_AlnXY_HomeCompleteCheck:                          //  Mask Y, Aligner XY축 홈 완료 체크

                    if ((TickCount_Elapsed((int)TickType.TICK_HOME) > 100) &&

                        (!Equipment.Machine_LaserType_CO2 ||
                        (Equipment.Machine_LaserType_CO2 && !MC_Func.MC_GetHoming((int)WorkStageParameter.AxisAjinEnum.MASK_Y) && MC_Func.MC_GetInposition((int)WorkStageParameter.AxisAjinEnum.MASK_Y))) &&

                        !MC_Func.MC_GetHoming((int)LoaderParameter.AxisAjinEnum.ALN_X) && MC_Func.MC_GetInposition((int)LoaderParameter.AxisAjinEnum.ALN_X) &&
                        !MC_Func.MC_GetHoming((int)LoaderParameter.AxisAjinEnum.ALN_Y) && MC_Func.MC_GetInposition((int)LoaderParameter.AxisAjinEnum.ALN_Y))
                    {
                        Log.Write("SLD-200", Equipment.User_Name, "Machine Initialize", "MaskY, Aligner XY 축 초기화 완료");

                        m_nHomeStep = (int)Home_Step.ScannerZ_TransferZ_HomeStart;
                    }
                    else if (TickCount_Elapsed((int)TickType.TICK_HOME) > 60000)
                    {
                        Log.Write("SLD-200", Equipment.User_Name, "Machine Initialize", "MaskY, Aligner XY 축 초기화 실패. (Timeout)");

                        //  알람 정지 (LED Bar - Red Blink)
                        Equipment.MachineStop_byAlarm = true;

                        timer_Motion_Home.Enabled = false;
                        m_btimer_Motion_Home_Stop = true;

                        m_bHomeProgressForm_Close = true;

                        m_nHomeStep = (int)Home_Step.None;

                        MessageBox.Show("MaskY, Aligner XY 축 초기화 실패", "Error", MessageBoxButtons.OK, MessageBoxIcon.Error);
                    }
                    break;


                case (int)Home_Step.ScannerZ_TransferZ_HomeStart:                           //  Scanner Z 축, Loader Z 축, Unloader Z 축 홈 실행

                    Log.Write("SLD-200", Equipment.User_Name, "Machine Initialize", "Scanner, LD, UL Z 축 초기화 시작");

                    MC_Func.MC_HomeSearch((int)WorkStageParameter.AxisAjinEnum.Z);
                    MC_Func.MC_HomeSearch((int)LoaderParameter.AxisAjinEnum.TR_Z);
                    MC_Func.MC_HomeSearch((int)UnloaderParameter.AxisAjinEnum.TR_Z);

                    TickCount_Start((int)TickType.TICK_HOME);

                    m_nHomeStep = (int)Home_Step.ScannerZ_TransferZ_HomeCompleteCheck;
                    break;


                case (int)Home_Step.ScannerZ_TransferZ_HomeCompleteCheck:                   //  Scanner Z 축, Loader Z 축, Unloader Z 축 홈 완료 체크

                    if ((TickCount_Elapsed((int)TickType.TICK_HOME) > 100) &&
                        !MC_Func.MC_GetHoming((int)WorkStageParameter.AxisAjinEnum.Z) && MC_Func.MC_GetInposition((int)WorkStageParameter.AxisAjinEnum.Z) &&
                        !MC_Func.MC_GetHoming((int)LoaderParameter.AxisAjinEnum.TR_Z) && MC_Func.MC_GetInposition((int)LoaderParameter.AxisAjinEnum.TR_Z) &&
                        !MC_Func.MC_GetHoming((int)UnloaderParameter.AxisAjinEnum.TR_Z) && MC_Func.MC_GetInposition((int)UnloaderParameter.AxisAjinEnum.TR_Z) )
                    {
                        Log.Write("SLD-200", Equipment.User_Name, "Machine Initialize", "Scanner, LD, UL Z 축 초기화 완료");

                        m_nHomeStep = (int)Home_Step.Remained_AllAxis_HomeStart;
                    }
                    else if (TickCount_Elapsed((int)TickType.TICK_HOME) > 60000)
                    {
                        Log.Write("SLD-200", Equipment.User_Name, "Machine Initialize", "Scanner, LD, UL Z 축 초기화 실패. (Timeout)");

                        //  알람 정지 (LED Bar - Red Blink)
                        Equipment.MachineStop_byAlarm = true;

                        timer_Motion_Home.Enabled = false;
                        m_btimer_Motion_Home_Stop = true;

                        m_bHomeProgressForm_Close = true;

                        m_nHomeStep = (int)Home_Step.None;

                        MessageBox.Show("Scanner, LD, UL Z 축 초기화 실패", "Error", MessageBoxButtons.OK, MessageBoxIcon.Error);
                    }
                    break;


                case (int)Home_Step.Remained_AllAxis_HomeStart:                             //  나머지 축 전체 홈 실행

                    Log.Write("SLD-200", Equipment.User_Name, "Machine Initialize", "나머지 축 전체 초기화 시작");

                    MC_Func.MC_HomeSearch((int)WorkStageParameter.AxisAjinEnum.X);
                    MC_Func.MC_HomeSearch((int)WorkStageParameter.AxisAjinEnum.Y);
                    //MC_Func.MC_HomeSearch((int)WorkStageParameter.AxisAjinEnum.MASK_Y);

                    MC_Func.MC_HomeSearch((int)LoaderParameter.AxisAjinEnum.Z0);
                    MC_Func.MC_HomeSearch((int)LoaderParameter.AxisAjinEnum.Z1);
                    MC_Func.MC_HomeSearch((int)LoaderParameter.AxisAjinEnum.TR_X);
                    //MC_Func.MC_HomeSearch((int)LoaderParameter.AxisAjinEnum.ALN_X);
                    //MC_Func.MC_HomeSearch((int)LoaderParameter.AxisAjinEnum.ALN_Y);

                    MC_Func.MC_HomeSearch((int)UnloaderParameter.AxisAjinEnum.Z0);
                    MC_Func.MC_HomeSearch((int)UnloaderParameter.AxisAjinEnum.Z1);
                    MC_Func.MC_HomeSearch((int)UnloaderParameter.AxisAjinEnum.TR_X);

                    TickCount_Start((int)TickType.TICK_HOME);

                    m_nHomeStep = (int)Home_Step.Remained_AllAxis_HomeCompleteCheck;
                    break;


                case (int)Home_Step.Remained_AllAxis_HomeCompleteCheck:                     //  나머지 축 전체 홈 완료 체크

                    if ((TickCount_Elapsed((int)TickType.TICK_HOME) > 100) &&
                        !MC_Func.MC_GetHoming((int)WorkStageParameter.AxisAjinEnum.X) && MC_Func.MC_GetInposition((int)WorkStageParameter.AxisAjinEnum.X) &&
                        !MC_Func.MC_GetHoming((int)WorkStageParameter.AxisAjinEnum.Y) && MC_Func.MC_GetInposition((int)WorkStageParameter.AxisAjinEnum.Y) &&
                        //!MC_Func.MC_GetHoming((int)WorkStageParameter.AxisAjinEnum.MASK_Y) && MC_Func.MC_GetInposition((int)WorkStageParameter.AxisAjinEnum.MASK_Y) &&

                        !MC_Func.MC_GetHoming((int)LoaderParameter.AxisAjinEnum.Z0) && MC_Func.MC_GetInposition((int)LoaderParameter.AxisAjinEnum.Z0) &&
                        !MC_Func.MC_GetHoming((int)LoaderParameter.AxisAjinEnum.Z1) && MC_Func.MC_GetInposition((int)LoaderParameter.AxisAjinEnum.Z1) &&
                        !MC_Func.MC_GetHoming((int)LoaderParameter.AxisAjinEnum.TR_X) && MC_Func.MC_GetInposition((int)LoaderParameter.AxisAjinEnum.TR_X) &&
                        //!MC_Func.MC_GetHoming((int)LoaderParameter.AxisAjinEnum.ALN_X) && MC_Func.MC_GetInposition((int)LoaderParameter.AxisAjinEnum.ALN_X) &&
                        //!MC_Func.MC_GetHoming((int)LoaderParameter.AxisAjinEnum.ALN_Y) && MC_Func.MC_GetInposition((int)LoaderParameter.AxisAjinEnum.ALN_Y) &&

                        !MC_Func.MC_GetHoming((int)UnloaderParameter.AxisAjinEnum.Z0) && MC_Func.MC_GetInposition((int)UnloaderParameter.AxisAjinEnum.Z0) &&
                        !MC_Func.MC_GetHoming((int)UnloaderParameter.AxisAjinEnum.Z1) && MC_Func.MC_GetInposition((int)UnloaderParameter.AxisAjinEnum.Z1) &&
                        !MC_Func.MC_GetHoming((int)UnloaderParameter.AxisAjinEnum.TR_X) && MC_Func.MC_GetInposition((int)UnloaderParameter.AxisAjinEnum.TR_X))
                    {
                        Log.Write("SLD-200", Equipment.User_Name, "Machine Initialize", "나머지 축 전체 초기화 완료");

                        m_bHomeOK = true;

                        //m_nHomeStep = (int)Home_Step.All_Z_Move_ReadyPos;             //  나중에 살리자
                        //m_nHomeStep = (int)Home_Step.Complete;
                        m_nHomeStep = (int)Home_Step.MachineCoordinateMatching;         //  Stage 좌표계와 Scanner 좌표계 일치화 시작
                    }
                    else if (TickCount_Elapsed((int)TickType.TICK_HOME) > 120000)
                    {
                        Log.Write("SLD-200", Equipment.User_Name, "Machine Initialize", "나머지 축 전체 초기화 실패. (Timeout)");

                        //  알람 정지 (LED Bar - Red Blink)
                        Equipment.MachineStop_byAlarm = true;

                        timer_Motion_Home.Enabled = false;
                        m_btimer_Motion_Home_Stop = true;

                        m_bHomeProgressForm_Close = true;

                        m_nHomeStep = (int)Home_Step.None;

                        MessageBox.Show("나머지 축 전체 초기화 실패", "Error", MessageBoxButtons.OK, MessageBoxIcon.Error);
                    }
                    break;


                case (int)Home_Step.MachineCoordinateMatching:                                      //  기계 좌표계 매칭 (Stage 와 Scanner 일치)

                    Log.Write("SLD-200", Equipment.User_Name, "Machine Initialize", "스테이지 좌표계와 스캐너 좌표계 매칭 시작");

                    if (Equipment.CoordinateMatchingOffset_X != 0.0)
                    {
                        MC_Func.MC_SetEncPos((int)WorkStageParameter.AxisAjinEnum.X, -Equipment.CoordinateMatchingOffset_X);
                        MC_Func.MC_SetCmdPos((int)WorkStageParameter.AxisAjinEnum.X, -Equipment.CoordinateMatchingOffset_X);
                    }

                    if (Equipment.CoordinateMatchingOffset_Y != 0.0)
                    {
                        MC_Func.MC_SetEncPos((int)WorkStageParameter.AxisAjinEnum.Y, -Equipment.CoordinateMatchingOffset_Y);
                        MC_Func.MC_SetCmdPos((int)WorkStageParameter.AxisAjinEnum.Y, -Equipment.CoordinateMatchingOffset_Y);
                    }

                    TickCount_Start((int)TickType.TICK_HOME);

                    m_nHomeStep = (int)Home_Step.MachineCoordinateMatching_Check;
                    break;


                case (int)Home_Step.MachineCoordinateMatching_Check:                                //  기계 좌표계 매칭 (Stage 와 Scanner 일치) 완료 확인

                    if (TickCount_Elapsed((int)TickType.TICK_HOME) > 500)
                    {
                        Log.Write("SLD-200", Equipment.User_Name, "Machine Initialize", "스테이지 좌표계와 스캐너 좌표계 매칭 완료");

                        //m_nHomeStep = (int)Home_Step.All_Z_Move_ReadyPos;             //  나중에 살리자
                        m_nHomeStep = (int)Home_Step.Complete;
                    }
                    break;


                case (int)Home_Step.All_Z_Move_ReadyPos:                                    //  전체 Z 축, 대기 위치로 이동

                    Log.Write("SLD-200", Equipment.User_Name, "Machine Initialize", "전체 Z 축, 대기 위치로 이동 시작");

                    workStageParameter.stWorkStagePosParam = workStageParameter.GetPositionInformation("Ready");
                    loader.loaderParameter.stLoaderPosParam = loader.loaderParameter.GetPositionInformation("Ready");
                    unloader.unloaderParameter.stUnloaderPosParam = unloader.unloaderParameter.GetPositionInformation("Ready");

                    //  Target 좌표 재설정
                    workStageParameter.stWorkStagePosParam.dTarget[(int)WorkStageParameter.MotionKey.Z] = vision.stVisionTeachingPos[(int)Vision.Vision_TeachingPosList.Vision_SafetyPos].Vision_Z;
                    loader.loaderParameter.stLoaderPosParam.dTarget[(int)LoaderParameter.MotionKey.TR_Z] = loader.stLDULTeachingPos[(int)Loader.LDUL_TeachingPosList.LD_TR_SafetyPos].LD_Transfer_Z;
                    unloader.unloaderParameter.stUnloaderPosParam.dTarget[(int)UnloaderParameter.MotionKey.TR_Z] = loader.stLDULTeachingPos[(int)Loader.LDUL_TeachingPosList.UL_TR_SafetyPos].UL_Transfer_Z;

                    MC_Func.MC_MovePosition((int)WorkStageParameter.AxisAjinEnum.Z,
                                        workStageParameter.stWorkStagePosParam.dTarget[(int)WorkStageParameter.MotionKey.Z],
                                        workStageParameter.stWorkStagePosParam.dVel[(int)WorkStageParameter.MotionKey.Z],
                                        workStageParameter.stWorkStagePosParam.dAcc[(int)WorkStageParameter.MotionKey.Z],
                                        workStageParameter.stWorkStagePosParam.dDec[(int)WorkStageParameter.MotionKey.Z]);

                    MC_Func.MC_MovePosition((int)LoaderParameter.AxisAjinEnum.TR_Z,
                                        loader.loaderParameter.stLoaderPosParam.dTarget[(int)LoaderParameter.MotionKey.TR_Z],
                                        loader.loaderParameter.stLoaderPosParam.dVel[(int)LoaderParameter.MotionKey.TR_Z],
                                        loader.loaderParameter.stLoaderPosParam.dAcc[(int)LoaderParameter.MotionKey.TR_Z],
                                        loader.loaderParameter.stLoaderPosParam.dDec[(int)LoaderParameter.MotionKey.TR_Z]);

                    MC_Func.MC_MovePosition((int)UnloaderParameter.AxisAjinEnum.TR_Z,
                                        unloader.unloaderParameter.stUnloaderPosParam.dTarget[(int)UnloaderParameter.MotionKey.TR_Z],
                                        unloader.unloaderParameter.stUnloaderPosParam.dVel[(int)UnloaderParameter.MotionKey.TR_Z],
                                        unloader.unloaderParameter.stUnloaderPosParam.dAcc[(int)UnloaderParameter.MotionKey.TR_Z],
                                        unloader.unloaderParameter.stUnloaderPosParam.dDec[(int)UnloaderParameter.MotionKey.TR_Z]);

                    TickCount_Start((int)TickType.TICK_HOME);

                    m_nHomeStep = (int)Home_Step.All_Z_Move_ReadyPos_DoneCheck;
                    break;


                case (int)Home_Step.All_Z_Move_ReadyPos_DoneCheck:                          //  전체 Z 축, 대기 위치로 이동 완료 확인

                    if (MC_Func.MC_GetDone((int)WorkStageParameter.AxisAjinEnum.Z) && MC_Func.MC_PosTolerance((int)WorkStageParameter.AxisAjinEnum.Z, workStageParameter.stWorkStagePosParam.dTarget[(int)WorkStageParameter.MotionKey.Z]) &&
                        MC_Func.MC_GetDone((int)LoaderParameter.AxisAjinEnum.TR_Z) && MC_Func.MC_PosTolerance((int)LoaderParameter.AxisAjinEnum.TR_Z, loader.loaderParameter.stLoaderPosParam.dTarget[(int)LoaderParameter.MotionKey.TR_Z]) &&
                        MC_Func.MC_GetDone((int)UnloaderParameter.AxisAjinEnum.TR_Z) && MC_Func.MC_PosTolerance((int)UnloaderParameter.AxisAjinEnum.TR_Z, unloader.unloaderParameter.stUnloaderPosParam.dTarget[(int)UnloaderParameter.MotionKey.TR_Z]) )
                    {
                        Log.Write("SLD-200", Equipment.User_Name, "Machine Initialize", "전체 Z 축, 대기 위치로 이동 완료");

                        m_nHomeStep = (int)Home_Step.All_XY_Move_ReadyPos;
                    }
                    else if (TickCount_Elapsed((int)TickType.TICK_HOME) >= 10000)
                    {
                        Log.Write("SLD-200", Equipment.User_Name, "Machine Initialize", "전체 Z 축, 대기 위치로 이동 시간 초과. (Timeout)");

                        //  알람 정지 (LED Bar - Red Blink)
                        Equipment.MachineStop_byAlarm = true;

                        timer_Motion_Home.Enabled = false;
                        m_btimer_Motion_Home_Stop = true;

                        m_bHomeProgressForm_Close = true;

                        m_nHomeStep = (int)Home_Step.None;

                        MessageBox.Show("전체 Z 축, Ready 위치로 이동 실패.", "Error", MessageBoxButtons.OK, MessageBoxIcon.Error);
                    }
                    break;


                case (int)Home_Step.All_XY_Move_ReadyPos:                                    //  전체 XY 축 대기 위치로 이동

                    Log.Write("SLD-200", Equipment.User_Name, "Machine Initialize", "전체 XY 축, 대기 위치로 이동 시작");

                    workStageParameter.stWorkStagePosParam = workStageParameter.GetPositionInformation("Ready");
                    bds.bdsParameter.stBdsPosParam = bds.bdsParameter.GetPositionInformation("Ready");
                    loader.loaderParameter.stLoaderPosParam = loader.loaderParameter.GetPositionInformation("Ready");
                    unloader.unloaderParameter.stUnloaderPosParam = unloader.unloaderParameter.GetPositionInformation("Ready");

                    //  Target 좌표 재설정
                    workStageParameter.stWorkStagePosParam.dTarget[(int)WorkStageParameter.MotionKey.X] = stWorkStageTeachingPos[(int)WorkStage.WorkStage_TeachingPosList.STAGE_SafetyPos].Stage_X;
                    workStageParameter.stWorkStagePosParam.dTarget[(int)WorkStageParameter.MotionKey.Y] = stWorkStageTeachingPos[(int)WorkStage.WorkStage_TeachingPosList.STAGE_SafetyPos].Stage_Y;

                    if (Equipment.Machine_LaserType_CO2)
                    {
                        bds.bdsParameter.stBdsPosParam.dTarget[(int)BdsParameter.MotionKey.MASK_Y] = bds.stBDSTeachingPos[(int)Bds.BDS_TeachingPosList.BDS_NoneMarkPos].Mask_Y;
                    }

                    loader.loaderParameter.stLoaderPosParam.dTarget[(int)LoaderParameter.MotionKey.TR_X] = loader.stLDULTeachingPos[(int)Loader.LDUL_TeachingPosList.LD_TR_SafetyPos].LD_Transfer_X;
                    loader.loaderParameter.stLoaderPosParam.dTarget[(int)LoaderParameter.MotionKey.ALN_X] = loader.stLDULTeachingPos[(int)Loader.LDUL_TeachingPosList.MAligner_OpenPos].MAligner_X;
                    loader.loaderParameter.stLoaderPosParam.dTarget[(int)LoaderParameter.MotionKey.ALN_Y] = loader.stLDULTeachingPos[(int)Loader.LDUL_TeachingPosList.MAligner_OpenPos].MAligner_Y;
                    unloader.unloaderParameter.stUnloaderPosParam.dTarget[(int)UnloaderParameter.MotionKey.TR_X] = loader.stLDULTeachingPos[(int)Loader.LDUL_TeachingPosList.UL_TR_SafetyPos].UL_Transfer_X;

                    MC_Func.MC_MovePosition((int)WorkStageParameter.AxisAjinEnum.X,
                                        workStageParameter.stWorkStagePosParam.dTarget[(int)WorkStageParameter.MotionKey.X],
                                        workStageParameter.stWorkStagePosParam.dVel[(int)WorkStageParameter.MotionKey.X],
                                        workStageParameter.stWorkStagePosParam.dAcc[(int)WorkStageParameter.MotionKey.X],
                                        workStageParameter.stWorkStagePosParam.dDec[(int)WorkStageParameter.MotionKey.X]);

                    MC_Func.MC_MovePosition((int)WorkStageParameter.AxisAjinEnum.Y,
                                        workStageParameter.stWorkStagePosParam.dTarget[(int)WorkStageParameter.MotionKey.Y],
                                        workStageParameter.stWorkStagePosParam.dVel[(int)WorkStageParameter.MotionKey.Y],
                                        workStageParameter.stWorkStagePosParam.dAcc[(int)WorkStageParameter.MotionKey.Y],
                                        workStageParameter.stWorkStagePosParam.dDec[(int)WorkStageParameter.MotionKey.Y]);

                    if (Equipment.Machine_LaserType_CO2)
                    {
                        MC_Func.MC_MovePosition((int)BdsParameter.AxisAjinEnum.MASK_Y,
                                        bds.bdsParameter.stBdsPosParam.dTarget[(int)BdsParameter.MotionKey.MASK_Y],
                                        bds.bdsParameter.stBdsPosParam.dVel[(int)BdsParameter.MotionKey.MASK_Y],
                                        bds.bdsParameter.stBdsPosParam.dAcc[(int)BdsParameter.MotionKey.MASK_Y],
                                        bds.bdsParameter.stBdsPosParam.dDec[(int)BdsParameter.MotionKey.MASK_Y]);
                    }

                    MC_Func.MC_MovePosition((int)LoaderParameter.AxisAjinEnum.TR_X,
                                        loader.loaderParameter.stLoaderPosParam.dTarget[(int)LoaderParameter.MotionKey.TR_X],
                                        loader.loaderParameter.stLoaderPosParam.dVel[(int)LoaderParameter.MotionKey.TR_X],
                                        loader.loaderParameter.stLoaderPosParam.dAcc[(int)LoaderParameter.MotionKey.TR_X],
                                        loader.loaderParameter.stLoaderPosParam.dDec[(int)LoaderParameter.MotionKey.TR_X]);

                    MC_Func.MC_MovePosition((int)LoaderParameter.AxisAjinEnum.ALN_X,
                                        loader.loaderParameter.stLoaderPosParam.dTarget[(int)LoaderParameter.MotionKey.ALN_X],
                                        loader.loaderParameter.stLoaderPosParam.dVel[(int)LoaderParameter.MotionKey.ALN_X],
                                        loader.loaderParameter.stLoaderPosParam.dAcc[(int)LoaderParameter.MotionKey.ALN_X],
                                        loader.loaderParameter.stLoaderPosParam.dDec[(int)LoaderParameter.MotionKey.ALN_X]);

                    MC_Func.MC_MovePosition((int)LoaderParameter.AxisAjinEnum.ALN_Y,
                                        loader.loaderParameter.stLoaderPosParam.dTarget[(int)LoaderParameter.MotionKey.ALN_Y],
                                        loader.loaderParameter.stLoaderPosParam.dVel[(int)LoaderParameter.MotionKey.ALN_Y],
                                        loader.loaderParameter.stLoaderPosParam.dAcc[(int)LoaderParameter.MotionKey.ALN_Y],
                                        loader.loaderParameter.stLoaderPosParam.dDec[(int)LoaderParameter.MotionKey.ALN_Y]);

                    MC_Func.MC_MovePosition((int)UnloaderParameter.AxisAjinEnum.TR_X,
                                        unloader.unloaderParameter.stUnloaderPosParam.dTarget[(int)UnloaderParameter.MotionKey.TR_X],
                                        unloader.unloaderParameter.stUnloaderPosParam.dVel[(int)UnloaderParameter.MotionKey.TR_X],
                                        unloader.unloaderParameter.stUnloaderPosParam.dAcc[(int)UnloaderParameter.MotionKey.TR_X],
                                        unloader.unloaderParameter.stUnloaderPosParam.dDec[(int)UnloaderParameter.MotionKey.TR_X]);

                    TickCount_Start((int)TickType.TICK_HOME);

                    m_nHomeStep = (int)Home_Step.All_XY_Move_ReadyPos_DoneCheck;
                    break;


                case (int)Home_Step.All_XY_Move_ReadyPos_DoneCheck:                          //  전체 XY 축 대기 위치로 이동 완료 확인

                    if (MC_Func.MC_GetDone((int)WorkStageParameter.AxisAjinEnum.X) && MC_Func.MC_PosTolerance((int)WorkStageParameter.AxisAjinEnum.X, workStageParameter.stWorkStagePosParam.dTarget[(int)WorkStageParameter.MotionKey.X]) &&
                        MC_Func.MC_GetDone((int)WorkStageParameter.AxisAjinEnum.Y) && MC_Func.MC_PosTolerance((int)WorkStageParameter.AxisAjinEnum.Y, workStageParameter.stWorkStagePosParam.dTarget[(int)WorkStageParameter.MotionKey.Y]) &&

                        (!Equipment.Machine_LaserType_CO2 || 
                        (Equipment.Machine_LaserType_CO2 && MC_Func.MC_GetDone((int)BdsParameter.AxisAjinEnum.MASK_Y) && MC_Func.MC_PosTolerance((int)BdsParameter.AxisAjinEnum.MASK_Y, bds.bdsParameter.stBdsPosParam.dTarget[(int)BdsParameter.MotionKey.MASK_Y]))) &&

                        MC_Func.MC_GetDone((int)LoaderParameter.AxisAjinEnum.TR_X) && MC_Func.MC_PosTolerance((int)LoaderParameter.AxisAjinEnum.TR_X, loader.loaderParameter.stLoaderPosParam.dTarget[(int)LoaderParameter.MotionKey.TR_X]) &&
                        MC_Func.MC_GetDone((int)LoaderParameter.AxisAjinEnum.ALN_X) && MC_Func.MC_PosTolerance((int)LoaderParameter.AxisAjinEnum.ALN_X, loader.loaderParameter.stLoaderPosParam.dTarget[(int)LoaderParameter.MotionKey.ALN_X]) &&
                        MC_Func.MC_GetDone((int)LoaderParameter.AxisAjinEnum.ALN_Y) && MC_Func.MC_PosTolerance((int)LoaderParameter.AxisAjinEnum.ALN_Y, loader.loaderParameter.stLoaderPosParam.dTarget[(int)LoaderParameter.MotionKey.ALN_Y]) &&
                        MC_Func.MC_GetDone((int)UnloaderParameter.AxisAjinEnum.TR_X) && MC_Func.MC_PosTolerance((int)UnloaderParameter.AxisAjinEnum.TR_X, unloader.unloaderParameter.stUnloaderPosParam.dTarget[(int)UnloaderParameter.MotionKey.TR_X]))
                    {
                        Log.Write("SLD-200", Equipment.User_Name, "Machine Initialize", "전체 XY 축, 대기 위치로 이동 완료");

                        m_nHomeStep = (int)Home_Step.All_StackerZ_Move_ReadyPos;
                    }
                    else if (TickCount_Elapsed((int)TickType.TICK_HOME) >= 10000)
                    {
                        Log.Write("SLD-200", Equipment.User_Name, "Machine Initialize", "전체 XY 축, 대기 위치로 이동 시간 초과. (Timeout)");

                        //  알람 정지 (LED Bar - Red Blink)
                        Equipment.MachineStop_byAlarm = true;

                        timer_Motion_Home.Enabled = false;
                        m_btimer_Motion_Home_Stop = true;

                        m_bHomeProgressForm_Close = true;

                        m_nHomeStep = (int)Home_Step.None;

                        MessageBox.Show("전체 XY 축, Ready 위치로 이동 실패.", "Error", MessageBoxButtons.OK, MessageBoxIcon.Error);
                    }
                    break;


                case (int)Home_Step.All_StackerZ_Move_ReadyPos:                             //  전체 Stacker 축 모듈 PickUp, PutDown 높이로 이동 

                    Log.Write("SLD-200", Equipment.User_Name, "Machine Initialize", "Stacker Z 축, Module PickUp & PutDown 위치로 이동 시작");

                    //  Cycle 동작 시작
                    loader.timer_LoaderWork.Enabled = false;                            //  Loader 
                    unloader.timer_UnloaderWork.Enabled = false;                        //  Unloader

                    loader.m_nStacker0_ModulePickupWaitingPos_Step = (int)StackerModulePickupWaitingPos_Step.None;
                    loader.m_nStacker1_ModulePickupWaitingPos_Step = (int)StackerModulePickupWaitingPos_Step.None;
                    unloader.m_nStacker0_ModulePutdownWaitingPos_Step = (int)StackerModulePickupWaitingPos_Step.None;
                    unloader.m_nStacker1_ModulePutdownWaitingPos_Step = (int)StackerModulePickupWaitingPos_Step.None;

                    loader.timer_LoaderWork.Enabled = true;                             //  Loader 
                    unloader.timer_UnloaderWork.Enabled = true;                         //  Unloader

                    TickCount_Start((int)TickType.TICK_HOME);

                    m_nHomeStep = (int)Home_Step.All_StackerZ_Move_ReadyPos_DoneCheck;
                    break;


                case (int)Home_Step.All_StackerZ_Move_ReadyPos_DoneCheck:                   //  전체 Stacker 축 모듈 PickUp, PutDown 높이로 이동 완료 체크

                    if ((TickCount_Elapsed((int)TickType.TICK_HOME) > 100) &&
                        (loader.m_nStacker0_ModulePickupWaitingPos_Step == (int)StackerModulePickupWaitingPos_Step.None) &&
                        (loader.m_nStacker1_ModulePickupWaitingPos_Step == (int)StackerModulePickupWaitingPos_Step.None) &&
                        MC_Func.MC_GetDone((int)LoaderParameter.AxisAjinEnum.Z0) && MC_Func.MC_GetDone((int)LoaderParameter.AxisAjinEnum.Z1) &&
                        (unloader.m_nStacker0_ModulePutdownWaitingPos_Step == (int)StackerModulePickupWaitingPos_Step.None) &&
                        (unloader.m_nStacker1_ModulePutdownWaitingPos_Step == (int)StackerModulePickupWaitingPos_Step.None) &&
                        MC_Func.MC_GetDone((int)UnloaderParameter.AxisAjinEnum.Z0) && MC_Func.MC_GetDone((int)UnloaderParameter.AxisAjinEnum.Z1))
                    {
                        Log.Write("SLD-200", Equipment.User_Name, "Stacker Z 축, Module PickUp & PutDown 위치로 이동 완료");

                        m_nHomeStep = (int)Home_Step.Complete;
                    }
                    else if (TickCount_Elapsed((int)TickType.TICK_HOME) > 60000)
                    {
                        Log.Write("SLD-200", Equipment.User_Name, "Stacker Z 축, Module PickUp & PutDown 위치로 이동 실패. (Timeout)");

                        //  알람 정지 (LED Bar - Red Blink)
                        Equipment.MachineStop_byAlarm = true;

                        timer_Motion_Home.Enabled = false;
                        m_btimer_Motion_Home_Stop = true;

                        m_bHomeProgressForm_Close = true;

                        m_nHomeStep = (int)Home_Step.None;

                        MessageBox.Show("Stacker Z 축, Module PickUp & PutDown 위치로 이동 실패", "Error", MessageBoxButtons.OK, MessageBoxIcon.Error);
                    }
                    break;


                case (int)Home_Step.Complete:

                    Log.Write("SLD-200", Equipment.User_Name, "Machine Initialize", "완료");

                    m_bHomeOK = true;
                    m_bHomeProgressForm_Close = true;

                    timer_Motion_Home.Enabled = false;
                    m_btimer_Motion_Home_Stop = true;

                    //  Sub Work 타이머
                    m_btimer_SubWork_Stop = false;
                    timer_SubWork.Enabled = true;

                    //  Comm. 타이머
                    m_btimer_Comm_Stop = false;
                    timer_Comm.Enabled = true;

                    m_strTemp = "===  장비 초기화 완료  ===";

                    m_nHomeStep = (int)Home_Step.None;

                    MessageBox.Show(m_strTemp, "Information!", MessageBoxButtons.OK, MessageBoxIcon.Information);
                    break;
            }
        }
        #endregion



        #region Work Stage Move Function

        //public enum WorkStageMoveType : int
        //{
        //    MoveTo_None = -1,                                                //  Move Type None
        //    MoveTo_LoadingPos = 0,                                          //  Module Loading Pos Move
        //    MoveTo_UnloadingPos,                                            //  Module Unloading Pos Move
        //    MoveTo_GlassCleaningPos,                                        //  Scanner Lens Glass Cleaning Pos Move
        //    MoveTo_CalSheetChangePos,                                       //  Scanner Cal-Sheet Change Pos Move
        //    MoveTo_ScannerCenterPos,                                        //  Stage and Scanner Center Pos Move
        //    MoveTo_CameraCenterPos,                                         //  Stage and Camera Center Pos Move
        //    MoveTo_CameraReticleGlassPos,                                   //  Camera and Reticle Glass Pos Move
        //    MoveTo_PowerCheckPos,                                           //  Laser Power Check Pos Move
        //    MoveTo_FrontPos,                                                //  Front Pos Move
        //    MoveTo_RearPos,                                                 //  Rear Pos Move
        //}

        void Run_WorkStageMove_Cycle_Func()
        {
            bool m_bRet = false;
            string m_strTemp;

            double lfVelocity = 0.0;
            double lfAccDec = 0.0;


            //  운전 중 Door 를 열면 장비 Stop
            if (m_nWorkStage_Move_Step >= (int)WorkStage_Move_Step.Start)
            {
                //if (Config.ParamConfig.AreaSensor_Usage && (waferProbeAlignParameter.DI_AreaSensor_Detect() || waferProbeAlignParameter.DI_AlignJig_Detect()))
                //{
                //    Log.Write("CWA150SA", Equipment.User_Name, "Machine Initialize", "안전 센서 감지로 인한 장비 Stop");

                //    m_bInCycleMoving_SafetySensor_Detected = true;

                //    //  알람 정지 (LED Bar - Red Blink)
                //    Equipment.MachineStop_byAlarm = true;

                //    timer_Motion_Home.Enabled = false;
                //    m_btimer_Motion_Home_Stop = true;

                //    m_nHomeStep = (int)Home_Step.None;

                //    //MC_Func.MC_MotorStop((int)WaferProbeAlignParameter.AxisAjinEnum.U, 500);
                //    //MC_Func.MC_MotorStop((int)WaferProbeAlignParameter.AxisAjinEnum.V, 500);
                //    //MC_Func.MC_MotorStop((int)WaferProbeAlignParameter.AxisAjinEnum.W, 500);
                //    //MC_Func.MC_MotorStop((int)WaferProbeAlignParameter.AxisAjinEnum.EZ, 500);
                //    //MC_Func.MC_MotorStop((int)WaferProbeAlignParameter.AxisAjinEnum.X, 500);
                //    //MC_Func.MC_MotorStop((int)WaferProbeAlignParameter.AxisAjinEnum.Y, 500);
                //    //MC_Func.MC_MotorStop((int)WaferProbeAlignParameter.AxisAjinEnum.VZ, 500);

                //    for (int i = 0; i < (int)AxisAjinEnum.Max; i++)
                //    {
                //        MC_Func.MC_MotorStop(i, 2000);
                //        //MC_Func.MC_EStop(i);
                //    }

                //    if (!Equipment.User_QMC_Engineer)                   //  QMC 관리자가 아닐 경우에만 Home Flag 를 false 로
                //    {
                //        m_bHomeOK = false;                              //  안전센서 감지 시 무조건 장비 초기화 해야 함
                //    }

                //    if (!Equipment.User_QMC_Engineer && Config.ParamConfig.AreaSensor_ServoOff_Usage)           //  안전센서 감지 시 Servo Off 할 경우
                //    {
                //        for (int i = 0; i < (int)AxisAjinEnum.Max; i++)
                //        {
                //            MC_Func.MC_SetServoOnOff(i, false);
                //        }
                //    }
                //}
            }


            switch (m_nWorkStage_Move_Step)
            {
                case (int)WorkStage_Move_Step.Start:
                    Log.Write("SLD-200", Equipment.User_Name, "Work Stage Move Cycle", "시작");

                    Equipment.MachineStop_byAlarm = false;

                    //  Work Stage XYZ 축 모터 전체 Stop
                    MC_Func.MC_MotorStop((int)nAxis.X, 2000);
                    MC_Func.MC_MotorStop((int)nAxis.Y, 2000);
                    MC_Func.MC_MotorStop((int)nAxis.Z, 2000);

                    m_nWorkStage_Move_Step = (int)WorkStage_Move_Step.Process_Type_Check;
                    break;


                case (int)WorkStage_Move_Step.Process_Type_Check:
                    Log.Write("SLD-200", Equipment.User_Name, "Work Stage Move Cycle", "동작 타입 확인");

                    //MoveTo_LoadingPos = 0,                                          //  Module Loading Pos Move
                    //MoveTo_UnloadingPos,                                            //  Module Unloading Pos Move
                    //MoveTo_GlassCleaningPos,                                        //  Scanner Lens Glass Cleaning Pos Move
                    //MoveTo_CalSheetChangePos,                                       //  Scanner Cal-Sheet Change Pos Move
                    //MoveTo_ScannerCenterPos,                                        //  Stage and Scanner Center Pos Move
                    //MoveTo_CameraCenterPos,                                         //  Stage and Camera Center Pos Move
                    //MoveTo_CameraReticleGlassPos,                                   //  Camera and Reticle Glass Pos Move
                    //MoveTo_PowerCheckPos,                                           //  Laser Power Check Pos Move
                    //MoveTo_FrontPos,                                                //  Front Pos Move
                    //MoveTo_RearPos,                                                 //  Rear Pos Move

                    switch (m_nWorkStageMoveType)
                    {
                        case (int)WorkStageMoveType.MoveTo_LoadingPos:
                            Log.Write("SLD-200", Equipment.User_Name, "Work Stage Move Cycle", "Loading 위치로 이동하는 모드");
                            m_nWorkStage_Move_Step = (int)WorkStage_Move_Step.ToLoadingPos_Condition_Check;                                                                             //  요거 하고
                            break;

                        case (int)WorkStageMoveType.MoveTo_UnloadingPos:
                            Log.Write("SLD-200", Equipment.User_Name, "Work Stage Move Cycle", "Unloading 위치로 이동하는 모드");
                            m_nWorkStage_Move_Step = (int)WorkStage_Move_Step.ToUnloadingPos_Condition_Check;                                                                           //  요거 하고
                            break;

                        case (int)WorkStageMoveType.MoveTo_GlassCleaningPos:
                            Log.Write("SLD-200", Equipment.User_Name, "Work Stage Move Cycle", "Scanner 렌즈 보호 유리를 청소하기 위한 위치로 이동하는 모드");
                            m_nWorkStage_Move_Step = (int)WorkStage_Move_Step.ToGlassCleaningPos_Condition_Check;
                            break;

                        case (int)WorkStageMoveType.MoveTo_CalSheetChangePos:
                            Log.Write("SLD-200", Equipment.User_Name, "Work Stage Move Cycle", "Calibration Acryl 교체 위치로 이동하는 모드");
                            m_nWorkStage_Move_Step = (int)WorkStage_Move_Step.ToCalSheetChangePos_Condition_Check;
                            break;

                        case (int)WorkStageMoveType.MoveTo_ScannerCenterPos:
                            Log.Write("SLD-200", Equipment.User_Name, "Work Stage Move Cycle", "Scanner Center 위치로 이동하는 모드");
                            m_nWorkStage_Move_Step = (int)WorkStage_Move_Step.ToScannerCenterPos_Condition_Check;                                                                       //  요거 하고
                            break;

                        case (int)WorkStageMoveType.MoveTo_CameraCenterPos:
                            Log.Write("SLD-200", Equipment.User_Name, "Work Stage Move Cycle", "Fine Camera 위치로 이동하는 모드");
                            m_nWorkStage_Move_Step = (int)WorkStage_Move_Step.ToCameraCenterPos_Condition_Check;                                                                        //  요거 하고
                            break;

                        case (int)WorkStageMoveType.MoveTo_CameraReticleGlassPos:
                            Log.Write("SLD-200", Equipment.User_Name, "Work Stage Move Cycle", "Fine Camera 가 Reticle Glass 를 확인하는 위치로 이동시키는 모드");
                            m_nWorkStage_Move_Step = (int)WorkStage_Move_Step.ToReticleCenterPos_Condition_Check;
                            break;

                        case (int)WorkStageMoveType.MoveTo_PowerCheckPos:
                            Log.Write("SLD-200", Equipment.User_Name, "Work Stage Move Cycle", "Stage 의 Power Meter 측정 위치로 이동시키는 모드");
                            m_nWorkStage_Move_Step = (int)WorkStage_Move_Step.ToPowerCheckPos_Condition_Check;
                            break;

                        case (int)WorkStageMoveType.MoveTo_FrontPos:
                            Log.Write("SLD-200", Equipment.User_Name, "Work Stage Move Cycle", "Work Stage 를 앞쪽으로 이동시키는 모드");
                            m_nWorkStage_Move_Step = (int)WorkStage_Move_Step.ToFrontPos_Condition_Check;
                            break;

                        case (int)WorkStageMoveType.MoveTo_RearPos:
                            Log.Write("SLD-200", Equipment.User_Name, "Work Stage Move Cycle", "Work Stage 를 장비 뒤쪽으로 이동시키는 모드");
                            m_nWorkStage_Move_Step = (int)WorkStage_Move_Step.ToRearPos_Condition_Check;
                            break;

                        default:            //  Error
                            Log.Write("SLD-200", Equipment.User_Name, "Work Stage Move Cycle", "동작 타입 목록에 없음");
                            m_nWorkStage_Move_Step = (int)WorkStage_Move_Step.Complete;
                            break;
                    }
                    break;



                /// <summary>
                /// Module Loading Pos Move - 시작
                /// </summary>                
                case (int)WorkStage_Move_Step.ToLoadingPos_Condition_Check:                            //  Work Stage 가 Module Loading 위치로 이동할 수 있는 조건 체크 (Stage Vacuum Off Check [필수 아님], Drilling Cycle : None, Loader Transfer Cycle : None)

                    Log.Write("SLD-200", Equipment.User_Name, "Work Stage Move Cycle", "Work Stage, Loading 위치 이동 체크");

                    if (m_nLaserDrilling_MainStep > (int)LaserDrilling_Step.None)
                    {
                        Log.Write("SLD-200", Equipment.User_Name, "Work Stage Move Cycle", "Laser Drilling Cycle 이 동작중이므로 Stage 이동 중지.");

                        //  Out.
                        m_nWorkStage_Move_Step = (int)WorkStage_Move_Step.None;
                    }
                    else if (((loader.m_nLoader_Transfer_Step < (int)Loader_Transfer_Step.WorkStagePutDown_WorkStageCycle_LoadingPos_Start) ||
                            (loader.m_nLoader_Transfer_Step > (int)Loader_Transfer_Step.WorkStagePutDown_WorkStageCycle_LoadingPos_CompleteCheck)) &&

                            (loader.m_nLoader_Transfer_Step > (int)Loader.Loader_Transfer_Step.None))
                    {
                        Log.Write("SLD-200", Equipment.User_Name, "Work Stage Move Cycle", "LD Transfer 가 동작중이므로 Stage 이동 중지.");

                        //  Out.
                        m_nWorkStage_Move_Step = (int)WorkStage_Move_Step.None;
                    }
                    else
                    {
                        Log.Write("SLD-200", Equipment.User_Name, "Work Stage Move Cycle", "Work Stage, Loading 위치 이동 조건 OK");

                        m_nWorkStage_Move_Step = (int)WorkStage_Move_Step.ToLoadingPos_ScannerZ_Move_ReadyPos;
                    }
                    break;


                case (int)WorkStage_Move_Step.ToLoadingPos_ScannerZ_Move_ReadyPos:                            //  Scanner Z 축, 대기 위치로 이동

                    Log.Write("SLD-200", Equipment.User_Name, "Auto Run", "Stage Z 축, 대기 위치 이동 시작");

                    workStageParameter.stWorkStagePosParam = workStageParameter.GetPositionInformation("Safety");

                    //  Target Position 변경 : Z 축 대기 위치
                    workStageParameter.stWorkStagePosParam.dTarget[(int)WorkStageParameter.MotionKey.Z] = vision.stVisionTeachingPos[(int)Vision.Vision_TeachingPosList.Vision_SafetyPos].Vision_Z;

                    //  속도 설정
                    lfVelocity = Equipment.stAxisParam[(int)WorkStage.nAxis.Z].Common_Speed_Fine;
                    lfAccDec = Equipment.stAxisParam[(int)WorkStage.nAxis.Z].Common_Acceleration_Fine;

                    MC_Func.MC_MovePosition((int)WorkStage.nAxis.Z, workStageParameter.stWorkStagePosParam.dTarget[(int)WorkStageParameter.MotionKey.Z],
                                          lfVelocity, lfAccDec, lfAccDec);

                    TickCount_Start((int)TickType.TICK_STAGE_MOVE);

                    m_nWorkStage_Move_Step = (int)WorkStage_Move_Step.ToLoadingPos_ScannerZ_Move_ReadyPos_DoneCheck;
                    break;


                case (int)WorkStage_Move_Step.ToLoadingPos_ScannerZ_Move_ReadyPos_DoneCheck:                       //  Scanner Z 축, 대기 위치로 이동 완료 확인

                    if (MC_Func.MC_GetDone((int)WorkStage.nAxis.Z) && MC_Func.MC_PosTolerance((int)WorkStage.nAxis.Z, workStageParameter.stWorkStagePosParam.dTarget[(int)WorkStageParameter.MotionKey.Z]))
                    {
                        Log.Write("SLD-200", Equipment.User_Name, "Auto Run", "Stage Z 축, 대기 위치 이동 완료 확인");

                        m_nWorkStage_Move_Step = (int)WorkStage_Move_Step.ToLoadingPos_StageXY_Move_LoadingPos;
                    }
                    else if (TickCount_Elapsed((int)TickType.TICK_STAGE_MOVE) > 60000)
                    {
                        Log.Write("SLD-200", Equipment.User_Name, "Auto Run", "Stage Z 축, 대기 위치 이동 실패. (Timeout)");

                        //  알람 정지 (LED Bar - Red Blink)
                        Equipment.MachineStop_byAlarm = true;

                        //timer_MainWork.Enabled = false;
                        //m_btimer_Motion_Home_Stop = true;

                        m_nWorkStage_Move_Step = (int)WorkStage_Move_Step.None;

                        MessageBox.Show("Stage Z 축, 대기 위치 이동 실패", "Error", MessageBoxButtons.OK, MessageBoxIcon.Error);
                    }
                    break;


                case (int)WorkStage_Move_Step.ToLoadingPos_StageXY_Move_LoadingPos:                            //  Stage XY 축, Module Loading 위치로 이동

                    Log.Write("SLD-200", Equipment.User_Name, "Work Stage Move Cycle", "Stage XY 축, Module Loading 위치로 이동 시작");

                    workStageParameter.stWorkStagePosParam = workStageParameter.GetPositionInformation("Module_Loading");

                    //  Target Position 변경 : Module Loading 위치
                    workStageParameter.stWorkStagePosParam.dTarget[(int)WorkStageParameter.MotionKey.X] = stWorkStageTeachingPos[(int)WorkStage_TeachingPosList.STAGE_LoadingPos].Stage_X;
                    workStageParameter.stWorkStagePosParam.dTarget[(int)WorkStageParameter.MotionKey.Y] = stWorkStageTeachingPos[(int)WorkStage_TeachingPosList.STAGE_LoadingPos].Stage_Y;

                    //  속도 설정
                    lfVelocity = Equipment.stAxisParam[(int)WorkStage.nAxis.X].Common_Speed_Coarse;
                    lfAccDec = Equipment.stAxisParam[(int)WorkStage.nAxis.X].Common_Acceleration_Coarse;

                    xyInterpolatedCoordinate.X = workStageParameter.stWorkStagePosParam.dTarget[(int)WorkStageParameter.MotionKey.X];
                    xyInterpolatedCoordinate.Y = workStageParameter.stWorkStagePosParam.dTarget[(int)WorkStageParameter.MotionKey.Y];

                    MC_Func.MovePosition(xyInterpolatedCoordinate, lfVelocity, lfAccDec, lfAccDec);

                    //////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
                    //  맵 데이터 변경 (기준위치 : Scanner)
                    //  기준위치로 보낼 때, 맵데이터를 변경한 후 보낸다.
                    //  그 외에는, 위치로 보낸 후 맵데이터를 변경한다.
                    MapData_Apply((int)WorkStage.nMapData_Type.MapData_Stage_FineCam);
                    //////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////

                    TickCount_Start((int)TickType.TICK_STAGE_MOVE);

                    m_nWorkStage_Move_Step = (int)WorkStage_Move_Step.ToLoadingPos_StageXY_Move_LoadingPos_DoneCheck;
                    break;


                case (int)WorkStage_Move_Step.ToLoadingPos_StageXY_Move_LoadingPos_DoneCheck:                       //  Stage XY 축, Module Loading 위치로 이동 완료 확인

                    if (MC_Func.MC_GetDone((int)WorkStage.nAxis.X) && MC_Func.MC_PosTolerance((int)WorkStage.nAxis.X, workStageParameter.stWorkStagePosParam.dTarget[(int)WorkStageParameter.MotionKey.X]) &&
                        MC_Func.MC_GetDone((int)WorkStage.nAxis.Y) && MC_Func.MC_PosTolerance((int)WorkStage.nAxis.Y, workStageParameter.stWorkStagePosParam.dTarget[(int)WorkStageParameter.MotionKey.Y]))
                    {
                        Log.Write("SLD-200", Equipment.User_Name, "Work Stage Move Cycle", "Stage XY 축, Module Loading 위치로 이동 완료");

                        m_nWorkStage_Move_Step = (int)WorkStage_Move_Step.Complete;
                    }
                    else if (TickCount_Elapsed((int)TickType.TICK_STAGE_MOVE) > 60000)
                    {
                        Log.Write("SLD-200", Equipment.User_Name, "Work Stage Move Cycle", "Stage XY 축, Module Loading 위치로 이동 실패. (Timeout)");

                        //  알람 정지 (LED Bar - Red Blink)
                        Equipment.MachineStop_byAlarm = true;

                        //timer_MainWork.Enabled = false;
                        //m_btimer_Motion_Home_Stop = true;

                        m_nWorkStage_Move_Step = (int)WorkStage_Move_Step.None;

                        MessageBox.Show("Stage XY 축, Module Loading 위치로 이동 실패.", "Error", MessageBoxButtons.OK, MessageBoxIcon.Error);
                    }
                    break;
                /// <summary>
                /// Module Loading Pos Move - 완료
                /// </summary>



                /// <summary>
                /// Module Unloading Pos Move - 시작
                /// </summary>                
                case (int)WorkStage_Move_Step.ToUnloadingPos_Condition_Check:                            //  Work Stage 가 Module Unloading 위치로 이동할 수 있는 조건 체크 (Stage Vacuum On Check [필수 아님], Drilling Cycle : None, Unloader Transfer Cycle : None)

                    Log.Write("SLD-200", Equipment.User_Name, "Work Stage Move Cycle", "Work Stage, Loading 위치 이동 체크");

                    if (m_nLaserDrilling_MainStep > (int)LaserDrilling_Step.None)
                    {
                        Log.Write("SLD-200", Equipment.User_Name, "Work Stage Move Cycle", "Laser Drilling Cycle 이 동작중이므로 Stage 이동 중지.");

                        //  Out.
                        m_nWorkStage_Move_Step = (int)WorkStage_Move_Step.None;
                    }
                    //else if (unloader.m_nUnloader_Transfer_Step > (int)Unloader.Unloader_Transfer_Step.None)
                    else if (((unloader.m_nUnloader_Transfer_Step < (int)Unloader_Transfer_Step.WorkStagePickUp_WorkStageCycle_UnloadingPos_Start) ||
                            (unloader.m_nUnloader_Transfer_Step > (int)Unloader_Transfer_Step.WorkStagePickUp_WorkStageCycle_UnloadingPos_CompleteCheck)) &&

                            (unloader.m_nUnloader_Transfer_Step > (int)Unloader.Unloader_Transfer_Step.None))
                    {
                        Log.Write("SLD-200", Equipment.User_Name, "Work Stage Move Cycle", "UL Transfer 가 동작중이므로 Stage 이동 중지.");

                        //  Out.
                        m_nWorkStage_Move_Step = (int)WorkStage_Move_Step.None;
                    }
                    else
                    {
                        Log.Write("SLD-200", Equipment.User_Name, "Work Stage Move Cycle", "Work Stage, Unloading 위치 이동 조건 OK");

                        m_nWorkStage_Move_Step = (int)WorkStage_Move_Step.ToUnloadingPos_ScannerZ_Move_ReadyPos;
                    }
                    break;


                case (int)WorkStage_Move_Step.ToUnloadingPos_ScannerZ_Move_ReadyPos:                            //  Scanner Z 축, 대기 위치로 이동

                    Log.Write("SLD-200", Equipment.User_Name, "Auto Run", "Stage Z 축, 대기 위치 이동 시작");

                    workStageParameter.stWorkStagePosParam = workStageParameter.GetPositionInformation("Safety");

                    //  Target Position 변경 : Z 축 대기 위치
                    workStageParameter.stWorkStagePosParam.dTarget[(int)WorkStageParameter.MotionKey.Z] = vision.stVisionTeachingPos[(int)Vision.Vision_TeachingPosList.Vision_SafetyPos].Vision_Z;

                    //  속도 설정
                    lfVelocity = Equipment.stAxisParam[(int)WorkStage.nAxis.Z].Common_Speed_Fine;
                    lfAccDec = Equipment.stAxisParam[(int)WorkStage.nAxis.Z].Common_Acceleration_Fine;

                    MC_Func.MC_MovePosition((int)WorkStage.nAxis.Z, workStageParameter.stWorkStagePosParam.dTarget[(int)WorkStageParameter.MotionKey.Z],
                                          lfVelocity, lfAccDec, lfAccDec);

                    TickCount_Start((int)TickType.TICK_STAGE_MOVE);

                    m_nWorkStage_Move_Step = (int)WorkStage_Move_Step.ToUnloadingPos_ScannerZ_Move_ReadyPos_DoneCheck;
                    break;


                case (int)WorkStage_Move_Step.ToUnloadingPos_ScannerZ_Move_ReadyPos_DoneCheck:                       //  Scanner Z 축, 대기 위치로 이동 완료 확인

                    if (MC_Func.MC_GetDone((int)WorkStage.nAxis.Z) && MC_Func.MC_PosTolerance((int)WorkStage.nAxis.Z, workStageParameter.stWorkStagePosParam.dTarget[(int)WorkStageParameter.MotionKey.Z]))
                    {
                        Log.Write("SLD-200", Equipment.User_Name, "Auto Run", "Stage Z 축, 대기 위치 이동 완료 확인");

                        m_nWorkStage_Move_Step = (int)WorkStage_Move_Step.ToUnloadingPos_StageXY_Move_UnloadingPos;
                    }
                    else if (TickCount_Elapsed((int)TickType.TICK_STAGE_MOVE) > 60000)
                    {
                        Log.Write("SLD-200", Equipment.User_Name, "Auto Run", "Stage Z 축, 대기 위치 이동 실패. (Timeout)");

                        //  알람 정지 (LED Bar - Red Blink)
                        Equipment.MachineStop_byAlarm = true;

                        //timer_MainWork.Enabled = false;
                        //m_btimer_Motion_Home_Stop = true;

                        m_nWorkStage_Move_Step = (int)WorkStage_Move_Step.None;

                        MessageBox.Show("Stage Z 축, 대기 위치 이동 실패", "Error", MessageBoxButtons.OK, MessageBoxIcon.Error);
                    }
                    break;


                case (int)WorkStage_Move_Step.ToUnloadingPos_StageXY_Move_UnloadingPos:                            //  Stage XY 축, Module Unloading 위치로 이동

                    Log.Write("SLD-200", Equipment.User_Name, "Work Stage Move Cycle", "Stage XY 축, Module Unloading 위치로 이동 시작");

                    workStageParameter.stWorkStagePosParam = workStageParameter.GetPositionInformation("Module_Unloading");

                    //  Target Position 변경 : Module Unloading 위치
                    workStageParameter.stWorkStagePosParam.dTarget[(int)WorkStageParameter.MotionKey.X] = stWorkStageTeachingPos[(int)WorkStage_TeachingPosList.STAGE_UnloadingPos].Stage_X;
                    workStageParameter.stWorkStagePosParam.dTarget[(int)WorkStageParameter.MotionKey.Y] = stWorkStageTeachingPos[(int)WorkStage_TeachingPosList.STAGE_UnloadingPos].Stage_Y;

                    //  속도 설정
                    lfVelocity = Equipment.stAxisParam[(int)WorkStage.nAxis.X].Common_Speed_Coarse;
                    lfAccDec = Equipment.stAxisParam[(int)WorkStage.nAxis.X].Common_Acceleration_Coarse;

                    xyInterpolatedCoordinate.X = workStageParameter.stWorkStagePosParam.dTarget[(int)WorkStageParameter.MotionKey.X];
                    xyInterpolatedCoordinate.Y = workStageParameter.stWorkStagePosParam.dTarget[(int)WorkStageParameter.MotionKey.Y];

                    MC_Func.MovePosition(xyInterpolatedCoordinate, lfVelocity, lfAccDec, lfAccDec);

                    //////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
                    //  맵 데이터 변경 (기준위치 : Scanner)
                    //  기준위치로 보낼 때, 맵데이터를 변경한 후 보낸다.
                    //  그 외에는, 위치로 보낸 후 맵데이터를 변경한다.
                    MapData_Apply((int)WorkStage.nMapData_Type.MapData_Stage_FineCam);
                    //////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////

                    TickCount_Start((int)TickType.TICK_STAGE_MOVE);

                    m_nWorkStage_Move_Step = (int)WorkStage_Move_Step.ToUnloadingPos_StageXY_Move_UnloadingPos_DoneCheck;
                    break;


                case (int)WorkStage_Move_Step.ToUnloadingPos_StageXY_Move_UnloadingPos_DoneCheck:                       //  Stage XY 축, Module Unloading 위치로 이동 완료 확인

                    if (MC_Func.MC_GetDone((int)WorkStage.nAxis.X) && MC_Func.MC_PosTolerance((int)WorkStage.nAxis.X, workStageParameter.stWorkStagePosParam.dTarget[(int)WorkStageParameter.MotionKey.X]) &&
                        MC_Func.MC_GetDone((int)WorkStage.nAxis.Y) && MC_Func.MC_PosTolerance((int)WorkStage.nAxis.Y, workStageParameter.stWorkStagePosParam.dTarget[(int)WorkStageParameter.MotionKey.Y]))
                    {
                        Log.Write("SLD-200", Equipment.User_Name, "Work Stage Move Cycle", "Stage XY 축, Module Unloading 위치로 이동 완료");

                        m_nWorkStage_Move_Step = (int)WorkStage_Move_Step.Complete;
                    }
                    else if (TickCount_Elapsed((int)TickType.TICK_STAGE_MOVE) > 60000)
                    {
                        Log.Write("SLD-200", Equipment.User_Name, "Work Stage Move Cycle", "Stage XY 축, Module Unloading 위치로 이동 실패. (Timeout)");

                        //  알람 정지 (LED Bar - Red Blink)
                        Equipment.MachineStop_byAlarm = true;

                        //timer_MainWork.Enabled = false;
                        //m_btimer_Motion_Home_Stop = true;

                        m_nWorkStage_Move_Step = (int)WorkStage_Move_Step.None;

                        MessageBox.Show("Stage XY 축, Module Unloading 위치로 이동 실패.", "Error", MessageBoxButtons.OK, MessageBoxIcon.Error);
                    }
                    break;
                /// <summary>
                /// Module Unloading Pos Move - 완료
                /// </summary>



                /// <summary>
                /// Stage and Scanner Center Pos Move - 시작
                /// </summary>                
                case (int)WorkStage_Move_Step.ToScannerCenterPos_Condition_Check:                            //  Work Stage 가 Scanner Center 위치로 이동할 수 있는 조건 체크 (Drilling Cycle : None)

                    Log.Write("SLD-200", Equipment.User_Name, "Work Stage Move Cycle", "Work Stage, Scanner Center 위치 이동 체크");

                    if (m_nLaserDrilling_MainStep > (int)LaserDrilling_Step.None)
                    {
                        Log.Write("SLD-200", Equipment.User_Name, "Work Stage Move Cycle", "Laser Drilling Cycle 이 동작중이므로 Stage 이동 중지.");

                        //  Out.
                        m_nWorkStage_Move_Step = (int)WorkStage_Move_Step.None;
                    }

                    //  Align 중이거나
                    //  Glass Cleaning 중이거나
                    //  Cal Sheet Change 중이거나
                    //  등등등이면 이동 안되도록 해야 한다.

                    //else if (unloader.m_nUnloader_Transfer_Step > (int)Unloader.Unloader_Transfer_Step.None)
                    //{
                    //    Log.Write("SLD-200", Equipment.User_Name, "Work Stage Move Cycle", "UL Transfer 가 동작중이므로 Stage 이동 중지.");

                    //    //  Out.
                    //    m_nWorkStage_Move_Step = (int)WorkStage_Move_Step.None;
                    //}
                    else
                    {
                        Log.Write("SLD-200", Equipment.User_Name, "Work Stage Move Cycle", "Work Stage, Scanner Center 위치 이동 조건 OK");

                        m_nWorkStage_Move_Step = (int)WorkStage_Move_Step.ToScannerCenterPos_ScannerZ_Move_ReadyPos;
                    }
                    break;


                case (int)WorkStage_Move_Step.ToScannerCenterPos_ScannerZ_Move_ReadyPos:                            //  Scanner Z 축, 대기 위치로 이동

                    Log.Write("SLD-200", Equipment.User_Name, "Auto Run", "Stage Z 축, 대기 위치 이동 시작");

                    workStageParameter.stWorkStagePosParam = workStageParameter.GetPositionInformation("Safety");

                    //  Target Position 변경 : Z 축 대기 위치
                    workStageParameter.stWorkStagePosParam.dTarget[(int)WorkStageParameter.MotionKey.Z] = vision.stVisionTeachingPos[(int)Vision.Vision_TeachingPosList.Vision_SafetyPos].Vision_Z;

                    //  속도 설정
                    lfVelocity = Equipment.stAxisParam[(int)WorkStage.nAxis.Z].Common_Speed_Fine;
                    lfAccDec = Equipment.stAxisParam[(int)WorkStage.nAxis.Z].Common_Acceleration_Fine;

                    MC_Func.MC_MovePosition((int)WorkStage.nAxis.Z, workStageParameter.stWorkStagePosParam.dTarget[(int)WorkStageParameter.MotionKey.Z],
                                          lfVelocity, lfAccDec, lfAccDec);

                    TickCount_Start((int)TickType.TICK_STAGE_MOVE);

                    m_nWorkStage_Move_Step = (int)WorkStage_Move_Step.ToScannerCenterPos_ScannerZ_Move_ReadyPos_DoneCheck;
                    break;


                case (int)WorkStage_Move_Step.ToScannerCenterPos_ScannerZ_Move_ReadyPos_DoneCheck:                       //  Scanner Z 축, 대기 위치로 이동 완료 확인

                    if (MC_Func.MC_GetDone((int)WorkStage.nAxis.Z) && MC_Func.MC_PosTolerance((int)WorkStage.nAxis.Z, workStageParameter.stWorkStagePosParam.dTarget[(int)WorkStageParameter.MotionKey.Z]))
                    {
                        Log.Write("SLD-200", Equipment.User_Name, "Auto Run", "Stage Z 축, 대기 위치 이동 완료 확인");

                        m_nWorkStage_Move_Step = (int)WorkStage_Move_Step.ToScannerCenterPos_StageXY_Move_StageScannerCenterPos;
                    }
                    else if (TickCount_Elapsed((int)TickType.TICK_STAGE_MOVE) > 60000)
                    {
                        Log.Write("SLD-200", Equipment.User_Name, "Auto Run", "Stage Z 축, 대기 위치 이동 실패. (Timeout)");

                        //  알람 정지 (LED Bar - Red Blink)
                        Equipment.MachineStop_byAlarm = true;

                        //timer_MainWork.Enabled = false;
                        //m_btimer_Motion_Home_Stop = true;

                        m_nWorkStage_Move_Step = (int)WorkStage_Move_Step.None;

                        MessageBox.Show("Stage Z 축, 대기 위치 이동 실패", "Error", MessageBoxButtons.OK, MessageBoxIcon.Error);
                    }
                    break;


                case (int)WorkStage_Move_Step.ToScannerCenterPos_StageXY_Move_StageScannerCenterPos:                            //  Stage XY 축, Scanner Center 위치로 이동

                    Log.Write("SLD-200", Equipment.User_Name, "Work Stage Move Cycle", "Stage XY 축, Scanner Center 위치로 이동 시작");

                    workStageParameter.stWorkStagePosParam = workStageParameter.GetPositionInformation("Processing");

                    //////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
                    //  맵 데이터 변경 (기준위치 : Scanner)
                    //  기준위치로 보낼 때, 맵데이터를 변경한 후 보낸다.
                    //  그 외에는, 위치로 보낸 후 맵데이터를 변경한다.
                    MapData_Apply((int)WorkStage.nMapData_Type.MapData_Stage_Scanner);
                    //////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////

                    //  Target Position 변경 : Module Unloading 위치
                    workStageParameter.stWorkStagePosParam.dTarget[(int)WorkStageParameter.MotionKey.X] = stWorkStageTeachingPos[(int)WorkStage_TeachingPosList.STAGE_ProcessingPos].Stage_X;
                    workStageParameter.stWorkStagePosParam.dTarget[(int)WorkStageParameter.MotionKey.Y] = stWorkStageTeachingPos[(int)WorkStage_TeachingPosList.STAGE_ProcessingPos].Stage_Y;

                    //  속도 설정
                    lfVelocity = Equipment.stAxisParam[(int)WorkStage.nAxis.X].Common_Speed_Coarse;
                    lfAccDec = Equipment.stAxisParam[(int)WorkStage.nAxis.X].Common_Acceleration_Coarse;

                    xyInterpolatedCoordinate.X = workStageParameter.stWorkStagePosParam.dTarget[(int)WorkStageParameter.MotionKey.X];
                    xyInterpolatedCoordinate.Y = workStageParameter.stWorkStagePosParam.dTarget[(int)WorkStageParameter.MotionKey.Y];

                    MC_Func.MovePosition(xyInterpolatedCoordinate, lfVelocity, lfAccDec, lfAccDec);
                    
                    TickCount_Start((int)TickType.TICK_STAGE_MOVE);

                    m_nWorkStage_Move_Step = (int)WorkStage_Move_Step.ToScannerCenterPos_StageXY_Move_StageScannerCenterPos_DoneCheck;
                    break;


                case (int)WorkStage_Move_Step.ToScannerCenterPos_StageXY_Move_StageScannerCenterPos_DoneCheck:                       //  Stage XY 축, Scanner Center 위치로 이동 완료 확인

                    if (MC_Func.MC_GetDone((int)WorkStage.nAxis.X) && MC_Func.MC_PosTolerance((int)WorkStage.nAxis.X, workStageParameter.stWorkStagePosParam.dTarget[(int)WorkStageParameter.MotionKey.X]) &&
                        MC_Func.MC_GetDone((int)WorkStage.nAxis.Y) && MC_Func.MC_PosTolerance((int)WorkStage.nAxis.Y, workStageParameter.stWorkStagePosParam.dTarget[(int)WorkStageParameter.MotionKey.Y]))
                    {
                        Log.Write("SLD-200", Equipment.User_Name, "Work Stage Move Cycle", "Stage XY 축, Scanner Center 위치로 이동 완료");

                        m_nWorkStage_Move_Step = (int)WorkStage_Move_Step.Complete;
                    }
                    else if (TickCount_Elapsed((int)TickType.TICK_STAGE_MOVE) > 60000)
                    {
                        Log.Write("SLD-200", Equipment.User_Name, "Work Stage Move Cycle", "Stage XY 축, Scanner Center 위치로 이동 실패. (Timeout)");

                        //  알람 정지 (LED Bar - Red Blink)
                        Equipment.MachineStop_byAlarm = true;

                        //timer_MainWork.Enabled = false;
                        //m_btimer_Motion_Home_Stop = true;

                        m_nWorkStage_Move_Step = (int)WorkStage_Move_Step.None;

                        MessageBox.Show("Stage XY 축, Scanner Center 위치로 이동 실패.", "Error", MessageBoxButtons.OK, MessageBoxIcon.Error);
                    }
                    break;
                /// <summary>
                /// Stage and Scanner Center Pos Move - 완료
                /// </summary>



                /// <summary>
                /// Stage and Camera Center Pos Move - 시작
                /// </summary>                
                case (int)WorkStage_Move_Step.ToCameraCenterPos_Condition_Check:                            //  Work Stage 가 Camera Center 위치로 이동할 수 있는 조건 체크 (Drilling Cycle : None, 고해상도와 저해상도 선택)

                    Log.Write("SLD-200", Equipment.User_Name, "Work Stage Move Cycle", "Work Stage, Fine Camera Center 위치 이동 체크");

                    if (m_nLaserDrilling_MainStep > (int)LaserDrilling_Step.None)
                    {
                        Log.Write("SLD-200", Equipment.User_Name, "Work Stage Move Cycle", "Laser Drilling Cycle 이 동작중이므로 Stage 이동 중지.");

                        //  Out.
                        m_nWorkStage_Move_Step = (int)WorkStage_Move_Step.None;
                    }

                    //  Align 중이거나
                    //  Glass Cleaning 중이거나
                    //  Cal Sheet Change 중이거나
                    //  등등등이면 이동 안되도록 해야 한다.

                    //else if (unloader.m_nUnloader_Transfer_Step > (int)Unloader.Unloader_Transfer_Step.None)
                    //{
                    //    Log.Write("SLD-200", Equipment.User_Name, "Work Stage Move Cycle", "UL Transfer 가 동작중이므로 Stage 이동 중지.");

                    //    //  Out.
                    //    m_nWorkStage_Move_Step = (int)WorkStage_Move_Step.None;
                    //}
                    else
                    {
                        Log.Write("SLD-200", Equipment.User_Name, "Work Stage Move Cycle", "Work Stage, Fine Camera Center 위치 이동 조건 OK");

                        m_nWorkStage_Move_Step = (int)WorkStage_Move_Step.ToCameraCenterPos_ScannerZ_Move_ReadyPos;
                    }
                    break;


                case (int)WorkStage_Move_Step.ToCameraCenterPos_ScannerZ_Move_ReadyPos:                            //  Scanner Z 축, 대기 위치로 이동

                    Log.Write("SLD-200", Equipment.User_Name, "Auto Run", "Stage Z 축, 대기 위치 이동 시작");

                    workStageParameter.stWorkStagePosParam = workStageParameter.GetPositionInformation("Safety");

                    //  Target Position 변경 : Z 축 대기 위치
                    workStageParameter.stWorkStagePosParam.dTarget[(int)WorkStageParameter.MotionKey.Z] = vision.stVisionTeachingPos[(int)Vision.Vision_TeachingPosList.Vision_SafetyPos].Vision_Z;

                    //  속도 설정
                    lfVelocity = Equipment.stAxisParam[(int)WorkStage.nAxis.Z].Common_Speed_Fine;
                    lfAccDec = Equipment.stAxisParam[(int)WorkStage.nAxis.Z].Common_Acceleration_Fine;

                    MC_Func.MC_MovePosition((int)WorkStage.nAxis.Z, workStageParameter.stWorkStagePosParam.dTarget[(int)WorkStageParameter.MotionKey.Z],
                                          lfVelocity, lfAccDec, lfAccDec);

                    TickCount_Start((int)TickType.TICK_STAGE_MOVE);

                    m_nWorkStage_Move_Step = (int)WorkStage_Move_Step.ToCameraCenterPos_ScannerZ_Move_ReadyPos_DoneCheck;
                    break;


                case (int)WorkStage_Move_Step.ToCameraCenterPos_ScannerZ_Move_ReadyPos_DoneCheck:                       //  Scanner Z 축, 대기 위치로 이동 완료 확인

                    if (MC_Func.MC_GetDone((int)WorkStage.nAxis.Z) && MC_Func.MC_PosTolerance((int)WorkStage.nAxis.Z, workStageParameter.stWorkStagePosParam.dTarget[(int)WorkStageParameter.MotionKey.Z]))
                    {
                        Log.Write("SLD-200", Equipment.User_Name, "Auto Run", "Stage Z 축, 대기 위치 이동 완료 확인");

                        m_nWorkStage_Move_Step = (int)WorkStage_Move_Step.ToCameraCenterPos_StageXY_Move_StageCameraCenterPos;
                    }
                    else if (TickCount_Elapsed((int)TickType.TICK_STAGE_MOVE) > 60000)
                    {
                        Log.Write("SLD-200", Equipment.User_Name, "Auto Run", "Stage Z 축, 대기 위치 이동 실패. (Timeout)");

                        //  알람 정지 (LED Bar - Red Blink)
                        Equipment.MachineStop_byAlarm = true;

                        //timer_MainWork.Enabled = false;
                        //m_btimer_Motion_Home_Stop = true;

                        m_nWorkStage_Move_Step = (int)WorkStage_Move_Step.None;

                        MessageBox.Show("Stage Z 축, 대기 위치 이동 실패", "Error", MessageBoxButtons.OK, MessageBoxIcon.Error);
                    }
                    break;


                case (int)WorkStage_Move_Step.ToCameraCenterPos_StageXY_Move_StageCameraCenterPos:                            //  Stage XY 축, Fine Camera Center 위치로 이동

                    Log.Write("SLD-200", Equipment.User_Name, "Work Stage Move Cycle", "Stage XY 축, Fine Camera Center 위치로 이동 시작");

                    workStageParameter.stWorkStagePosParam = workStageParameter.GetPositionInformation("High_Mag_Camera_Center");
                    
                    //  Target Position 변경 : Module Unloading 위치
                    workStageParameter.stWorkStagePosParam.dTarget[(int)WorkStageParameter.MotionKey.X] = stWorkStageTeachingPos[(int)WorkStage_TeachingPosList.STAGE_HighMagCamPos].Stage_X;
                    workStageParameter.stWorkStagePosParam.dTarget[(int)WorkStageParameter.MotionKey.Y] = stWorkStageTeachingPos[(int)WorkStage_TeachingPosList.STAGE_HighMagCamPos].Stage_Y;

                    //  속도 설정
                    lfVelocity = Equipment.stAxisParam[(int)WorkStage.nAxis.X].Common_Speed_Coarse;
                    lfAccDec = Equipment.stAxisParam[(int)WorkStage.nAxis.X].Common_Acceleration_Coarse;

                    xyInterpolatedCoordinate.X = workStageParameter.stWorkStagePosParam.dTarget[(int)WorkStageParameter.MotionKey.X];
                    xyInterpolatedCoordinate.Y = workStageParameter.stWorkStagePosParam.dTarget[(int)WorkStageParameter.MotionKey.Y];

                    MC_Func.MovePosition(xyInterpolatedCoordinate, lfVelocity, lfAccDec, lfAccDec);

                    //////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
                    //  맵 데이터 변경 (기준위치 : Scanner)
                    //  기준위치로 보낼 때, 맵데이터를 변경한 후 보낸다.
                    //  그 외에는, 위치로 보낸 후 맵데이터를 변경한다.
                    MapData_Apply((int)WorkStage.nMapData_Type.MapData_Stage_FineCam);
                    //////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////

                    TickCount_Start((int)TickType.TICK_STAGE_MOVE);

                    m_nWorkStage_Move_Step = (int)WorkStage_Move_Step.ToCameraCenterPos_StageXY_Move_StageCameraCenterPos_DoneCheck;
                    break;


                case (int)WorkStage_Move_Step.ToCameraCenterPos_StageXY_Move_StageCameraCenterPos_DoneCheck:                       //  Stage XY 축, Camera Center 위치로 이동 완료 확인

                    if (MC_Func.MC_GetDone((int)WorkStage.nAxis.X) && MC_Func.MC_PosTolerance((int)WorkStage.nAxis.X, workStageParameter.stWorkStagePosParam.dTarget[(int)WorkStageParameter.MotionKey.X]) &&
                        MC_Func.MC_GetDone((int)WorkStage.nAxis.Y) && MC_Func.MC_PosTolerance((int)WorkStage.nAxis.Y, workStageParameter.stWorkStagePosParam.dTarget[(int)WorkStageParameter.MotionKey.Y]))
                    {
                        Log.Write("SLD-200", Equipment.User_Name, "Work Stage Move Cycle", "Stage XY 축, Fine Camera Center 위치로 이동 완료");

                        m_nWorkStage_Move_Step = (int)WorkStage_Move_Step.Complete;
                    }
                    else if (TickCount_Elapsed((int)TickType.TICK_STAGE_MOVE) > 60000)
                    {
                        Log.Write("SLD-200", Equipment.User_Name, "Work Stage Move Cycle", "Stage XY 축, Fine Camera Center 위치로 이동 실패. (Timeout)");

                        //  알람 정지 (LED Bar - Red Blink)
                        Equipment.MachineStop_byAlarm = true;

                        //timer_MainWork.Enabled = false;
                        //m_btimer_Motion_Home_Stop = true;

                        m_nWorkStage_Move_Step = (int)WorkStage_Move_Step.None;

                        MessageBox.Show("Stage XY 축, Fine Camera Center 위치로 이동 실패.", "Error", MessageBoxButtons.OK, MessageBoxIcon.Error);
                    }
                    break;
                /// <summary>
                /// Stage and Camera Center Pos Move - 완료
                /// </summary>










                case (int)WorkStage_Move_Step.Complete:

                    Log.Write("SLD-200", Equipment.User_Name, "Work Stage Move Cycle", "완료");

                    //  m_bHomeOK = true;

                    //timer_Motion_Home.Enabled = false;
                    //m_btimer_Motion_Home_Stop = true;

                    switch (m_nWorkStageMoveType)
                    {
                        case (int)WorkStageMoveType.MoveTo_LoadingPos:
                            Log.Write("SLD-200", Equipment.User_Name, "Work Stage Move Cycle", "Loading 위치로 이동 완료");                                        //  요거 하고
                            m_nWorkStagePosition = (int)WorkStage.WorkStagePosition.WorkStage_LoadingZone;
                            break;

                        case (int)WorkStageMoveType.MoveTo_UnloadingPos:
                            Log.Write("SLD-200", Equipment.User_Name, "Work Stage Move Cycle", "Unloading 위치로 이동 완료");                                      //  요거 하고
                            m_nWorkStagePosition = (int)WorkStage.WorkStagePosition.WorkStage_UnloadingZone;
                            break;

                        case (int)WorkStageMoveType.MoveTo_GlassCleaningPos:
                            Log.Write("SLD-200", Equipment.User_Name, "Work Stage Move Cycle", "Scanner 렌즈 보호 유리를 청소하기 위한 위치로 이동 완료");
                            break;

                        case (int)WorkStageMoveType.MoveTo_CalSheetChangePos:
                            Log.Write("SLD-200", Equipment.User_Name, "Work Stage Move Cycle", "Calibration Acryl 교체 위치로 이동 완료");
                            break;

                        case (int)WorkStageMoveType.MoveTo_ScannerCenterPos:
                            Log.Write("SLD-200", Equipment.User_Name, "Work Stage Move Cycle", "Scanner Center 위치로 이동 완료");                                 //  요거 하고     
                            m_nWorkStagePosition = (int)WorkStage.WorkStagePosition.WorkStage_WorkingZone;
                            break;

                        case (int)WorkStageMoveType.MoveTo_CameraCenterPos:
                            Log.Write("SLD-200", Equipment.User_Name, "Work Stage Move Cycle", "Fine Camera 위치로 이동 완료");                                    //  요거 하고   
                            m_nWorkStagePosition = (int)WorkStage.WorkStagePosition.WorkStage_FineCameraZone;
                            break;

                        case (int)WorkStageMoveType.MoveTo_CameraReticleGlassPos:
                            Log.Write("SLD-200", Equipment.User_Name, "Work Stage Move Cycle", "Fine Camera 가 Reticle Glass 를 확인하는 위치로 이동 완료");
                            break;

                        case (int)WorkStageMoveType.MoveTo_PowerCheckPos:
                            Log.Write("SLD-200", Equipment.User_Name, "Work Stage Move Cycle", "Stage 의 Power Meter 측정 위치로 이동 완료");
                            break;

                        case (int)WorkStageMoveType.MoveTo_FrontPos:
                            Log.Write("SLD-200", Equipment.User_Name, "Work Stage Move Cycle", "Work Stage 를 앞쪽으로 이동 완료");
                            break;

                        case (int)WorkStageMoveType.MoveTo_RearPos:
                            Log.Write("SLD-200", Equipment.User_Name, "Work Stage Move Cycle", "Work Stage 를 장비 뒤쪽으로 이동 완료");
                            break;
                    }

                    m_nWorkStage_Move_Step = (int)WorkStage_Move_Step.None;

                    //MessageBox.Show(m_strTemp, "Information!", MessageBoxButtons.OK, MessageBoxIcon.Information);
                    break;
            }
        }

        #endregion



