        #region Laser Height Sensor (Keyence) Socket Func

        void Run_LaserHeightSensorSocket_Func()
        {
            string m_strData = "";

            //if ((m_nLaserDrilling_MainStep != (int)LaserDrilling_Step.None) ||

            //    ((m_nLaserPowerCal_Step >= (int)LaserPowerCal_Step.ThruHole_LaserParameter_Change_Start) && (m_nLaserPowerCal_Step <= (int)LaserPowerCal_Step.ThruHole_LaserParameter_Change_Complete)) ||
            //    ((m_nLaserPowerCal_Step >= (int)LaserPowerCal_Step.OutLine_LaserParameter_Change_Start) && (m_nLaserPowerCal_Step <= (int)LaserPowerCal_Step.OutLine_LaserParameter_Change_Complete)) ||
            //    ((m_nLaserPowerCal_Step >= (int)LaserPowerCal_Step.Drilling_LaserParameter_Change_Start) && (m_nLaserPowerCal_Step <= (int)LaserPowerCal_Step.Drilling_LaserParameter_Change_Complete)) ||

            //    ((m_nLaserPowerCal_byRange_Step >= (int)LaserPowerCal_byRange_Step.Thruhole_LaserParameter_Change_Start) && (m_nLaserPowerCal_byRange_Step <= (int)LaserPowerCal_byRange_Step.Thruhole_LaserParameter_Change_Complete)) ||
            //    ((m_nLaserPowerCal_byRange_Step >= (int)LaserPowerCal_byRange_Step.Outline_LaserParameter_Change_Start) && (m_nLaserPowerCal_byRange_Step <= (int)LaserPowerCal_byRange_Step.Outline_LaserParameter_Change_Complete)) ||
            //    ((m_nLaserPowerCal_byRange_Step >= (int)LaserPowerCal_byRange_Step.Drilling_LaserParameter_Change_Start) && (m_nLaserPowerCal_byRange_Step <= (int)LaserPowerCal_byRange_Step.Drilling_LaserParameter_Change_Complete)))
            //{
            //    if (m_nLaserCommStep == (int)LaserComm_Step.GateStatus_Check)
            //    {
            //        m_bLaserComm_Paused = true;
            //        return;
            //    }
            //    else
            //    {
            //        m_bLaserComm_Paused = false;
            //    }
            //}
            //else
            //{
            //    m_bLaserComm_Paused = false;
            //}


            if (m_SocketLaserHeightSensor == null)
            {
                m_nLaserHeightSensorSocketStep = (int)LaserHeightSensorSocket_Step.None;
                return; ;
            }

            if (!m_SocketLaserHeightSensor.isConnected)
            {
                m_nLaserHeightSensorSocketStep = (int)LaserHeightSensorSocket_Step.None;
                return;
            }

            switch (m_nLaserHeightSensorSocketStep)
            {
                case (int)LaserHeightSensorSocket_Step.Start:

                    m_nLaserHeightSensorSocketRecvData_CR_Count = 0;              //  수신된 데이터 안에 chrCR 이 1개만 존재하는지 확인
                    m_dLaserHeightSensorSocket_Value = 0.0;

                    m_nLaserHeightSensorSocketStep = (int)LaserHeightSensorSocket_Step.LaserHeightSensor_ModeChange_Measure;
                    break;


                case (int)LaserHeightSensorSocket_Step.LaserHeightSensor_ModeChange_Measure:
                    //  모드 변경 (측정)

                    if (m_SocketLaserHeightSensor.isConnected)
                    {
                        m_bLaserSensorSocket_Received = false;
                        m_strLaserSensorSocket_ReceivedData = "";
                        m_nLaserHeightSensorSocketRecvData_CR_Count = 0;

                        LaserSensor_Socket_MeasurementMode();

                        TickCount_Start((int)TickType.TICK_LASER_HEIGHT_SENSOR);

                        m_nLaserHeightSensorSocketStep = (int)LaserHeightSensorSocket_Step.LaserHeightSensor_ModeChange_Measure_DoneCheck;
                    }
                    else
                    {
                        m_nLaserHeightSensorSocketStep = (int)LaserHeightSensorSocket_Step.None;

                        MessageBox.Show("Laser Height Sensor Socket Not Opened.", "Error");
                    }
                    break;


                case (int)LaserHeightSensorSocket_Step.LaserHeightSensor_ModeChange_Measure_DoneCheck:
                    if (m_bLaserSensorSocket_Received)
                    {
                        //  데이터 체크 (2개가 붙어서 들어오는 경우가 있어서... ctrCR 가 1개인지 확인)
                        for (int i = 0; i < m_strLaserSensorSocket_ReceivedData.Length; i++)
                        {
                            if (m_strLaserSensorSocket_ReceivedData[i] == chrCR)
                                m_nLaserHeightSensorSocketRecvData_CR_Count++;
                        }

                        if (m_nLaserHeightSensorSocketRecvData_CR_Count == 1)         //  수신 데이터 안에 \r 이 1개이면? 정상 데이터.
                        {
                            m_strData = m_strLaserSensorSocket_ReceivedData.Substring(0, m_strLaserSensorSocket_ReceivedData.Length - 1);

                            //  데이터 구분
                            string[] LaserSensorData = m_strData.Split(',');

                            if (LaserSensorData.Length == 1)                    //  모드 변경 후 리턴되는 값은 1개
                            {
                                //  명렁어 리턴일 때

                                //label_CommunicationTerminal_ReceivedData.Text = string.Format("Laser Height Sensor Value : {0}", LaserSensorData[0]);

                                //  되었다 치고

                                m_strLaserSensorSocket_ReceivedData = "";

                                m_bLaserSensorSocket_Received = false;
                                m_strLaserSensorSocket_ReceivedData = "";
                                m_nLaserHeightSensorSocketRecvData_CR_Count = 0;

                                m_nLaserHeightSensorSocketStep = (int)LaserHeightSensorSocket_Step.Socket_Pause_Check;
                            }
                            else
                            {
                                m_bLaserSensorSocket_Received = false;
                                m_strLaserSensorSocket_ReceivedData = "";
                                m_nLaserHeightSensorSocketRecvData_CR_Count = 0;

                                m_nLaserHeightSensorSocketStep = (int)LaserHeightSensorSocket_Step.LaserHeightSensor_ModeChange_Measure;
                            }
                        }
                        else                                            //  수신 데이터 안에 \n 이 2개 이상이면? 데이터가 잘못 들어온 것으로 판단하여 다시 데이터 읽기.
                        {
                            m_bLaserSensorSocket_Received = false;
                            m_strLaserSensorSocket_ReceivedData = "";
                            m_nLaserHeightSensorSocketRecvData_CR_Count = 0;

                            m_nLaserHeightSensorSocketStep = (int)LaserHeightSensorSocket_Step.LaserHeightSensor_ModeChange_Measure;
                        }
                    }
                    else if (TickCount_Elapsed((int)TickType.TICK_LASER_HEIGHT_SENSOR) >= 500)
                    {
                        m_bLaserSensorSocket_Received = false;
                        m_strLaserSensorSocket_ReceivedData = "";
                        m_nLaserHeightSensorSocketRecvData_CR_Count = 0;

                        m_nLaserHeightSensorSocketStep = (int)LaserHeightSensorSocket_Step.LaserHeightSensor_ModeChange_Measure;
                    }
                    break;


                case (int)LaserHeightSensorSocket_Step.Socket_Pause_Check:


                    m_nLaserHeightSensorSocketStep = (int)LaserHeightSensorSocket_Step.LaserHeightSensorSocket_Read;
                    break;


                case (int)LaserHeightSensorSocket_Step.LaserHeightSensorSocket_Read:
                    //  읽기

                    if (m_SocketLaserHeightSensor.isConnected)
                    {
                        m_bLaserSensorSocket_Received = false;
                        m_strLaserSensorSocket_ReceivedData = "";
                        m_nLaserHeightSensorSocketRecvData_CR_Count = 0;

                        LaserSensor_Socket_ReadValue();

                        TickCount_Start((int)TickType.TICK_LASER_HEIGHT_SENSOR);

                        m_nLaserHeightSensorSocketStep = (int)LaserHeightSensorSocket_Step.LaserHeightSensorSocket_Received;
                    }
                    else
                    {
                        m_nLaserHeightSensorSocketStep = (int)LaserHeightSensorSocket_Step.None;

                        MessageBox.Show("Laser Height Sensor Socket Not Opened.", "Error");
                    }
                    break;


                case (int)LaserHeightSensorSocket_Step.LaserHeightSensorSocket_Received:
                    if (m_bLaserSensorSocket_Received)
                    {
                        //  데이터 체크 (2개가 붙어서 들어오는 경우가 있어서... ctrLF 가 1개인지 확인)
                        for (int i = 0; i < m_strLaserSensorSocket_ReceivedData.Length; i++)
                        {
                            if (m_strLaserSensorSocket_ReceivedData[i] == chrCR)
                                m_nLaserHeightSensorSocketRecvData_CR_Count++;
                        }

                        if (m_nLaserHeightSensorSocketRecvData_CR_Count == 1)         //  수신 데이터 안에 \r 이 1개이면? 정상 데이터.
                        {
                            m_strData = m_strLaserSensorSocket_ReceivedData.Substring(0, m_strLaserSensorSocket_ReceivedData.Length - 1);

                            //  데이터 구분
                            string[] LaserSensorData = m_strData.Split(',');

                            if (LaserSensorData.Length > 1)
                            {
                                //  값을 읽었을 때
                                m_dLaserHeightSensorSocket_Value = Convert.ToDouble(LaserSensorData[1]);

                                //label_CommunicationTerminal_ReceivedData.Text = string.Format("Laser Height Sensor Value : {0}", );
                                m_strLaserSensorSocket_ReceivedData = "";
                            }
                            else if (LaserSensorData.Length == 1)
                            {
                                //  명렁어 리턴일 때
                                //label_CommunicationTerminal_ReceivedData.Text = string.Format("Laser Height Sensor Value : {0}", LaserSensorData[0]);
                                m_strLaserSensorSocket_ReceivedData = "";
                            }

                            m_bLaserSensorSocket_Received = false;
                            m_strLaserSensorSocket_ReceivedData = "";
                            m_nLaserHeightSensorSocketRecvData_CR_Count = 0;

                            m_nLaserHeightSensorSocketStep = (int)LaserHeightSensorSocket_Step.Socket_Pause_Check;
                        }
                        else                                            //  수신 데이터 안에 \n 이 2개 이상이면? 데이터가 잘못 들어온 것으로 판단하여 다시 데이터 읽기.
                        {
                            m_bLaserSensorSocket_Received = false;
                            m_strLaserSensorSocket_ReceivedData = "";
                            m_nLaserHeightSensorSocketRecvData_CR_Count = 0;

                            m_nLaserHeightSensorSocketStep = (int)LaserHeightSensorSocket_Step.Socket_Pause_Check;
                        }
                    }
                    else if (TickCount_Elapsed((int)TickType.TICK_LASER_HEIGHT_SENSOR) >= 500)
                    {
                        m_bLaserSensorSocket_Received = false;
                        m_strLaserSensorSocket_ReceivedData = "";
                        m_nLaserHeightSensorSocketRecvData_CR_Count = 0;

                        m_nLaserHeightSensorSocketStep = (int)LaserHeightSensorSocket_Step.Socket_Pause_Check;
                    }
                    break;
            }
        }

