            //    ((m_nLaserPowerCal_byRange_Step >= (int)LaserPowerCal_byRange_Step.Drilling_LaserParameter_Change_Start) && (m_nLaserPowerCal_byRange_Step <= (int)LaserPowerCal_byRange_Step.Drilling_LaserParameter_Change_Complete)))
            //{
            //    if (m_nLaserCommStep == (int)LaserComm_Step.GateStatus_Check)
            //    {
            //        m_bLaserComm_Paused = true;
            //        return;
            //    }
            //    else
            //    {
            //        m_bLaserComm_Paused = false;
            //    }
            //}
            //else
            //{
            //    m_bLaserComm_Paused = false;
            //}


            if (m_rapidLxLaser_Comm == null)
            {
                m_nLaserCommStep = (int)LaserComm_Step.None;
                return; ;
            }

            if (!m_rapidLxLaser_Comm.IsOpen)
            {
                m_nLaserCommStep = (int)LaserComm_Step.None;
                return;
            }
            
            switch (m_nLaserCommStep)
            {
                case (int)LaserComm_Step.Start:
                    m_strLaser_HostName = "";
                    m_strLaser_SystemFaults = "";
                    m_nLaser_SystemStatus = 0;
                    m_nLaser_PulseMode = 0;
                    m_dLaser_AmplifierRR = 0.0;
                    m_dLaser_OutputRR = 0.0;
                    m_dLaser_OutputEnergy = 0.0;

                    m_nLaserCommRecvData_LF_Count = 0;                  //  수신된 데이터 안에 chrLF 가 1개만 존재하는지 확인

                    m_nLaserComm_SetValue_Get_Process = 0;              //  Laser Comm 최초 연결 시 세팅된 값을 읽기 위함. (User 세팅 파라미터를 현재 세팅값으로 표시하기 위해서). (0 : Get, 1 : Get Complete, 2 : Set Complete)
                    m_nLaserComm_ReadSetValue_PulseMode_Index = -1;     //  Laser Comm Pulse Mode Index (0 : Internal, 1 : External, 2 : Internal + gated, 3 : External + gated)
                    m_dLaserComm_ReadSetValue_Amplifier = 0.0;          //  Laser Comm Amplifier
                    m_dLaserComm_ReadSetValue_EnergyPercent = 0.0;      //  Laser Comm Output Energy Percentage

                    //m_bLaser_QSW_Value_OK = false;
                    //m_bLaser_EPRF_Value_OK = false;
                    //m_bLaser_SHG_Value_OK = false;
                    //m_bLaser_THG_Value_OK = false;

                    m_nLaserCommStep = (int)LaserComm_Step.Model_Get;
                    break;


                case (int)LaserComm_Step.Model_Get:
                    //  Laser Head Serial Number 읽기

                    if (m_rapidLxLaser_Comm.IsOpen)
                    {
                        m_bRapidLxLaser_CommData_Received = false;
                        m_strRapidLxLaser_Comm_ReceivedData = "";
                        m_nLaserCommRecvData_LF_Count = 0;

                        RapidLxLaserComm_Laser_HostName_Read();

                        TickCount_Start((int)TickType.TICK_LASER_COMM);

                        m_nLaserCommStep = (int)LaserComm_Step.Model_Received;
                    }
                    else
                    {
                        m_nLaserCommStep = (int)LaserComm_Step.None;

                        MessageBox.Show("Laser Comm. Not Opened.", "Error");
                    }
                    break;


                case (int)LaserComm_Step.Model_Received:
                    if (m_bRapidLxLaser_CommData_Received)
                    {
                        //  데이터 체크 (2개가 붙어서 들어오는 경우가 있어서... ctrLF 가 1개인지 확인)
                        for (int i = 0; i < m_strRapidLxLaser_Comm_ReceivedData.Length; i++)
                        {
                            if (m_strRapidLxLaser_Comm_ReceivedData[i] == chrLF)
                                m_nLaserCommRecvData_LF_Count++;
