                            m_bRapidLxLaser_CommData_Received = false;
                            m_strRapidLxLaser_Comm_ReceivedData = "";
                            m_nLaserCommRecvData_LF_Count = 0;

                            m_nLaserCommStep = (int)LaserComm_Step.AmplifierRR_Get;
                        }
                    }
                    else if (TickCount_Elapsed((int)TickType.TICK_LASER_COMM) >= 500)
                    {
                        //  데이터를 사용했으니 초기화
                        m_bRapidLxLaser_CommData_Received = false;
                        m_strRapidLxLaser_Comm_ReceivedData = "";
                        m_nLaserCommRecvData_LF_Count = 0;

                        m_nLaserCommStep = (int)LaserComm_Step.OutputRR_Get;
                    }
                    break;


                case (int)LaserComm_Step.OutputRR_Get:
                    //  Output RepRate 읽기

                    if (m_rapidLxLaser_Comm.IsOpen)
                    {
                        m_bRapidLxLaser_CommData_Received = false;
                        m_strRapidLxLaser_Comm_ReceivedData = "";
                        m_nLaserCommRecvData_LF_Count = 0;

                        RapidLxLaserComm_Laser_OutputRR_Read();

                        TickCount_Start((int)TickType.TICK_LASER_COMM);

                        m_nLaserCommStep = (int)LaserComm_Step.OutputRR_Received;
                    }
                    else
                    {
                        m_nLaserCommStep = (int)LaserComm_Step.None;
                        //timer_LaserComm.Enabled = false;

                        MessageBox.Show("Laser Comm. Not Opened.", "Error");
                    }
                    break;


                case (int)LaserComm_Step.OutputRR_Received:
                    if (m_bRapidLxLaser_CommData_Received)
                    {
                        //  데이터 체크 (2개가 붙어서 들어오는 경우가 있어서... ctrLF 가 1개인지 확인)
                        for (int i = 0; i < m_strRapidLxLaser_Comm_ReceivedData.Length; i++)
                        {
                            if (m_strRapidLxLaser_Comm_ReceivedData[i] == chrLF)
                                m_nLaserCommRecvData_LF_Count++;
                        }

                        //if (m_nLaserCommRecvData_LF_Count == 1)         //  수신 데이터 안에 \n 이 1개이면? 정상 데이터.
                        if ((m_nLaserCommRecvData_LF_Count == 1) && (m_strRapidLxLaser_Comm_ReceivedData.Length >= 2))         //  수신 데이터 안에 \n 이 1개이면? 정상 데이터.
                        {
                            m_strTemp = m_strRapidLxLaser_Comm_ReceivedData;
                            m_strTemp = m_strTemp.Replace("\r", "");
                            m_strTemp = m_strTemp.Replace("\n", "");

                            string[] words = m_strTemp.Split(' ');

                            if (words.Length >= 2)
                            {
                                //m_dLaser_OutputRR = Convert.ToDouble(m_strRapidLxLaser_Comm_ReceivedData.Substring(3, m_strRapidLxLaser_Comm_ReceivedData.Length - 1));
                                m_dLaser_OutputRR = Convert.ToDouble(words[1]);

                                //  데이터를 사용했으니 초기화
                                m_bRapidLxLaser_CommData_Received = false;
                                m_strRapidLxLaser_Comm_ReceivedData = "";
                                m_nLaserCommRecvData_LF_Count = 0;

                                m_nLaserCommStep = (int)LaserComm_Step.EnergyPercent_Get;
                            }
                            else
                            {
                                //  데이터 개수가 안맞으니 다시 시도
                                m_bRapidLxLaser_CommData_Received = false;
                                m_strRapidLxLaser_Comm_ReceivedData = "";
                                m_nLaserCommRecvData_LF_Count = 0;

                                m_nLaserCommStep = (int)LaserComm_Step.OutputRR_Get;
                            }
                        }
                        else                                            //  수신 데이터 안에 \n 이 2개 이상이면? 데이터가 잘못 들어온 것으로 판단하여 다시 데이터 읽기.
                        {
                            //  데이터 개수가 안맞으니 다시 시도
                            m_bRapidLxLaser_CommData_Received = false;
                            m_strRapidLxLaser_Comm_ReceivedData = "";
                            m_nLaserCommRecvData_LF_Count = 0;

                            m_nLaserCommStep = (int)LaserComm_Step.OutputRR_Get;
                        }
                    }
                    else if (TickCount_Elapsed((int)TickType.TICK_LASER_COMM) >= 500)
                    {
                        //  데이터를 사용했으니 초기화
                        m_bRapidLxLaser_CommData_Received = false;
                        m_strRapidLxLaser_Comm_ReceivedData = "";
                        m_nLaserCommRecvData_LF_Count = 0;

                        m_nLaserCommStep = (int)LaserComm_Step.EnergyPercent_Get;
                    }
                    break;


                case (int)LaserComm_Step.EnergyPercent_Get:
                    //  Output Energy 읽기

                    if (m_rapidLxLaser_Comm.IsOpen)
                    {
                        m_bRapidLxLaser_CommData_Received = false;
                        m_strRapidLxLaser_Comm_ReceivedData = "";
                        m_nLaserCommRecvData_LF_Count = 0;

                        RapidLxLaserComm_Laser_OutputEnergy_Read();

                        TickCount_Start((int)TickType.TICK_LASER_COMM);

                        m_nLaserCommStep = (int)LaserComm_Step.EnergyPercent_Received;
                    }
                    else
                    {
                        m_nLaserCommStep = (int)LaserComm_Step.None;
                        //timer_LaserComm.Enabled = false;

                        MessageBox.Show("Laser Comm. Not Opened.", "Error");
                    }
                    break;


                case (int)LaserComm_Step.EnergyPercent_Received:
                    if (m_bRapidLxLaser_CommData_Received)
                    {
                        //  데이터 체크 (2개가 붙어서 들어오는 경우가 있어서... ctrLF 가 1개인지 확인)
                        for (int i = 0; i < m_strRapidLxLaser_Comm_ReceivedData.Length; i++)
                        {
                            if (m_strRapidLxLaser_Comm_ReceivedData[i] == chrLF)
                                m_nLaserCommRecvData_LF_Count++;
                        }

                        //if (m_nLaserCommRecvData_LF_Count == 1)         //  수신 데이터 안에 \n 이 1개이면? 정상 데이터.
                        if ((m_nLaserCommRecvData_LF_Count == 1) && (m_strRapidLxLaser_Comm_ReceivedData.Length >= 2))         //  수신 데이터 안에 \n 이 1개이면? 정상 데이터.
                        {
                            m_strTemp = m_strRapidLxLaser_Comm_ReceivedData;
                            m_strTemp = m_strTemp.Replace("\r", "");
                            m_strTemp = m_strTemp.Replace("\n", "");

                            string[] words = m_strTemp.Split(' ');

                            if (words.Length >= 2)
                            {
                                //m_dLaser_OutputEnergy = Convert.ToDouble(m_strRapidLxLaser_Comm_ReceivedData.Substring(0, m_strRapidLxLaser_Comm_ReceivedData.Length - 1));
                                m_dLaser_OutputEnergy = Convert.ToDouble(words[1]);
                                m_dLaserComm_ReadSetValue_EnergyPercent = m_dLaser_OutputEnergy;

                                if (m_nLaserComm_SetValue_Get_Process == 0)
                                {
                                    //  Laser Comm 최초 연결 시 세팅된 값을 읽기 위함. (User 세팅 파라미터를 현재 세팅값으로 표시하기 위해서), (0 : Get, 1 : Get Complete, 2 : Set Complete)
                                    m_nLaserComm_SetValue_Get_Process = 1;                  
                                }

                                //  데이터를 사용했으니 초기화
                                m_bRapidLxLaser_CommData_Received = false;
                                m_strRapidLxLaser_Comm_ReceivedData = "";
                                m_nLaserCommRecvData_LF_Count = 0;

                                m_nLaserCommStep = (int)LaserComm_Step.Model_Get;
                            }
                            else
                            {
                                //  데이터 개수가 안맞으니 다시 시도
                                m_bRapidLxLaser_CommData_Received = false;
                                m_strRapidLxLaser_Comm_ReceivedData = "";
                                m_nLaserCommRecvData_LF_Count = 0;

                                m_nLaserCommStep = (int)LaserComm_Step.EnergyPercent_Get;
                            }
                        }
                        else                                            //  수신 데이터 안에 \n 이 2개 이상이면? 데이터가 잘못 들어온 것으로 판단하여 다시 데이터 읽기.
                        {
                            //  데이터 개수가 안맞으니 다시 시도
                            m_bRapidLxLaser_CommData_Received = false;
                            m_strRapidLxLaser_Comm_ReceivedData = "";
                            m_nLaserCommRecvData_LF_Count = 0;

                            m_nLaserCommStep = (int)LaserComm_Step.EnergyPercent_Get;
                        }
                    }
                    else if (TickCount_Elapsed((int)TickType.TICK_LASER_COMM) >= 500)
                    {
                        //  데이터를 사용했으니 초기화
                        m_bRapidLxLaser_CommData_Received = false;
                        m_strRapidLxLaser_Comm_ReceivedData = "";
                        m_nLaserCommRecvData_LF_Count = 0;

                        m_nLaserCommStep = (int)LaserComm_Step.Model_Get;
                    }
                    break;
            }
        }

        #endregion



        #region Main Work Cycle Function (자동 운전)

        void Run_MainWork_Cycle_Func()
        {
            bool m_bRet = false;
            string m_strTemp = "";

            double m_dSpeed = 0.0;
            double m_dAccDec = 0.0;


            //  운전 중 Door 를 열면 장비 Stop
            if (m_nMainWork_Step >= (int)MainWork_Step.Start)
            {
                //if (Config.ParamConfig.AreaSensor_Usage && (waferProbeAlignParameter.DI_AreaSensor_Detect() || waferProbeAlignParameter.DI_AlignJig_Detect()))
                //{
                //    Log.Write("CWA150SA", Equipment.User_Name, "Machine Initialize", "안전 센서 감지로 인한 장비 Stop");

                //    m_bInCycleMoving_SafetySensor_Detected = true;

                //    //  알람 정지 (LED Bar - Red Blink)
                //    Equipment.MachineStop_byAlarm = true;

                //    timer_Motion_Home.Enabled = false;
                //    m_btimer_Motion_Home_Stop = true;

                //    m_nHomeStep = (int)Home_Step.None;

                //    //MC_Func.MC_MotorStop((int)WaferProbeAlignParameter.AxisAjinEnum.U, 500);
                //    //MC_Func.MC_MotorStop((int)WaferProbeAlignParameter.AxisAjinEnum.V, 500);
                //    //MC_Func.MC_MotorStop((int)WaferProbeAlignParameter.AxisAjinEnum.W, 500);
                //    //MC_Func.MC_MotorStop((int)WaferProbeAlignParameter.AxisAjinEnum.EZ, 500);
                //    //MC_Func.MC_MotorStop((int)WaferProbeAlignParameter.AxisAjinEnum.X, 500);
                //    //MC_Func.MC_MotorStop((int)WaferProbeAlignParameter.AxisAjinEnum.Y, 500);
                //    //MC_Func.MC_MotorStop((int)WaferProbeAlignParameter.AxisAjinEnum.VZ, 500);

                //    for (int i = 0; i < (int)AxisAjinEnum.Max; i++)
                //    {
                //        MC_Func.MC_MotorStop(i, 2000);
                //        //MC_Func.MC_EStop(i);
                //    }

                //    if (!Equipment.User_QMC_Engineer)                   //  QMC 관리자가 아닐 경우에만 Home Flag 를 false 로
                //    {
                //        m_bHomeOK = false;                              //  안전센서 감지 시 무조건 장비 초기화 해야 함
                //    }

                //    if (!Equipment.User_QMC_Engineer && Config.ParamConfig.AreaSensor_ServoOff_Usage)           //  안전센서 감지 시 Servo Off 할 경우
                //    {
                //        for (int i = 0; i < (int)AxisAjinEnum.Max; i++)
                //        {
                //            MC_Func.MC_SetServoOnOff(i, false);
                //        }
                //    }
                //}
            }


            //  자동운전 시, Transfer 동작 조건
            if (Equipment.AutoRunStatus &&

                m_nMainWork_Step == (int)MainWork_Step.None)
            {
                //  Dry Run 하기 위한 조건
                if (!m_bMainWorkCycle_Complete &&
                    loader.m_bLoader_Transfer_ModulePutDowntoWorkStage_Complete &&

                    m_bMainWorkCycle_DryRun &&

                    !m_bDryRun_Complete &&

                    (loader.m_nLoader_Transfer_Step == (int)Loader_Transfer_Step.None) &&               //  테스트 후 주석 처리 가능
                    (unloader.m_nUnloader_Transfer_Step == (int)Unloader_Transfer_Step.None) &&         //  테스트 후 주석 처리 가능

                    (m_nDryRun_Step == (int)DryRun_Step.None) &&
                    (m_nLaserDrilling_MainStep == (int)LaserDrilling_Step.None))
                {
                    m_nMainWorkCycleType = (int)MainWorkCycleType.Cycle_DryRun;                     //  Dry Run Cycle
                    m_nMainWork_Step = (int)MainWork_Step.Start;
                }
                //  Laser Drilling 을 위한 조건
                else if (!m_bMainWorkCycle_Complete &&
                    loader.m_bLoader_Transfer_ModulePutDowntoWorkStage_Complete &&

                    !m_bMainWorkCycle_DryRun &&

                    !m_bLaserDrilling_Complete &&

                    (loader.m_nLoader_Transfer_Step == (int)Loader_Transfer_Step.None) &&               //  테스트 후 주석 처리 가능
                    (unloader.m_nUnloader_Transfer_Step == (int)Unloader_Transfer_Step.None) &&         //  테스트 후 주석 처리 가능

                    (m_nDryRun_Step == (int)DryRun_Step.None) &&
                    (m_nLaserDrilling_MainStep == (int)LaserDrilling_Step.None))
                {
                    m_nMainWorkCycleType = (int)MainWorkCycleType.Cycle_LaserDrilling;              //  Laser Drilling Cycle
                    m_nMainWork_Step = (int)MainWork_Step.Start;
                }
            }


            switch (m_nMainWork_Step)
            {
                case (int)MainWork_Step.Start:
                    Log.Write("SLD-200", Equipment.User_Name, "Main Work Cycle", "시작");

                    Equipment.MachineStop_byAlarm = false;

                    //  Work Stage XYZ 축 모터 전체 Stop
                    MC_Func.MC_MotorStop((int)nAxis.X, 2000);
                    MC_Func.MC_MotorStop((int)nAxis.Y, 2000);
                    MC_Func.MC_MotorStop((int)nAxis.Z, 2000);

                    m_nMainWork_Step = (int)MainWork_Step.Process_Type_Check;
                    break;


                case (int)MainWork_Step.Process_Type_Check:
                    Log.Write("SLD-200", Equipment.User_Name, "Main Work Cycle", "동작 타입 확인");

                    switch (m_nMainWorkCycleType)
                    {
                        case (int)MainWorkCycleType.Cycle_DryRun:
                            Log.Write("SLD-200", Equipment.User_Name, "Main Work Cycle", "Dry Run Cycle");
                            m_nMainWork_Step = (int)MainWork_Step.DryRun_Condition_Check;
                            break;

                        case (int)MainWorkCycleType.Cycle_LaserDrilling:
                            Log.Write("SLD-200", Equipment.User_Name, "Main Work Cycle", "Laser Drilling Cycle");
                            m_nMainWork_Step = (int)MainWork_Step.LaserDrilling_Condition_Check;
                            break;

                        default:            //  Error
                            Log.Write("SLD-200", Equipment.User_Name, "Main Work Cycle", "동작 타입 목록에 없음");
                            m_nMainWork_Step = (int)MainWork_Step.Complete;
                            break;
                    }
                    break;



                /// <summary>
                /// Dry Run - 시작
                /// </summary>
                case (int)MainWork_Step.DryRun_Condition_Check:                            //  Dry Run 조건 체크 (Dry Run Mode true, Laser Drilling Complete : false, Work Stage Module Exist, Dry Run Cycle : None)

                    Log.Write("SLD-200", Equipment.User_Name, "Main Work Cycle", "Main Work 동작 조건 체크");

                    if (!m_bMainWorkCycle_DryRun)
                    {
                        Log.Write("SLD-200", Equipment.User_Name, "Main Work Cycle", "Dry Run 모드가 아님.");

                        //  Out.
                        m_nMainWork_Step = (int)Loader_Transfer_Step.None;
                    }
                    else if (m_nLaserDrilling_MainStep != (int)LaserDrilling_Step.None)
                    {
                        Log.Write("SLD-200", Equipment.User_Name, "Main Work Cycle", "Laser Drilling Cycle 진행 중.");

                        //  Out.
                        m_nMainWork_Step = (int)Loader_Transfer_Step.None;
                    }
                    else if (!loader.m_bLoader_Transfer_ModulePutDowntoWorkStage_Complete)
                    {
                        Log.Write("SLD-200", Equipment.User_Name, "Main Work Cycle", "Loader 에서 Module 이 투입되지 않음.");

                        //  Out.
                        m_nMainWork_Step = (int)Loader_Transfer_Step.None;
                    }
                    else
                    {
                        Log.Write("SLD-200", Equipment.User_Name, "Main Work Cycle", "Dry Run 조건 OK");

                        m_nMainWork_Step = (int)MainWork_Step.DryRun_Cycle_Start;
                    }
                    break;


                case (int)MainWork_Step.DryRun_Cycle_Start:                                 //  Dry Run Cycle 시작

                    Log.Write("SLD-200", Equipment.User_Name, "Main Work Cycle", "Dry Run 시작");

                    m_bDryRun_Complete = false;

                    m_nDryRun_Step = (int)DryRun_Step.Start;

                    timer_LaserDrillingWork.Enabled = true;

                    TickCount_Start((int)TickType.TICK_MAIN);

                    m_nMainWork_Step = (int)MainWork_Step.DryRun_Cycle_CompleteCheck;
                    break;


                case (int)MainWork_Step.DryRun_Cycle_CompleteCheck:                         //  Dry Run Cycle 완료 확인

                    if ((m_nDryRun_Step == (int)DryRun_Step.None) && m_bDryRun_Complete)
                    {
                        Log.Write("SLD-200", Equipment.User_Name, "Main Work Cycle", "Dry Run 완료");

                        m_nMainWork_Step = (int)MainWork_Step.Complete;
                    }
                    else if (TickCount_Elapsed((int)TickType.TICK_MAIN) > 60000)
                    {
                        Log.Write("SLD-200", Equipment.User_Name, "Main Work Cycle", "Dry Run 실패. (Timeout)");

                        //  알람 정지 (LED Bar - Red Blink)
                        Equipment.MachineStop_byAlarm = true;

                        //timer_Motion_Home.Enabled = false;
                        //m_btimer_Motion_Home_Stop = true;

                        m_nMainWork_Step = (int)MainWork_Step.None;

                        //MessageBox.Show("Dry Run 실패. (Timeout)", "Error", MessageBoxButtons.OK, MessageBoxIcon.Error);
                    }
                    break;
                /// <summary>
                /// Dry Run - 완료
                /// </summary>
                ///



                /// <summary>
                /// Laser Drilling - 시작
                /// </summary>
                case (int)MainWork_Step.LaserDrilling_Condition_Check:                            //  Laser Drilling 조건 체크 (Dry Run Mode false, Laser Drilling Complete : false, Work Stage Module Exist, Laser Drilling Cycle : None)

                    Log.Write("SLD-200", Equipment.User_Name, "Main Work Cycle", "Main Work 동작 조건 체크");

                    if (m_bMainWorkCycle_DryRun)
                    {
                        Log.Write("SLD-200", Equipment.User_Name, "Main Work Cycle", "Laser 가공 모드가 아님.");

                        //  Out.
                        m_nMainWork_Step = (int)Loader_Transfer_Step.None;
                    }
                    else if (m_nLaserDrilling_MainStep != (int)LaserDrilling_Step.None)
                    {
                        Log.Write("SLD-200", Equipment.User_Name, "Main Work Cycle", "Laser Drilling Cycle 진행 중.");

                        //  Out.
                        m_nMainWork_Step = (int)Loader_Transfer_Step.None;
                    }
                    else if (!loader.m_bLoader_Transfer_ModulePutDowntoWorkStage_Complete)
                    {
                        Log.Write("SLD-200", Equipment.User_Name, "Main Work Cycle", "Loader 에서 Module 이 투입되지 않음.");

                        //  Out.
                        m_nMainWork_Step = (int)Loader_Transfer_Step.None;
                    }
                    else
                    {
                        Log.Write("SLD-200", Equipment.User_Name, "Main Work Cycle", "Laser 가공 조건 OK");

                        m_nMainWork_Step = (int)MainWork_Step.LaserDrilling_Cycle_Start;
                    }
                    break;


                case (int)MainWork_Step.LaserDrilling_Cycle_Start:                                 //  Laser Drilling Cycle 시작

                    Log.Write("SLD-200", Equipment.User_Name, "Main Work Cycle", "Laser Drilling 시작");

                    m_bLaserDrilling_Complete = false;

                    m_nLaserDrilling_MainStep = (int)LaserDrilling_Step.Start;

                    timer_LaserDrillingWork.Enabled = true;

                    //TickCount_Start((int)TickType.TICK_MAIN);

                    m_nMainWork_Step = (int)MainWork_Step.LaserDrilling_Cycle_CompleteCheck;
                    break;


                case (int)MainWork_Step.LaserDrilling_Cycle_CompleteCheck:                         //  Laser Drilling Cycle 완료 확인

                    if ((m_nLaserDrilling_MainStep == (int)LaserDrilling_Step.None) && m_bLaserDrilling_Complete)
                    {
                        Log.Write("SLD-200", Equipment.User_Name, "Main Work Cycle", "Laser Drilling 완료");

                        m_nMainWork_Step = (int)MainWork_Step.Complete;
                    }
                    //else if (TickCount_Elapsed((int)TickType.TICK_MAIN) > 60000)
                    //{
                    //    Log.Write("SLD-200", Equipment.User_Name, "Main Work Cycle", "Laser Drilling 실패. (Timeout)");

                    //    //  알람 정지 (LED Bar - Red Blink)
                    //    Equipment.MachineStop_byAlarm = true;

                    //    //timer_Motion_Home.Enabled = false;
                    //    //m_btimer_Motion_Home_Stop = true;

                    //    m_nMainWork_Step = (int)MainWork_Step.None;

                    //    //MessageBox.Show("Dry Run 실패. (Timeout)", "Error", MessageBoxButtons.OK, MessageBoxIcon.Error);
                    //}
                    break;
                /// <summary>
                /// Laser Drilling - 완료
                /// </summary>
                ///



                case (int)MainWork_Step.Complete:

                    Log.Write("SLD-200", Equipment.User_Name, "Main Work Cycle", "완료");

                    switch (m_nMainWorkCycleType)
                    {
                        case (int)MainWorkCycleType.Cycle_DryRun:
                            Log.Write("SLD-200", Equipment.User_Name, "Main Work Cycle", "Dry Run Cycle 완료");

                            m_bMainWorkCycle_Complete = true;

                            //  Laser Drilling 결과에 따라 OK/NG 다르게 해야 함.
                            m_bMainWorkCycle_ResultOK = true;
                            m_bMainWorkCycle_ResultOK_toRPort = true;
                            break;

                        case (int)MainWorkCycleType.Cycle_LaserDrilling:
                            Log.Write("SLD-200", Equipment.User_Name, "Main Work Cycle", "Laser Drilling Cycle 완료");

                            m_bMainWorkCycle_Complete = true;

                            //  Laser Drilling 결과에 따라 OK/NG 다르게 해야 함.
                            m_bMainWorkCycle_ResultOK = true;
                            m_bMainWorkCycle_ResultOK_toRPort = true;
                            break;

                        default:            //  Error
                            Log.Write("SLD-200", Equipment.User_Name, "Main Work Cycle", "동작 타입 목록에 없음");

                            break;
                    }

                    m_nMainWork_Step = (int)MainWork_Step.None;

                    //  Seq. Test 일 경우
                    if (!Equipment.AutoRunStatus && Equipment.SeqTestMode)
                    {
                        Equipment.SeqTestMode = false;

                        MessageBox.Show(m_strTemp, "Information!", MessageBoxButtons.OK, MessageBoxIcon.Information);
                    }
                    break;
            }
        }

        #endregion



        #region Socket Align
        void Run_SocketAlign_Func(int m_nSocketNum)
        {
            double m_dOffsetX = 0.0;
            double m_dOffsetY = 0.0;

            double lfVelocity = 0.0;
            double lfAccDec = 0.0;

            switch (m_nSocketAlign_MainStep)
            {
                case (int)SocketAlign_Step.Start:
                    //On_LogFile_Add(LOG_OPERATION, "홈 실행 루틴, 시작.");
                    //Display_Event("홈 실행 루틴 : 시작.");

                    Log.Write("SLD100", "Wafer Align", "Align 시작");

                    m_bAlignMarkErrorCheck = false;
                    m_bAlignCompleted = false;

                    m_bSocketAlign_OK = false;

                    for (int i = 0; i < 4; i++)
                    {
                        //  4-Point 의 도면상 위치 데이터
                        m_st4PointPosition_DwgPos[i].ptFiducial_Center.X = 0.0;
                        m_st4PointPosition_DwgPos[i].ptFiducial_Center.Y = 0.0;
                        m_st4PointPosition_DwgPos[i].dFiducial_Width = 0.0;
                        m_st4PointPosition_DwgPos[i].dFiducial_Height = 0.0;

                        //  4-Point 의 측정된 위치 데이터
                        m_st4PointPosition_InspectedPos[i].ptFiducial_Center.X = 0.0;
                        m_st4PointPosition_InspectedPos[i].ptFiducial_Center.Y = 0.0;
                        m_st4PointPosition_InspectedPos[i].dFiducial_Width = 0.0;
                        m_st4PointPosition_InspectedPos[i].dFiducial_Height = 0.0;
                    }

                    m_st4PointAlign_Result.dRotationCenterX = 0.0;
                    m_st4PointAlign_Result.dRotationCenterY = 0.0;
                    m_st4PointAlign_Result.dCenterOffsetX = 0.0;                    
                    m_st4PointAlign_Result.dCenterOffsetY = 0.0;
                    m_st4PointAlign_Result.dRotationAngle = 0.0;

                    m_nSocketAlign_Retry_Max = 3;
                    m_nSocketAlign_Retry_Count = 0;

                    m_nSocketAlign_FiducialCount_Total = m_stDividedRegion_GroupData[m_nSocketNum].dFiducialPos.Length;
                    m_nSocketAlign_FiducialCount = 0;

                    if (Camera_HighRes != null)
                    {
                        Camera_HighRes.StartLive();
                    }

                    CommonModule.Instance.Illuminator.SetVolume(Equipment.stLayerRecipeSet[(int)Equipment.LayerList.Fiducial].IlluminatorValue_FineCamRed, 1);
                    CommonModule.Instance.Illuminator.SetVolume(Equipment.stLayerRecipeSet[(int)Equipment.LayerList.Fiducial].IlluminatorValue_FineCamIR, 2);
                    CommonModule.Instance.Illuminator.SetVolume(Equipment.stLayerRecipeSet[(int)Equipment.LayerList.Fiducial].IlluminatorValue_CoarseCamIR, 3);
                    CommonModule.Instance.Illuminator.TurnOnOff(true, 1);       //  Fine Cam Red 조명
                    CommonModule.Instance.Illuminator.TurnOnOff(true, 2);       //  Fine Cam IR 조명
                    CommonModule.Instance.Illuminator.TurnOnOff(false, 3);      //  Coarse Cam IR 조명은 일단 Off (Coarse Cam 으로 얼라인을 할 때만 켜도록 한다)

                    m_nSocketAlign_MainStep = (int)SocketAlign_Step.AlignSocketData_Load;
                    break;


                case (int)SocketAlign_Step.AlignSocketData_Load:

                    //  얼라인 할 소켓의 데이터를 로드

                    if (m_stDividedRegion_GroupData != null)
                    {
                        if ((m_nSocketNum >= 0) && (m_nSocketNum < m_stDividedRegion_GroupData[0].nGroup_Num))
                        {
                            for (int i = 0; i < 4; i++)
                            {
                                //  4-Point 의 도면상 위치 데이터
                                m_st4PointPosition_DwgPos[i].ptFiducial_Center.X = m_stDividedRegion_GroupData[m_nSocketNum].dFiducialPos[i].X ;
                                m_st4PointPosition_DwgPos[i].ptFiducial_Center.Y = m_stDividedRegion_GroupData[m_nSocketNum].dFiducialPos[i].Y;
                                m_st4PointPosition_DwgPos[i].dFiducial_Width = 0.0;
                                m_st4PointPosition_DwgPos[i].dFiducial_Height = 0.0;
                            }

                            //m_nProductAlign_MainStep = (int)SocketAlign_Step.SocketAlignZ_MoveReadyPos;
                            m_nSocketAlign_MainStep = (int)SocketAlign_Step.__SocketAlign_Start;
                        }
                        else
                        {
                            Log.Write("SLD-200", Equipment.User_Name, "Auto Run", "Align 하려는 Socket 번호를 확인하세요.");

                            //  알람 정지 (LED Bar - Red Blink)
                            Equipment.MachineStop_byAlarm = true;

                            timer_VisionAlign.Enabled = false;

                            m_nSocketAlign_MainStep = (int)SocketAlign_Step.None;

                            MessageBox.Show("Socket 번호에 이상이 있습니다.", "Error", MessageBoxButtons.OK, MessageBoxIcon.Error);
                        }
                    }
                    else
                    {
                        Log.Write("SLD-200", Equipment.User_Name, "Auto Run", "Parsing 된 데이터가 없음.");

                        //  알람 정지 (LED Bar - Red Blink)
                        Equipment.MachineStop_byAlarm = true;

                        timer_VisionAlign.Enabled = false;

                        m_nSocketAlign_MainStep = (int)SocketAlign_Step.None;

                        MessageBox.Show("Parsing 데이터가 없음.", "Error", MessageBoxButtons.OK, MessageBoxIcon.Error);
                    }
                    break;


                case (int)SocketAlign_Step.SocketAlignZ_MoveReadyPos:                                                 //  Satge Z 축, 대기위치(높이)로 이동                       --> 자동운전 중이면 pass

                    Log.Write("SLD100", "Wafer Align", "Z 축 대기위치로 이동 시작");

                    //  속도 설정 (스트로크 짧은 Z축은 느리게)
                    lfVelocity = Equipment.stAxisParam[(int)WorkStage.nAxis.Z].Common_Speed_Fine;
                    lfAccDec = Equipment.stAxisParam[(int)WorkStage.nAxis.Z].Common_Acceleration_Fine;

                    MC_Func.MC_MovePosition((int)WorkStage.nAxis.Z, vision.stVisionTeachingPos[(int)Vision.Vision_TeachingPosList.Vision_SafetyPos].Vision_Z,
                                          lfVelocity, lfAccDec, lfAccDec);

                    TickCount_Start((int)TickType.TICK_ALIGN);

                    m_nSocketAlign_MainStep = (int)SocketAlign_Step.SocketAlignZ_MoveReadyPosDoneCheck;
                    break;


                case (int)SocketAlign_Step.SocketAlignZ_MoveReadyPosDoneCheck:                                        //  Stage Z 축, 대기위치(높이)로 이동 완료 확인
                    if (MC_Func.MC_GetDone((int)WorkStage.nAxis.Z) && MC_Func.MC_PosTolerance((int)WorkStage.nAxis.Z, vision.stVisionTeachingPos[(int)Vision.Vision_TeachingPosList.Vision_SafetyPos].Vision_Z))
                    {
                        Log.Write("SLD100", "Wafer Align", "Z 축 대기위치로 이동 완료");

                        m_nSocketAlign_MainStep = (int)SocketAlign_Step.__SocketAlign_Start;
                    }
                    else if (TickCount_Elapsed((int)TickType.TICK_ALIGN) >= 60000)
                    {
                        //  알람 정지 (LED Bar - Red Blink)
                        Equipment.MachineStop_byAlarm = true;

                        timer_VisionAlign.Enabled = false;

                        m_nSocketAlign_MainStep = (int)SocketAlign_Step.None;
                    }
                    break;


                case (int)SocketAlign_Step.__SocketAlign_Start:                                                         //  비전 Align 검사 시작
                    Log.Write("SLD100", "Wafer Align", "Align Part 시작");

                    m_nSocketAlign_MainStep = (int)SocketAlign_Step.SocketAlign_RemainedCheck;
                    break;


                case (int)SocketAlign_Step.SocketAlign_RemainedCheck:                                                   //  남아있는 얼라인 위치가 있는지 확인 (4개의 얼라인 위치를 모두 확인)

                    if (m_nSocketAlign_FiducialCount < m_nSocketAlign_FiducialCount_Total)                                                               //  Fiducial 마크는 4개
                    {
                        m_nSocketAlign_MainStep = (int)SocketAlign_Step.SocketAlignXY_MoveFiducialPos;
                    }
                    else
                    {
                        m_nSocketAlign_MainStep = (int)SocketAlign_Step.__SocketAlign_Complete;
                    }
                    break;


                case (int)SocketAlign_Step.SocketAlignXY_MoveFiducialPos:                                               //  Stage XY 축, Fiducial Mark 위치로 이동

                    Log.Write("SLD-200", Equipment.User_Name, "Auto Run", "Fiducial 마크 위치로 이동 시작");

                    workStageParameter.stWorkStagePosParam = workStageParameter.GetPositionInformation("Safety");

                    //  좌표계 (기존)
                    workStageParameter.stWorkStagePosParam.dTarget[(int)WorkStageParameter.MotionKey.X] = 0.0;
                    workStageParameter.stWorkStagePosParam.dTarget[(int)WorkStageParameter.MotionKey.Y] = 0.0;

                    //  좌표계 변환 (Stage 좌표계와 Scanner 좌표계를 일치시키지 않을 경우에 사용. Stage 원점 위치에서 Scanner Center 까지의 Offset 거리를 더해서 이동시킨다.)
                    workStageParameter.stWorkStagePosParam.dTarget[(int)WorkStageParameter.MotionKey.X] += Equipment.StageOffset_forDrilling_X;
                    workStageParameter.stWorkStagePosParam.dTarget[(int)WorkStageParameter.MotionKey.Y] += Equipment.StageOffset_forDrilling_Y;

                    //  데이터 위치를 Fine 카메라 위치로 변경
                    workStageParameter.stWorkStagePosParam.dTarget[(int)WorkStageParameter.MotionKey.X] -= Equipment.stOffsetDistance.FromScannerToFineCam.X;
                    workStageParameter.stWorkStagePosParam.dTarget[(int)WorkStageParameter.MotionKey.Y] -= Equipment.stOffsetDistance.FromScannerToFineCam.Y;

                    workStageParameter.stWorkStagePosParam.dTarget[(int)WorkStageParameter.MotionKey.X] -= m_stDividedRegion_GroupData[m_nSocketNum].dFiducialPos[m_nSocketAlign_FiducialCount].X;
                    workStageParameter.stWorkStagePosParam.dTarget[(int)WorkStageParameter.MotionKey.Y] -= m_stDividedRegion_GroupData[m_nSocketNum].dFiducialPos[m_nSocketAlign_FiducialCount].Y;

                    //  속도 설정
                    lfVelocity = Equipment.stAxisParam[(int)WorkStage.nAxis.X].Common_Speed_Coarse;
                    lfAccDec = Equipment.stAxisParam[(int)WorkStage.nAxis.X].Common_Acceleration_Coarse;

                    xyInterpolatedCoordinate.X = workStageParameter.stWorkStagePosParam.dTarget[(int)WorkStageParameter.MotionKey.X];
                    xyInterpolatedCoordinate.Y = workStageParameter.stWorkStagePosParam.dTarget[(int)WorkStageParameter.MotionKey.Y];
                    MC_Func.MovePosition(xyInterpolatedCoordinate, lfVelocity, lfAccDec, lfAccDec);

                    TickCount_Start((int)TickType.TICK_ALIGN);

                    m_nSocketAlign_MainStep = (int)SocketAlign_Step.SocketAlignXY_MoveFiducialPosDoneCheck;
                    break;


                case (int)SocketAlign_Step.SocketAlignXY_MoveFiducialPosDoneCheck:                                      //  Stage XY 축, Fiducial Mark 위치로 이동 완료 확인

                    if (MC_Func.MC_GetDone((int)WorkStage.nAxis.X) && MC_Func.MC_PosTolerance((int)WorkStage.nAxis.X, workStageParameter.stWorkStagePosParam.dTarget[(int)WorkStageParameter.MotionKey.X]) &&
                        MC_Func.MC_GetDone((int)WorkStage.nAxis.Y) && MC_Func.MC_PosTolerance((int)WorkStage.nAxis.Y, workStageParameter.stWorkStagePosParam.dTarget[(int)WorkStageParameter.MotionKey.Y]))
                    {
                        Log.Write("SLD-200", Equipment.User_Name, "Auto Run", "Fiducial 마크 위치로 이동 완료");

                        m_nSocketAlign_MainStep = (int)SocketAlign_Step.SocketAlignZ_MoveInspPos;
                    }
                    else if (TickCount_Elapsed((int)TickType.TICK_ALIGN) > 60000)
                    {
                        Log.Write("SLD-200", Equipment.User_Name, "Auto Run", "Fiducial 마크 위치로 이동 실패. (Timeout)");

                        //  알람 정지 (LED Bar - Red Blink)
                        Equipment.MachineStop_byAlarm = true;

                        timer_VisionAlign.Enabled = false;
                        //m_btimer_Motion_Home_Stop = true;

                        m_nSocketAlign_MainStep = (int)SocketAlign_Step.None;

                        MessageBox.Show("Stage XY 축, Fiducial 마크 위치로 이동 실패", "Error", MessageBoxButtons.OK, MessageBoxIcon.Error);
                    }
                    break;


                case (int)SocketAlign_Step.SocketAlignZ_MoveInspPos:                                                 //  Stage Z 축, 비전 검사 위치(높이)로 이동

                    Log.Write("SLD100", "Wafer Align", "Z 축 비전 검사 위치로 이동 시작");

                    //  속도 설정 (스트로크 짧은 Z축은 느리게)
                    lfVelocity = Equipment.stAxisParam[(int)WorkStage.nAxis.Z].Common_Speed_Fine;
                    lfAccDec = Equipment.stAxisParam[(int)WorkStage.nAxis.Z].Common_Acceleration_Fine;

                    MC_Func.MC_MovePosition((int)WorkStage.nAxis.Z, vision.stVisionTeachingPos[(int)Vision.Vision_TeachingPosList.Vision_FocusPos].Vision_Z,
                                          lfVelocity, lfAccDec, lfAccDec);

                    TickCount_Start((int)TickType.TICK_ALIGN);

                    m_nSocketAlign_MainStep = (int)SocketAlign_Step.SocketAlignZ_MoveInspPosDoneCheck;
                    break;


                case (int)SocketAlign_Step.SocketAlignZ_MoveInspPosDoneCheck:                                        //  Stage Z 축, 비전 검사 위치(높이)로 이동 완료 확인
                    if (MC_Func.MC_GetDone((int)WorkStage.nAxis.Z) && MC_Func.MC_PosTolerance((int)WorkStage.nAxis.Z, vision.stVisionTeachingPos[(int)Vision.Vision_TeachingPosList.Vision_FocusPos].Vision_Z))
                    {
                        Log.Write("SLD100", "Wafer Align", "Z 축 비전 검사 위치로 이동 완료");

                        m_nSocketAlign_MainStep = (int)SocketAlign_Step.SocketAlign_toVision_AlignStart;
                    }
                    else if (TickCount_Elapsed((int)TickType.TICK_ALIGN) >= 60000)
                    {
                        Log.Write("SLD100", "Wafer Align", "Z 축 비전 검사 위치로 이동 실패. (Timeout)");

                        //  알람 정지 (LED Bar - Red Blink)
                        Equipment.MachineStop_byAlarm = true;

                        timer_VisionAlign.Enabled = false;

                        m_nSocketAlign_MainStep = (int)SocketAlign_Step.None;
                    }
                    break;


                case (int)SocketAlign_Step.SocketAlign_toVision_AlignStart:                                           //  Align Start
                    timer_VisionAlign.Enabled = false;

                    Log.Write("SLD100", "Wafer Align", "Align 마크 찾기 시작");

                    Equipment.MachineStop_byUser = false;

                    //jigAligner.Work();

                    //  이미지 Grab
                    Camera_HighRes.Grab();
                    //Camera_HighRes.LatestImage.Save("D:\\TempImage_HighRes_Align.bmp", QMC.Common.Vision.VisionImage.FileFilter.bmp);
                    //bm_AlignImage = new Bitmap("D:\\TempImage_HighRes_Align.bmp");

                    bm_AlignRawData = new byte[Camera_HighRes.Resolution.Width * Camera_HighRes.Resolution.Height];
                    bm_AlignRawData = Camera_HighRes.LatestImage.RawData;

                    //  Circle Find 함수 call
                    Fiducial_aligner = new QMC_ImageProcessFindAlign();
                    Fiducial_circlesResult = new List<RectangleF>();

                    // Bitmap을 byte 배열로 변환
                    //byte[] pixelData = Fiducial_aligner.ConvertBitmapToByteArray(bm_AlignImage);
                    Fiducial_aligner.FindCirclesWidthCircleBoundary(Fiducial_circlesResult, bm_AlignRawData, Camera_HighRes.Resolution.Width, Camera_HighRes.Resolution.Height, ref Fiducial_circleFound);

                    timer_VisionAlign.Enabled = true;

                    m_nSocketAlign_MainStep = (int)SocketAlign_Step.SocketAlign_fromVision_ResultCheck;
                    break;


                case (int)SocketAlign_Step.SocketAlign_fromVision_ResultCheck:                                        //  Align 결과 확인

                    if (Fiducial_circleFound && (Fiducial_circlesResult.Count > 0))
                    {
                        Log.Write("SLD100", "Wafer Align", "Align 마크 찾기 성공");

                        //  4-Point 의 측정된 위치 데이터 (Pixel 좌표이므로, Stage 좌표로 변환해야 한다.)
                        //m_st4PointPosition_InspectedPos[m_nSocketAlign_FiducialCount].ptFiducial_Center.X = Fiducial_circlesResult[0].X;
                        //m_st4PointPosition_InspectedPos[m_nSocketAlign_FiducialCount].ptFiducial_Center.Y = Fiducial_circlesResult[0].Y;
                        //m_st4PointPosition_InspectedPos[m_nSocketAlign_FiducialCount].dFiducial_Width = Fiducial_circlesResult[0].Width;
                        //m_st4PointPosition_InspectedPos[m_nSocketAlign_FiducialCount].dFiducial_Height = Fiducial_circlesResult[0].Height;

                        //  Stage Center 가 0, 0 인 좌표계로 변환
                        m_st4PointPosition_InspectedPos[m_nSocketAlign_FiducialCount].ptFiducial_Center.X = MC_Func.MC_GetEncPos((int)nAxis.X) + 
                                                                                                            ((((double)Fiducial_circlesResult[0].X + ((double)Fiducial_circlesResult[0].Width / 2.0)) - (double)(Camera_HighRes.Resolution.Width / 2)) * Config.ParamConfig.UpperVision_Scale_X);
                        m_st4PointPosition_InspectedPos[m_nSocketAlign_FiducialCount].ptFiducial_Center.Y = MC_Func.MC_GetEncPos((int)nAxis.Y) + 
                                                                                                            (((double)(Camera_HighRes.Resolution.Height / 2) - ((double)Fiducial_circlesResult[0].Y + ((double)Fiducial_circlesResult[0].Height / 2.0))) * Config.ParamConfig.UpperVision_Scale_Y);

                        //  데이터 위치를 Scanner 위치로 변경
                        m_st4PointPosition_InspectedPos[m_nSocketAlign_FiducialCount].ptFiducial_Center.X += Equipment.stOffsetDistance.FromScannerToFineCam.X;
                        m_st4PointPosition_InspectedPos[m_nSocketAlign_FiducialCount].ptFiducial_Center.Y += Equipment.stOffsetDistance.FromScannerToFineCam.Y;

                        //  여기까지는 Fine Camera 기준 위치값이므로, Scanner 위치 것으로 변환해야 한다. (Stage 원점 위치에서 Scanner Center 까지의 Offset 거리 반영)
                        m_st4PointPosition_InspectedPos[m_nSocketAlign_FiducialCount].ptFiducial_Center.X = Equipment.StageOffset_forDrilling_X - m_st4PointPosition_InspectedPos[m_nSocketAlign_FiducialCount].ptFiducial_Center.X;
                        m_st4PointPosition_InspectedPos[m_nSocketAlign_FiducialCount].ptFiducial_Center.Y = Equipment.StageOffset_forDrilling_Y - m_st4PointPosition_InspectedPos[m_nSocketAlign_FiducialCount].ptFiducial_Center.Y;

                        

                        m_st4PointPosition_InspectedPos[m_nSocketAlign_FiducialCount].dFiducial_Width = Fiducial_circlesResult[0].Width * Config.ParamConfig.UpperVision_Scale_X;
                        m_st4PointPosition_InspectedPos[m_nSocketAlign_FiducialCount].dFiducial_Height = Fiducial_circlesResult[0].Height * Config.ParamConfig.UpperVision_Scale_X;

                        m_nSocketAlign_FiducialCount++;

                        m_nSocketAlign_MainStep = (int)SocketAlign_Step.SocketAlign_RemainedCheck;
                    }
                    else
                    {
                        Log.Write("SLD100", "Wafer Align", "Align 마크 찾기 실패. Retry");

                        if (m_nSocketAlign_Retry_Count < m_nSocketAlign_Retry_Max)
                        {
                            m_nSocketAlign_Retry_Count++;

                            //  테스트 하면서 조명값을 변경하여 재시도 하도록 한다.
                            m_nSocketAlign_MainStep = (int)SocketAlign_Step.SocketAlign_toVision_AlignStart;
                        }
                        else
                        {
                            Log.Write("SLD100", "Wafer Align", "Align 마크 찾기 실패. Retry 횟수 초과");

                            //  알람 정지 (LED Bar - Red Blink)
                            Equipment.MachineStop_byAlarm = true;

                            timer_VisionAlign.Enabled = false;

                            m_nSocketAlign_MainStep = (int)SocketAlign_Step.None;
                        }   
                    }
                    break;


                case (int)SocketAlign_Step.__SocketAlign_Complete:                                                    //  비전 검사 완료

                    //  Angle, Offset 계산 (이 값만큼 Dwg 데이터를 보정해서 가공한다.) 
                    m_st4PointAlign_Result = Calc_4Point_AlignData(m_st4PointPosition_DwgPos, m_st4PointPosition_InspectedPos);

                    if ((m_st4PointAlign_Result.dCenterOffsetX == 0.0) && (m_st4PointAlign_Result.dCenterOffsetY == 0.0) && (m_st4PointAlign_Result.dRotationAngle == 0.0))
                    {
                        m_bSocketAlign_OK = false;
                    }
                    else
                    {
                        m_bSocketAlign_OK = true;
                    }

                    //if ((m_nLaserDrilling_MainStep != (int)LaserDrilling_Step.None) ||
                    //    (m_nAlignVerification_MainStep != (int)AlignVerification_Step.None))                            //  자동운전중이거나, 얼라인 Verification Cyc 일 경우, Cycle 완료
                    //{
                    //    timer_VisionAlign.Enabled = false;

                    //    if ((m_forAlign_Data[(int)AlignParam.RESULTPOS_FIRSTMARK].X == 0.0) ||
                    //        (m_forAlign_Data[(int)AlignParam.RESULTPOS_FIRSTMARK].Y == 0.0) ||
                    //        (m_forAlign_Data[(int)AlignParam.RESULTTHETA].X == 0.0))
                    //    {
                    //        m_bProductAlign_OK = false;
                    //    }
                    //    else
                    //    {
                    //        m_dOffsetX = m_forAlign_Data[(int)AlignParam.RESULTPOS_FIRSTMARK].X - Config.ParamConfig.OffsetX_fromCamera_toLaser;
                    //        m_dOffsetY = -(m_forAlign_Data[(int)AlignParam.RESULTPOS_FIRSTMARK].Y - Config.ParamConfig.OffsetY_fromCamera_toLaser);

                    //        m_forAlign_Data[(int)AlignParam.POS_OFFSET].X = m_dOffsetX - m_forAlign_Data[(int)AlignParam.POS_ROTCENTER].X;
                    //        m_forAlign_Data[(int)AlignParam.POS_OFFSET].Y = m_dOffsetY - m_forAlign_Data[(int)AlignParam.POS_ROTCENTER].Y;
                    //        m_forAlign_Data[(int)AlignParam.RESULTTHETA].X = -m_forAlign_Data[(int)AlignParam.RESULTTHETA].X;

                    //        m_bProductAlign_OK = true;
                    //    }

                    //    m_nSocketAlign_MainStep = (int)SocketAlign_Step.None;
                    //}
                    //else                                                                                                //  자동운전중이 아닐 경우
                    //{
                    //    Log.Write("SLD100", "Wafer Align", "자동운전중이 아님. 가공 도면 보정 완료");

                    //    //m_nProductAlign_MainStep = (int)SocketAlign_Step.ProductAlignXY_MoveReadyPos;

                    //    //m_nProductAlign_MainStep = (int)SocketAlign_Step.ProductAlign_RotAndOffsetMove;
                    //    m_nSocketAlign_MainStep = (int)SocketAlign_Step.Complete;
                    //}


                    //  가공 중에 얼라인을 하는 것이면, 여기에서 마무리
                    if (Equipment.AutoRunStatus || m_nLaserDrilling_MainStep != (int)LaserDrilling_Step.None)
                    {                        
                        m_bAlignCompleted = true;

                        m_nSocketAlign_MainStep = (int)SocketAlign_Step.None;
                    }
                    else
                    {
                        m_nSocketAlign_MainStep = (int)SocketAlign_Step.SocketAlignZ_MoveReadyPos2;
                    }

                    break;


                case (int)SocketAlign_Step.SocketAlignZ_MoveReadyPos2:                                                 //  Satge Z 축, 대기위치(높이)로 이동                       --> 자동운전 중이면 pass

                    Log.Write("SLD100", "Wafer Align", "Z 축, 대기위치로 이동 시작");

                    //  속도 설정 (스트로크 짧은 Z축은 느리게)
                    lfVelocity = Equipment.stAxisParam[(int)WorkStage.nAxis.Z].Common_Speed_Fine;
                    lfAccDec = Equipment.stAxisParam[(int)WorkStage.nAxis.Z].Common_Acceleration_Fine;

                    MC_Func.MC_MovePosition((int)WorkStage.nAxis.Z, vision.stVisionTeachingPos[(int)Vision.Vision_TeachingPosList.Vision_SafetyPos].Vision_Z,
                                          lfVelocity, lfAccDec, lfAccDec);

                    TickCount_Start((int)TickType.TICK_ALIGN);

                    m_nSocketAlign_MainStep = (int)SocketAlign_Step.SocketAlignZ_MoveReadyPos2DoneCheck;
                    break;


                case (int)SocketAlign_Step.SocketAlignZ_MoveReadyPos2DoneCheck:                                        //  Stage Z 축, 대기위치(높이)로 이동 완료 확인
                    if (MC_Func.MC_GetDone((int)WorkStage.nAxis.Z) && MC_Func.MC_PosTolerance((int)WorkStage.nAxis.Z, vision.stVisionTeachingPos[(int)Vision.Vision_TeachingPosList.Vision_SafetyPos].Vision_Z))
                    {
                        Log.Write("SLD100", "Wafer Align", "Z 축, 대기위치로 이동 완료");

                        m_nSocketAlign_MainStep = (int)SocketAlign_Step.SocketAlignXY_MoveReadyPos;
                    }
                    else if (TickCount_Elapsed((int)TickType.TICK_ALIGN) >= 60000)
                    {
                        //  알람 정지 (LED Bar - Red Blink)
                        Equipment.MachineStop_byAlarm = true;

                        timer_VisionAlign.Enabled = false;

                        m_nSocketAlign_MainStep = (int)SocketAlign_Step.None;
                    }
                    break;


                case (int)SocketAlign_Step.SocketAlignXY_MoveReadyPos:                                               //  Stage XY 축, 대기위치로 이동                             --> 자동운전 중이면 pass

                    Log.Write("SLD-200", Equipment.User_Name, "Auto Run", "XY 축, 대기위치로 이동 시작");

                    //  속도 설정
                    lfVelocity = Equipment.stAxisParam[(int)WorkStage.nAxis.X].Common_Speed_Coarse;
                    lfAccDec = Equipment.stAxisParam[(int)WorkStage.nAxis.X].Common_Acceleration_Coarse;

                    xyInterpolatedCoordinate.X = stWorkStageTeachingPos[(int)WorkStage_TeachingPosList.STAGE_SafetyPos].Stage_X;
                    xyInterpolatedCoordinate.Y = stWorkStageTeachingPos[(int)WorkStage_TeachingPosList.STAGE_SafetyPos].Stage_Y;
                    MC_Func.MovePosition(xyInterpolatedCoordinate, lfVelocity, lfAccDec, lfAccDec);

                    TickCount_Start((int)TickType.TICK_ALIGN);

                    m_nSocketAlign_MainStep = (int)SocketAlign_Step.SocketAlignXY_MoveReadyPosDoneCheck;
                    break;


                case (int)SocketAlign_Step.SocketAlignXY_MoveReadyPosDoneCheck:                                      //  Stage XY 축, 대기위치로 이동 완료 확인

                    if (MC_Func.MC_GetDone((int)WorkStage.nAxis.X) && MC_Func.MC_PosTolerance((int)WorkStage.nAxis.X, stWorkStageTeachingPos[(int)WorkStage_TeachingPosList.STAGE_SafetyPos].Stage_X) &&
                        MC_Func.MC_GetDone((int)WorkStage.nAxis.Y) && MC_Func.MC_PosTolerance((int)WorkStage.nAxis.Y, stWorkStageTeachingPos[(int)WorkStage_TeachingPosList.STAGE_SafetyPos].Stage_Y))
                    {
                        Log.Write("SLD-200", Equipment.User_Name, "Auto Run", "XY 축, 대기위치로 이동 완료");

                        m_nSocketAlign_MainStep = (int)SocketAlign_Step.SocketAlign_RotAndOffsetMove;
                    }
                    else if (TickCount_Elapsed((int)TickType.TICK_ALIGN) > 60000)
                    {
                        Log.Write("SLD-200", Equipment.User_Name, "Auto Run", "XY 축, 대기위치로 이동 실패. (Timeout)");

                        //  알람 정지 (LED Bar - Red Blink)
                        Equipment.MachineStop_byAlarm = true;

                        timer_VisionAlign.Enabled = false;
                        //m_btimer_Motion_Home_Stop = true;

                        m_nSocketAlign_MainStep = (int)SocketAlign_Step.None;

                        MessageBox.Show("Stage XY 축, XY 축, 대기위치로 이동 실패", "Error", MessageBoxButtons.OK, MessageBoxIcon.Error);
                    }
                    break;


                case (int)SocketAlign_Step.SocketAlign_RotAndOffsetMove:                                        //  가공 데이터 회전 및 Offset 이동
                                        
                    m_dALIGN_FACTOR_RotationCenter_X = m_st4PointAlign_Result.dRotationCenterX;                                 //  전체 가공 도면 회전 중심 X
                    m_dALIGN_FACTOR_RotationCenter_Y = m_st4PointAlign_Result.dRotationCenterY;                                 //  전체 가공 도면 회전 중심 Y
                    m_dALIGN_FACTOR_Offset_X = m_st4PointAlign_Result.dCenterOffsetX;                                           //  전체 가공 도면 이동 Offset X
                    m_dALIGN_FACTOR_Offset_Y = m_st4PointAlign_Result.dCenterOffsetY;                                           //  전체 가공 도면 이동 Offset Y
                    m_dALIGN_FACTOR_Theta = m_st4PointAlign_Result.dRotationAngle;                                             //  전체 가공 도면 회전 (Theta,     기준위치 : Align1 (Thruhole 의 Circle 객체, Description 에 Align1 표시)

                    m_dALIGN_FACTOR_Offset_Y += 30.0;

                    //DrillingData_RotationOffset_Move(m_dALIGN_FACTOR_RotationCenter_X, m_dALIGN_FACTOR_RotationCenter_Y, m_dALIGN_FACTOR_Theta, m_dALIGN_FACTOR_Offset_X, m_dALIGN_FACTOR_Offset_Y);
                    AlignedDrillingData_Select_and_OffsetMove(m_nSocketNum_forAlign, m_dALIGN_FACTOR_RotationCenter_X, m_dALIGN_FACTOR_RotationCenter_Y, m_dALIGN_FACTOR_Offset_X, m_dALIGN_FACTOR_Offset_Y, m_dALIGN_FACTOR_Theta);

                    Log.Write("SLD100", "Wafer Align", "Wafer Align 각도 보정 완료");

                    m_nSocketAlign_MainStep = (int)SocketAlign_Step.SocketAlign_Reload;
                    break;


                case (int)SocketAlign_Step.SocketAlign_Reload:                                                  //  가공 데이터를 회전했으면 데이터를 다시 불러온다.

                    //  Get Data
                    int m_nReturn = (int)WorkStage.nGetDataResult.GETDATA_FAIL;

                    Log.Write("SLD100", "Wafer Align", "Align 후 가공 데이터 다시 Parsing 시작");

                    m_nReturn = GetDrillingData();
                    switch (m_nReturn)
                    {
                        case (int)WorkStage.nGetDataResult.GETDATA_SUCCESS:
                            Log.Write("SLD-200", Equipment.User_Name, "Auto Run", "가공 데이터 Parsing 성공");

                            m_nLaserDrilling_LayerCount = 0;

                            m_bAlignCompleted = true;

                            timer_VisionAlign.Enabled = false;
                            m_nSocketAlign_MainStep = (int)SocketAlign_Step.None;
                            break;

                        case (int)WorkStage.nGetDataResult.GETDATA_FAIL:
                            Log.Write("SLD-200", "Auto Run", "가공 데이터가 정상적으로 로드 되지 않았습니다.");

                            timer_VisionAlign.Enabled = false;
                            //m_bExit = true;
                            MessageBox.Show("데이터가 정상적으로 로드 되지 않았습니다.", "Information !");
                            m_nSocketAlign_MainStep = (int)SocketAlign_Step.None;
                            break;

                        case (int)WorkStage.nGetDataResult.GETDATA_NOT_GROUP:
                            Log.Write("SLD-200", "Auto Run", "가공 데이터가 Group 이 아닙니다.");

                            timer_VisionAlign.Enabled = false;
                            //m_bExit = true;
                            MessageBox.Show("데이터가 Group 이 아닙니다.", "Information !");
                            m_nSocketAlign_MainStep = (int)SocketAlign_Step.None;
                            break;

                        case (int)WorkStage.nGetDataResult.GETDATA_UNGROUP:
                            Log.Write("SLD-200", "Auto Run", "가공 데이터를 Group 해제 해야 합니다.");

                            timer_VisionAlign.Enabled = false;
                            //m_bExit = true;
                            MessageBox.Show("데이터를 Group 해제 해야 합니다.", "Information !");
                            m_nSocketAlign_MainStep = (int)SocketAlign_Step.None;
                            break;

                        case (int)WorkStage.nGetDataResult.GETDATA_LAYERNAME_NG:
                            Log.Write("SLD-200", "Auto Run", "가공 데이터 Layer Name 은 'Hole1~4', 'Rect', 'Outline', 'Marking', 'Fiducial' 5가지만 가능합니다.");

                            timer_VisionAlign.Enabled = false;
                            //m_bExit = true;
                            MessageBox.Show("Layer Name 은 'Hole1~4', 'Rect', 'Outline', 'Marking', 'Fiducial' 5가지만 가능합니다.", "Information !");
                            m_nSocketAlign_MainStep = (int)SocketAlign_Step.None;
                            break;

                        case (int)WorkStage.nGetDataResult.GETDATA_MOTIONTYPE_NG:
                            Log.Write("SLD-200", "Auto Run", "가공 데이터 Layer Motion Type 은 'StageAndScanner', 'ScannerOnly' 2가지만 가능합니다.");

                            timer_VisionAlign.Enabled = false;
                            //m_bExit = true;
                            MessageBox.Show("Layer Motion Type 은 'StageAndScanner', 'ScannerOnly' 2가지만 가능합니다.", "Information !");
                            m_nSocketAlign_MainStep = (int)SocketAlign_Step.None;
                            break;

                        case (int)WorkStage.nGetDataResult.GETDATA_DRILDATA_NG:
                            Log.Write("SLD-200", "Auto Run", "가공 데이터 중 Drilling Data 는 Polyline, Rectangle, Line, Circle, Arc 중 한 가지로만 구성되어야 합니다.");

                            timer_VisionAlign.Enabled = false;
                            //m_bExit = true;
                            MessageBox.Show("Drilling Data 는 Polyline, Line, Circle 중 한 가지 데이터로만 구성되어야 합니다.", "Information !");
                            m_nSocketAlign_MainStep = (int)SocketAlign_Step.None;
                            break;

                        case (int)WorkStage.nGetDataResult.GETDATA_DRILDATA_LINECNT:
                            Log.Write("SLD-200", "Auto Run", "가공 데이터 중 Drilling Data 의 Line 데이터 개수가 4의 배수가 아닙니다.");

                            timer_VisionAlign.Enabled = false;
                            //m_bExit = true;
                            MessageBox.Show("Drilling Data 에 Line 데이터 개수가 4의 배수가 아닙니다.", "Information !");
                            m_nSocketAlign_MainStep = (int)SocketAlign_Step.None;
                            break;

                        case (int)WorkStage.nGetDataResult.GETDATA_DRILDATA_NOT_CLOSED:
                            Log.Write("SLD-200", "Auto Run", "가공 데이터 중 Drilling Data 의 Line 이 닫힌 도형이 아닙니다.");

                            timer_VisionAlign.Enabled = false;
                            //m_bExit = true;
                            MessageBox.Show("Line 으로 이루어진 Drilling Data 가 닫힌 도형이 아닙니다.", "Information !");
                            m_nSocketAlign_MainStep = (int)SocketAlign_Step.None;
                            break;

                        case (int)WorkStage.nGetDataResult.GETDATA_RTCINIT:
                            Log.Write("SLD-200", "Auto Run", "RTC 보드가 초기화 되지 않았습니다.");

                            timer_VisionAlign.Enabled = false;
                            //m_bExit = true;
                            MessageBox.Show("RTC 보드가 초기화 되지 않았습니다.", "Information !");
                            m_nSocketAlign_MainStep = (int)SocketAlign_Step.None;
                            break;
                    }
                    break;


                case (int)SocketAlign_Step.Complete:

                    m_bAlignCompleted = true;

                    timer_VisionAlign.Enabled = false;

                    //if ((m_forAlign_Data[(int)AlignParam.RESULTPOS_FIRSTMARK].X == 0.0) ||
                    //    (m_forAlign_Data[(int)AlignParam.RESULTPOS_FIRSTMARK].Y == 0.0) ||
                    //    (m_forAlign_Data[(int)AlignParam.RESULTTHETA].X == 0.0))
                    if ((m_st4PointAlign_Result.dCenterOffsetX == 0.0) ||
                        (m_st4PointAlign_Result.dCenterOffsetY == 0.0) ||
                        (m_st4PointAlign_Result.dRotationAngle == 0.0))
                    {
                        m_bSocketAlign_OK = false;

                        MessageBox.Show("Align 이동량 계산 실패.", "Information!");
                    }
                    else
                    {
                        //m_dOffsetX = m_forAlign_Data[(int)AlignParam.RESULTPOS_FIRSTMARK].X - Config.ParamConfig.OffsetX_fromCamera_toLaser;
                        //m_dOffsetY = -(m_forAlign_Data[(int)AlignParam.RESULTPOS_FIRSTMARK].Y - Config.ParamConfig.OffsetY_fromCamera_toLaser);

                        //m_forAlign_Data[(int)AlignParam.POS_OFFSET].X = m_dOffsetX - m_forAlign_Data[(int)AlignParam.POS_ROTCENTER].X;
                        //m_forAlign_Data[(int)AlignParam.POS_OFFSET].Y = m_dOffsetY - m_forAlign_Data[(int)AlignParam.POS_ROTCENTER].Y;
                        //m_forAlign_Data[(int)AlignParam.RESULTTHETA].X = -m_forAlign_Data[(int)AlignParam.RESULTTHETA].X;

                        m_bSocketAlign_OK = true;

                        //MessageBox.Show("Align 이동량 계산 성공.", "Information!");

                        string m_strTemp = "";
                        m_strTemp = "Align 이동량 계산 성공.\r\n\r\n" +
                                    "- Offset X : " + m_st4PointAlign_Result.dCenterOffsetX.ToString() + "\r\n" +
                                    "- Offset Y : " + m_st4PointAlign_Result.dCenterOffsetY.ToString() + "\r\n" +
                                    "- Angle : " + m_st4PointAlign_Result.dRotationAngle.ToString();
                        MessageBox.Show(m_strTemp);
                    }

                    m_nSocketAlign_MainStep = (int)SocketAlign_Step.None;
                    break;
            }
        }
        #endregion



        #region Dry Run Cycle Function

        private void Func_DryRun_Cycle()
        {
            bool success = true;
            string m_strTemp = "";

            double lfVelocity = 0.0f;
            double lfAccDec = 0.0f;


            switch (m_nDryRun_Step)
            {
                case (int)DryRun_Step.Start:
                    Log.Write("SLD-200", "Auto Run", "DryRun 시작");

                    m_bDryRun_Complete = false;

                    m_nDryRun_Step = (int)DryRun_Step.StageZ_MoveReadyPos;
                    break;


                case (int)DryRun_Step.StageZ_MoveReadyPos:                                      //  Z 축, 대기 위치로 이동

                    Log.Write("SLD-200", Equipment.User_Name, "Auto Run", "Stage Z 축, 대기 위치로 이동 시작");

                    //  속도 설정 (스트로크 짧은 Z축은 느리게)
                    lfVelocity = Equipment.stAxisParam[(int)WorkStage.nAxis.Z].Common_Speed_Fine;
                    lfAccDec = Equipment.stAxisParam[(int)WorkStage.nAxis.Z].Common_Acceleration_Fine;

                    MC_Func.MC_MovePosition((int)WorkStage.nAxis.Z, vision.stVisionTeachingPos[(int)Vision.Vision_TeachingPosList.Vision_SafetyPos].Vision_Z,
                                          lfVelocity, lfAccDec, lfAccDec);

                    TickCount_Start((int)TickType.TICK_MAIN);

                    m_nDryRun_Step = (int)DryRun_Step.StageZ_MoveReadyPos_DoneCheck;
                    break;


                case (int)DryRun_Step.StageZ_MoveReadyPos_DoneCheck:                            //  Z 축, 대기 위치로 이동 완료 체크

                    if (MC_Func.MC_GetDone((int)WorkStage.nAxis.Z) && MC_Func.MC_PosTolerance((int)WorkStage.nAxis.Z, vision.stVisionTeachingPos[(int)Vision.Vision_TeachingPosList.Vision_SafetyPos].Vision_Z))
                    {
                        Log.Write("SLD-200", Equipment.User_Name, "Auto Run", "Stage Z 축, 대기 위치로 이동 완료 확인");

                        m_nDryRun_Step = (int)DryRun_Step.StageXY_MoveCenterPos;
                    }
                    else if (TickCount_Elapsed((int)TickType.TICK_MAIN) > 60000)
                    {
                        Log.Write("SLD-200", Equipment.User_Name, "Auto Run", "Stage Z 축, 대기 위치로 이동 실패. (Timeout)");

                        //  알람 정지 (LED Bar - Red Blink)
                        Equipment.MachineStop_byAlarm = true;

                        //timer_LaserDrillingWork.Enabled = false;
                        //m_btimer_Motion_Home_Stop = true;

                        m_nDryRun_Step = (int)DryRun_Step.None;

                        MessageBox.Show("Stage Z 축, 대기 위치로 이동 실패", "Error", MessageBoxButtons.OK, MessageBoxIcon.Error);
                    }
                    break;


                case (int)DryRun_Step.StageXY_MoveCenterPos:                              //  XY 축, Stage Center 위치로 이동

                    Log.Write("SLD-200", Equipment.User_Name, "Auto Run", "Stage XY 축, Stage Center 위치로 이동 시작");

                    //  속도 설정
                    lfVelocity = Equipment.stAxisParam[(int)WorkStage.nAxis.X].Common_Speed_Coarse;
                    lfAccDec = Equipment.stAxisParam[(int)WorkStage.nAxis.X].Common_Acceleration_Coarse;

                    xyInterpolatedCoordinate.X = stWorkStageTeachingPos[(int)WorkStage_TeachingPosList.STAGE_ProcessingPos].Stage_X;
                    xyInterpolatedCoordinate.Y = stWorkStageTeachingPos[(int)WorkStage_TeachingPosList.STAGE_ProcessingPos].Stage_Y;
                    MC_Func.MovePosition(xyInterpolatedCoordinate, lfVelocity, lfAccDec, lfAccDec);

                    TickCount_Start((int)TickType.TICK_MAIN);

                    m_nDryRun_Step = (int)DryRun_Step.StageXY_MoveCenterPos_DoneCheck;
                    break;


                case (int)DryRun_Step.StageXY_MoveCenterPos_DoneCheck:                 //  XY 축, Stage Center 위치로 이동 완료 체크           

                    if (MC_Func.MC_GetDone((int)WorkStage.nAxis.X) && MC_Func.MC_PosTolerance((int)WorkStage.nAxis.X, stWorkStageTeachingPos[(int)WorkStage_TeachingPosList.STAGE_ProcessingPos].Stage_X) &&
                        MC_Func.MC_GetDone((int)WorkStage.nAxis.Y) && MC_Func.MC_PosTolerance((int)WorkStage.nAxis.Y, stWorkStageTeachingPos[(int)WorkStage_TeachingPosList.STAGE_ProcessingPos].Stage_Y))
                    {
                        Log.Write("SLD-200", Equipment.User_Name, "Auto Run", "Stage XY 축, Stage Center 위치로 이동 완료 확인");

                        m_nDryRun_Step = (int)DryRun_Step.Complete;
                    }
                    else if (TickCount_Elapsed((int)TickType.TICK_MAIN) > 60000)
                    {
                        Log.Write("SLD-200", Equipment.User_Name, "Auto Run", "Stage XY 축, Stage Center 위치로 이동 실패. (Timeout)");

                        //  알람 정지 (LED Bar - Red Blink)
                        Equipment.MachineStop_byAlarm = true;

                        //timer_LaserDrillingWork.Enabled = false;
                        //m_btimer_Motion_Home_Stop = true;

                        m_nDryRun_Step = (int)DryRun_Step.None;

                        MessageBox.Show("Stage XY 축, Stage Center 위치로 이동 실패", "Error", MessageBoxButtons.OK, MessageBoxIcon.Error);
                    }
                    break;


                case (int)DryRun_Step.Complete:

                    m_bDryRun_Complete = true;

                    m_nDryRun_Step = (int)DryRun_Step.None;
                    break;
            }
        }

        #endregion



