        /// <summary>
        /// 회전 이동
        /// </summary>
        /// 
        public PointD[] rotatePolygon(PointD[] m_polygon, PointD m_centroid, double m_angle)
        {
            for (int i = 0; i < m_polygon.Length; i++)
            {
                m_pPolygon_Temp[i] = rotatePoint(m_polygon[i], m_centroid, m_angle);
            }

            return m_pPolygon_Temp;
        }

        public PointD rotatePoint(PointD point, PointD centroid, double radian)
        {
            double x = centroid.X + ((point.X - centroid.X) * Math.Cos(radian) - (point.Y - centroid.Y) * Math.Sin(radian));
            double y = centroid.Y + ((point.X - centroid.X) * Math.Sin(radian) + (point.Y - centroid.Y) * Math.Cos(radian));

            m_pRet.X = x;
            m_pRet.Y = y;

            return m_pRet;
        }


