            //if (m_dTotal_MarkingJumpLength > 0.0)
            //{
            //    Equipment.WorkTotalTime_Marking += (m_dTotal_MarkingJumpLength / Config.ParamConfig.Marking_Jump_Speed) * (Config.ParamConfig.Marking_Repeat_Count == 0 ? 1.0 : Config.ParamConfig.Marking_Repeat_Count);
            //}
            //if (m_dTotal_MarkingDataLength > 0.0)
            //{
            //    Equipment.WorkTotalTime_Marking += (m_dTotal_MarkingDataLength / Config.ParamConfig.Marking_Mark_Speed) * (Config.ParamConfig.Marking_Repeat_Count == 0 ? 1.0 : Config.ParamConfig.Marking_Repeat_Count);
            //}

            //Equipment.WorkTotalTime = Equipment.WorkTotalTime_Outline + Equipment.WorkTotalTime_Thruhole + Equipment.WorkTotalTime_Drilling + Equipment.WorkTotalTime_Marking;

            return success == true ? (int)nGetDataResult.GETDATA_SUCCESS : (int)nGetDataResult.GETDATA_FAIL;            //   0 : "데이터가 정상적으로 로드 되었습니다."
                                                                                                                        //  -1 : "데이터가 정상적으로 로드 되지 않았습니다."
        }

        // 4개의 원 좌표를 좌하단, 좌상단, 우상단, 우하단 순서로 정렬하는 메서드 (LB 에서 시작하여 CW 방향으로 정렬)
        private PointD[] SortCircles(PointD[] circles)
        {
            // y 값을 기준으로 정렬하여 상단과 하단을 구분
            var sortedByY = circles.OrderBy(p => p.Y).ToArray();
            var bottomTwo = sortedByY.Take(2).OrderBy(p => p.X).ToArray(); // 상단 좌표들        --> 좌표계 문제로 "topTwo" 를 "bottomTwo" 로 변경
            var topTwo = sortedByY.Skip(2).OrderBy(p => p.X).ToArray(); // 하단 좌표들           --> 좌표계 문제로 "bottomTwo" 를 "topTwo" 로 변경

            return new PointD[]
            {
                bottomTwo[0], // 좌하단
                topTwo[0], // 좌상단
                topTwo[1], // 우상단
                bottomTwo[1], // 우하단                
            };
        }

        protected void CreateProcessDrillingVectors()
        {
            List<Vector2> listVectors = new List<Vector2>();
            int nCount = m_stDividedRegion_GroupData[m_nGroupCount].nGroup_RegionCount;
            for (int i = 0; i < nCount; i++)
            {
                stDividedRegion_RegionData data = m_stDividedRegion_GroupData[m_nGroupCount].m_stDividedRegion_RegionData[i];
                for (int j = 0; j < data.nRegion_ObjectTotalNum; j++)
                {
                    stDividedRegion_ObjectData objectData = data.m_stDividedRegion_ObjectData[j];
                    listVectors.Clear();
                    switch (objectData.nObjectType)
                    {
                        case (int)ObjectType.OBJECT_POLY:
                            //if (Config.ParamConfig.bDrillingSizeReduce_Enable)
                            if (Config.ParamConfig.bPreDrilling_Use)
                            {
                                //  Object Min, Max 체크 (X, Y)   --> 이 크기에서 Reduce Size 만큼 줄임
                                entity_Pos_Min.X = double.MaxValue;
                                entity_Pos_Min.Y = double.MaxValue;
                                entity_Pos_Max.X = double.MinValue;
                                entity_Pos_Max.Y = double.MinValue;
                                for (int nChkEntity = 0; nChkEntity < objectData.nEdgePointNum; nChkEntity++)
                                {
                                    if (entity_Pos_Min.X >= objectData.dEdgePoint[nChkEntity].X)
                                    {
                                        entity_Pos_Min.X = objectData.dEdgePoint[nChkEntity].X;
                                    }
                                    if (entity_Pos_Min.Y >= objectData.dEdgePoint[nChkEntity].Y)
                                    {
                                        entity_Pos_Min.Y = objectData.dEdgePoint[nChkEntity].Y;
                                    }
                                    if (entity_Pos_Max.X <= objectData.dEdgePoint[nChkEntity].X)
                                    {
                                        entity_Pos_Max.X = objectData.dEdgePoint[nChkEntity].X;
                                    }
                                    if (entity_Pos_Max.Y <= objectData.dEdgePoint[nChkEntity].Y)
                                    {
                                        entity_Pos_Max.Y = objectData.dEdgePoint[nChkEntity].Y;
                                    }
                                }

                                //  Reduce Size 적용하여 Edge Point 다시 계산
                                //  Edge Point 개수 : 5개 (Left Top --> Left Bottom --> Right Bottom --> Right Top --> Left Top)
                                //  Left-Top (시작점)
                                objectData.dEdgePoint_PreDrilling[0].X =
                                    entity_Pos_Min.X + (Config.ParamConfig.PreDrilling_ReduceSize / 2.0);
                                objectData.dEdgePoint_PreDrilling[0].Y =
                                    entity_Pos_Max.Y - (Config.ParamConfig.PreDrilling_ReduceSize / 2.0);
                                //  Left-Bottom
                                objectData.dEdgePoint_PreDrilling[1].X =
                                    entity_Pos_Min.X + (Config.ParamConfig.PreDrilling_ReduceSize / 2.0);
                                objectData.dEdgePoint_PreDrilling[1].Y =
                                    entity_Pos_Min.Y + (Config.ParamConfig.PreDrilling_ReduceSize / 2.0);
                                //  Right-Bottom
                                objectData.dEdgePoint_PreDrilling[2].X =
                                    entity_Pos_Max.X - (Config.ParamConfig.PreDrilling_ReduceSize / 2.0);
                                objectData.dEdgePoint_PreDrilling[2].Y =
                                    entity_Pos_Min.Y + (Config.ParamConfig.PreDrilling_ReduceSize / 2.0);
                                //  Right-Top
                                objectData.dEdgePoint_PreDrilling[3].X =
                                    entity_Pos_Max.X - (Config.ParamConfig.PreDrilling_ReduceSize / 2.0);
                                objectData.dEdgePoint_PreDrilling[3].Y =
                                    entity_Pos_Max.Y - (Config.ParamConfig.PreDrilling_ReduceSize / 2.0);
                                //  Left-Top (다시 시작점으로)
                                objectData.dEdgePoint_PreDrilling[4].X =
                                    entity_Pos_Min.X + (Config.ParamConfig.PreDrilling_ReduceSize / 2.0);
                                objectData.dEdgePoint_PreDrilling[4].Y =
                                    entity_Pos_Max.Y - (Config.ParamConfig.PreDrilling_ReduceSize / 2.0);
                            }

                            //  첫 번째 Edge Point 로 Jump 이동
                            entity_Position.X = objectData.dEdgePoint_PreDrilling[0].X -
                                                data.dRegionCenter.X;
                            entity_Position.Y = objectData.dEdgePoint_PreDrilling[0].Y -
                                                data.dRegionCenter.Y;

                            entity_Position_Rot = RotatePoint(scanner_Center, entity_Position, Math.PI / 2.0);

                            //if (Equipment.RtcMode_syncAxis == (int)Equipment.RtcMode.RTC_SYNCAXIS)
                            //{
                            //    data.JumpVector = new Vector2((float)entity_Position.X, (float)entity_Position.Y);
                            //}
                            //else if (Equipment.RtcMode_syncAxis == (int)Equipment.RtcMode.RTC_RTC6)
                            {
                                data.JumpVector = new Vector2((float)entity_Position_Rot.X, (float)entity_Position_Rot.Y);
                            }

                            //  이어서 오는 Edge Point 로 Mark 이동(cont') 하여 Polyline 완성
                            data.nVectorCount = objectData.nEdgePointNum;
                            data.Vectors = new Vector2[objectData.nEdgePointNum];
                            for (int nEntity = 1; nEntity < objectData.nEdgePointNum; nEntity++)
                            {
                                entity_Position.X = objectData.dEdgePoint_PreDrilling[nEntity].X -
                                                    data.dRegionCenter.X;
                                entity_Position.Y = objectData.dEdgePoint_PreDrilling[nEntity].Y -
                                                    data.dRegionCenter.Y;

                                entity_Position_Rot = RotatePoint(scanner_Center, entity_Position, Math.PI / 2.0);

                                //if (Equipment.RtcMode_syncAxis == (int)Equipment.RtcMode.RTC_SYNCAXIS)
                                //{
                                //    data.Vectors[nEntity] = new Vector2((float)entity_Position.X, (float)entity_Position.Y);
                                //}
                                //else if (Equipment.RtcMode_syncAxis == (int)Equipment.RtcMode.RTC_RTC6)
                                {
                                    data.Vectors[nEntity] = new Vector2((float)entity_Position_Rot.X, (float)entity_Position_Rot.Y);
                                }
                            }
                            break;


                        case (int)ObjectType.OBJECT_CIR:
                            //if (Config.ParamConfig.bDrillingSizeReduce_Enable)
                            if (Config.ParamConfig.bPreDrilling_Use)
                            {
                                //  반지름에서 Reduce Size 만큼 줄임
                                objectData.dEdgePoint_PreDrilling[1].X =
                                    objectData.dEdgePoint[1].X - (Config.ParamConfig.PreDrilling_ReduceSize / 2.0);
                            }

                            //  첫 번째 Edge Point 로 Jump 이동. (원 모양이므로 반지름 만큼 왼쪽으로)
                            entity_Position.X = objectData.dEdgePoint[0].X -
                                                data.dRegionCenter.X +
                                                objectData.dEdgePoint_PreDrilling[1].X;           //  반지름 값
                            entity_Position.Y = objectData.dEdgePoint[0].Y -
                                                data.dRegionCenter.Y;

                            entity_Position_Rot = RotatePoint_CurPos(data.dRegionCenter, entity_Position, Math.PI / 2.0);

                            //if (Equipment.RtcMode_syncAxis == (int)Equipment.RtcMode.RTC_SYNCAXIS)
                            //{
                            //    data.JumpVector = new Vector2((float)entity_Position.X, (float)entity_Position.Y);
                            //}
                            //else if (Equipment.RtcMode_syncAxis == (int)Equipment.RtcMode.RTC_RTC6)
                            {
                                data.JumpVector = new Vector2((float)entity_Position_Rot.X, (float)entity_Position_Rot.Y);
                            }

                            //  Arc 구동 
                            entity_Position.X = objectData.dEdgePoint[0].X -
                                                data.dRegionCenter.X;
                            entity_Position.Y = objectData.dEdgePoint[0].Y -
                                                data.dRegionCenter.Y;

                            data.nVectorCount = 1;
                            data.Vectors = new Vector2[1];
                            //if (Equipment.RtcMode_syncAxis == (int)Equipment.RtcMode.RTC_SYNCAXIS)
                            //{
                            //    data.Vectors[0] = new Vector2((float)entity_Position.X, (float)entity_Position.Y);
                            //}
                            //else if (Equipment.RtcMode_syncAxis == (int)Equipment.RtcMode.RTC_RTC6)
                            {
                                data.Vectors[0] = new Vector2((float)entity_Position_Rot.X, (float)entity_Position_Rot.Y);
                            }

                            break;


                        case (int)ObjectType.OBJECT_RECT:
                            //  첫 번째 Edge Point 로 Jump 이동
                            entity_Position.X = objectData.dEdgePoint[0].X -
                                                data.dRegionCenter.X;
                            entity_Position.Y = objectData.dEdgePoint[0].Y -
                                                data.dRegionCenter.Y;

                            entity_Position_Rot = RotatePoint_CurPos(data.dRegionCenter, entity_Position, Math.PI / 2.0);

                            //if (Equipment.RtcMode_syncAxis == (int)Equipment.RtcMode.RTC_SYNCAXIS)
                            //{
                            //    data.JumpVector = new Vector2((float)entity_Position.X, (float)entity_Position.Y);
                            //}
                            //else if (Equipment.RtcMode_syncAxis == (int)Equipment.RtcMode.RTC_RTC6)
                            {
                                data.JumpVector = new Vector2((float)entity_Position_Rot.X, (float)entity_Position_Rot.Y);
                            }
                            data.nVectorCount = objectData.nEdgePointNum;
                            data.Vectors = new Vector2[objectData.nEdgePointNum];
                            //  이어서 오는 Edge Point 로 Mark 이동(cont') 하여 Polyline 완성
                            for (int nEntity = 1; nEntity < objectData.nEdgePointNum; nEntity++)
                            {
                                entity_Position.X = objectData.dEdgePoint[nEntity].X -
                                                    data.dRegionCenter.X;
                                entity_Position.Y = objectData.dEdgePoint[nEntity].Y -
                                                    data.dRegionCenter.Y;

                                entity_Position_Rot = RotatePoint_CurPos(data.dRegionCenter, entity_Position, Math.PI / 2.0);

                                //if (Equipment.RtcMode_syncAxis == (int)Equipment.RtcMode.RTC_SYNCAXIS)
                                //{
                                //    data.Vectors[nEntity] = new Vector2((float)entity_Position.X, (float)entity_Position.Y);
                                //}
                                //else if (Equipment.RtcMode_syncAxis == (int)Equipment.RtcMode.RTC_RTC6)
                                {
                                    data.Vectors[nEntity] = new Vector2((float)entity_Position_Rot.X, (float)entity_Position_Rot.Y);
                                }
                            }
                            break;


                        case (int)ObjectType.OBJECT_LINE:
                            //  첫 번째 Edge Point 로 Jump 이동 (Start)
                            entity_Position.X = objectData.dEdgePoint[0].X -
                                                data.dRegionCenter.X;
                            entity_Position.Y = objectData.dEdgePoint[0].Y -
                                                data.dRegionCenter.Y;

                            entity_Position_Rot = RotatePoint_CurPos(data.dRegionCenter, entity_Position, Math.PI / 2.0);

                            //if (Equipment.RtcMode_syncAxis == (int)Equipment.RtcMode.RTC_SYNCAXIS)
                            //{
                            //    data.JumpVector = new Vector2((float)entity_Position.X, (float)entity_Position.Y);
                            //}
                            //else if (Equipment.RtcMode_syncAxis == (int)Equipment.RtcMode.RTC_RTC6)
                            {
                                data.JumpVector = new Vector2((float)entity_Position_Rot.X, (float)entity_Position_Rot.Y);
                            }

                            //  이어서 오는 Edge Point 로 Mark 이동 (End)
                            entity_Position.X = objectData.dEdgePoint[1].X -
                                                data.dRegionCenter.X;
                            entity_Position.Y = objectData.dEdgePoint[1].Y -
                                                data.dRegionCenter.Y;

                            entity_Position_Rot = RotatePoint_CurPos(data.dRegionCenter, entity_Position, Math.PI / 2.0);
                            data.nVectorCount = 1;
                            data.Vectors = new Vector2[1];
                            //if (Equipment.RtcMode_syncAxis == (int)Equipment.RtcMode.RTC_SYNCAXIS)
                            //{
                            //    data.Vectors[0] = new Vector2((float)entity_Position.X, (float)entity_Position.Y);
                            //}
                            //else if (Equipment.RtcMode_syncAxis == (int)Equipment.RtcMode.RTC_RTC6)
                            {
                                data.Vectors[0] = new Vector2((float)entity_Position_Rot.X, (float)entity_Position_Rot.Y);
                            }
                            break;
                    }
                }
            }
        }

        // 원의 좌표를 저장하는 배열
        //private PointD[] circleCoordinates = new PointD[12];

        // 입력한 좌표와 가까운 4개의 원 좌표를 가져오는 메서드
        public PointD[] GetClosestCircles(PointD inputCoordinate)
        {
            return m_ptFiducial
                .OrderBy(c => GetDistance(c, inputCoordinate))
                .Take(4)
                .ToArray();
        }

        // 두 좌표 간의 거리를 계산하는 메서드
        private double GetDistance(PointD p1, PointD p2)
        {
            return Math.Sqrt(Math.Pow(p1.X - p2.X, 2) + Math.Pow(p1.Y - p2.Y, 2));
        }

        private void SortFastPath(ref stDrilling_GroupData paths, bool bSortDir_HorVer, double dStepSize)
        {
            List<stDrilling_ObjectData> pathFast = new List<stDrilling_ObjectData>();

            double dStep = 0.0;
            dStep = dStepSize;

            if (dStep <= 0.0)
            {
                dStep = 0.03;
            }

            if (bSortDir_HorVer)           //  X 방향 Zigzag 이동
            {
                if (paths.m_stDrilling_ObjectData != null)
                {

                    double dMin = paths.m_stDrilling_ObjectData.Min(t => t.dEdgePoint.Min(tt => tt.Y));
                    double dMax = paths.m_stDrilling_ObjectData.Max(t => t.dEdgePoint.Max(tt => tt.Y));

                    bool bAccending = true;


                    for (double iter = dMin; iter <= dMax; iter += dStep)
                    {
                        IOrderedEnumerable<stDrilling_ObjectData> iSorted = null;
                        if (bAccending)
                        {
                            iSorted = paths.m_stDrilling_ObjectData.Where(t => t.dEdgePoint.Min(tt => tt.Y) >= iter && t.dEdgePoint.Min(tt => tt.Y) < (iter + dStep)).ToList().OrderBy(t => t.dEdgePoint.Min(tt => tt.X));
                        }
                        else
                        {
                            iSorted = paths.m_stDrilling_ObjectData.Where(t => t.dEdgePoint.Min(tt => tt.Y) >= iter && t.dEdgePoint.Min(tt => tt.Y) < (iter + dStep)).ToList().OrderByDescending(t => t.dEdgePoint.Min(tt => tt.X));
                        }

                        pathFast.AddRange(iSorted);
                        bAccending = !bAccending;
                    }
                }
            }
            else                //  Y 방향 Zigzag 이동
            {
                if (paths.m_stDrilling_ObjectData != null)
                {

                    double dMin = paths.m_stDrilling_ObjectData.Min(t => t.dEdgePoint.Min(tt => tt.X));
                    double dMax = paths.m_stDrilling_ObjectData.Max(t => t.dEdgePoint.Max(tt => tt.X));

                    bool bAccending = true;


                    for (double iter = dMin; iter <= dMax; iter += dStep)
                    {
                        IOrderedEnumerable<stDrilling_ObjectData> iSorted = null;
                        if (bAccending)
                        {
                            iSorted = paths.m_stDrilling_ObjectData.Where(t => t.dEdgePoint.Min(tt => tt.X) >= iter && t.dEdgePoint.Min(tt => tt.X) < (iter + dStep)).ToList().OrderBy(t => t.dEdgePoint.Min(tt => tt.Y));
                        }
                        else
                        {
                            iSorted = paths.m_stDrilling_ObjectData.Where(t => t.dEdgePoint.Min(tt => tt.X) >= iter && t.dEdgePoint.Min(tt => tt.X) < (iter + dStep)).ToList().OrderByDescending(t => t.dEdgePoint.Min(tt => tt.Y));
                        }

                        pathFast.AddRange(iSorted);
                        bAccending = !bAccending;
                    }

                }
            }
            paths.m_stDrilling_ObjectData = pathFast.ToArray();
        }

        public st4PointAlign_Result Calc_4Point_AlignData(st4PointPosition_Data[] ptDwgPos, st4PointPosition_Data[] ptInspectedPos)
        {
            //  4 Point 위치 (좌측 하단부터 시계방향으로)
            //  P1 : Left Bottom
            //  P2 : Left Top
            //  P3 : Right Top
            //  P4 : Right Bottom

            //  직선 구성 : P2 - P4, P1 - P3

            st4PointAlign_Result m_st4PointAlign_Result = new st4PointAlign_Result();
            m_st4PointAlign_Result.dCenterOffsetX = 0.0;
            m_st4PointAlign_Result.dCenterOffsetY = 0.0;
            m_st4PointAlign_Result.dRotationAngle = 0.0;

            //  도면상 좌표 데이터 모두 존재하는지 체크
            if ((ptDwgPos[0].ptFiducial_Center.X == 0.0) && (ptDwgPos[0].ptFiducial_Center.Y == 0.0) &&
                (ptDwgPos[1].ptFiducial_Center.X == 0.0) && (ptDwgPos[1].ptFiducial_Center.Y == 0.0) &&
                (ptDwgPos[2].ptFiducial_Center.X == 0.0) && (ptDwgPos[2].ptFiducial_Center.Y == 0.0) &&
                (ptDwgPos[3].ptFiducial_Center.X == 0.0) && (ptDwgPos[3].ptFiducial_Center.Y == 0.0))
            {
                return m_st4PointAlign_Result;
            }

            //  비전 검사로 얻은 좌표 데이터 모두 존재하는지 체크
            if ((ptInspectedPos[0].ptFiducial_Center.X == 0.0) && (ptInspectedPos[0].ptFiducial_Center.Y == 0.0) &&
                (ptInspectedPos[1].ptFiducial_Center.X == 0.0) && (ptInspectedPos[1].ptFiducial_Center.Y == 0.0) &&
                (ptInspectedPos[2].ptFiducial_Center.X == 0.0) && (ptInspectedPos[2].ptFiducial_Center.Y == 0.0) &&
                (ptInspectedPos[3].ptFiducial_Center.X == 0.0) && (ptInspectedPos[3].ptFiducial_Center.Y == 0.0))
            {
                return m_st4PointAlign_Result;
            }

            //  도면상좌표 데이터 4개의 교차점이 존재하는지 체크
            if ((((ptDwgPos[1].ptFiducial_Center.X - ptDwgPos[3].ptFiducial_Center.X) * (ptDwgPos[2].ptFiducial_Center.Y - ptDwgPos[0].ptFiducial_Center.Y)) -
                ((ptDwgPos[1].ptFiducial_Center.Y - ptDwgPos[3].ptFiducial_Center.Y) * (ptDwgPos[2].ptFiducial_Center.X - ptDwgPos[0].ptFiducial_Center.X))) == 0.0)                                //  교차점이 없는 경우
            {
                return m_st4PointAlign_Result;
            }

            //  비전 검사로 얻은 좌표 데이터 4개의 교차점이 존재하는지 체크
            if ((((ptInspectedPos[1].ptFiducial_Center.X - ptInspectedPos[3].ptFiducial_Center.X) * (ptInspectedPos[2].ptFiducial_Center.Y - ptInspectedPos[0].ptFiducial_Center.Y)) -
                ((ptInspectedPos[1].ptFiducial_Center.Y - ptInspectedPos[3].ptFiducial_Center.Y) * (ptInspectedPos[2].ptFiducial_Center.X - ptInspectedPos[0].ptFiducial_Center.X))) == 0.0)                                //  교차점이 없는 경우
            {
                return m_st4PointAlign_Result;
            }

            //  도면상 좌표 데이터의 교차점 계산
            double dDwgCrossX = 0.0;
            double dDwgCrossY = 0.0;

            dDwgCrossX = (((ptDwgPos[1].ptFiducial_Center.X * ptDwgPos[3].ptFiducial_Center.Y - ptDwgPos[1].ptFiducial_Center.Y * ptDwgPos[3].ptFiducial_Center.X) * (ptDwgPos[2].ptFiducial_Center.X - ptDwgPos[0].ptFiducial_Center.X) -
                        (ptDwgPos[1].ptFiducial_Center.X - ptDwgPos[3].ptFiducial_Center.X) * (ptDwgPos[2].ptFiducial_Center.X * ptDwgPos[0].ptFiducial_Center.Y - ptDwgPos[2].ptFiducial_Center.Y * ptDwgPos[0].ptFiducial_Center.X)) /
                        ((ptDwgPos[1].ptFiducial_Center.X - ptDwgPos[3].ptFiducial_Center.X) * (ptDwgPos[2].ptFiducial_Center.Y - ptDwgPos[0].ptFiducial_Center.Y) - (ptDwgPos[1].ptFiducial_Center.Y - ptDwgPos[3].ptFiducial_Center.Y) * (ptDwgPos[2].ptFiducial_Center.X - ptDwgPos[0].ptFiducial_Center.X)));
            dDwgCrossY = (((ptDwgPos[1].ptFiducial_Center.X * ptDwgPos[3].ptFiducial_Center.Y - ptDwgPos[1].ptFiducial_Center.Y * ptDwgPos[3].ptFiducial_Center.X) * (ptDwgPos[2].ptFiducial_Center.Y - ptDwgPos[0].ptFiducial_Center.Y) -
                        (ptDwgPos[1].ptFiducial_Center.Y - ptDwgPos[3].ptFiducial_Center.Y) * (ptDwgPos[2].ptFiducial_Center.X * ptDwgPos[0].ptFiducial_Center.Y - ptDwgPos[2].ptFiducial_Center.Y * ptDwgPos[0].ptFiducial_Center.X)) /
                        ((ptDwgPos[1].ptFiducial_Center.X - ptDwgPos[3].ptFiducial_Center.X) * (ptDwgPos[2].ptFiducial_Center.Y - ptDwgPos[0].ptFiducial_Center.Y) - (ptDwgPos[1].ptFiducial_Center.Y - ptDwgPos[3].ptFiducial_Center.Y) * (ptDwgPos[2].ptFiducial_Center.X - ptDwgPos[0].ptFiducial_Center.X)));

            //  비전 검사로 얻은 좌표 데이터의 교차점 계산
            double dInspectedCrossX = 0.0;
            double dInspectedCrossY = 0.0;

            dInspectedCrossX = (((ptInspectedPos[1].ptFiducial_Center.X * ptInspectedPos[3].ptFiducial_Center.Y - ptInspectedPos[1].ptFiducial_Center.Y * ptInspectedPos[3].ptFiducial_Center.X) * (ptInspectedPos[2].ptFiducial_Center.X - ptInspectedPos[0].ptFiducial_Center.X) -
                        (ptInspectedPos[1].ptFiducial_Center.X - ptInspectedPos[3].ptFiducial_Center.X) * (ptInspectedPos[2].ptFiducial_Center.X * ptInspectedPos[0].ptFiducial_Center.Y - ptInspectedPos[2].ptFiducial_Center.Y * ptInspectedPos[0].ptFiducial_Center.X)) /
                        ((ptInspectedPos[1].ptFiducial_Center.X - ptInspectedPos[3].ptFiducial_Center.X) * (ptInspectedPos[2].ptFiducial_Center.Y - ptInspectedPos[0].ptFiducial_Center.Y) - (ptInspectedPos[1].ptFiducial_Center.Y - ptInspectedPos[3].ptFiducial_Center.Y) * (ptInspectedPos[2].ptFiducial_Center.X - ptInspectedPos[0].ptFiducial_Center.X)));
            dInspectedCrossY = (((ptInspectedPos[1].ptFiducial_Center.X * ptInspectedPos[3].ptFiducial_Center.Y - ptInspectedPos[1].ptFiducial_Center.Y * ptInspectedPos[3].ptFiducial_Center.X) * (ptInspectedPos[2].ptFiducial_Center.Y - ptInspectedPos[0].ptFiducial_Center.Y) -
                        (ptInspectedPos[1].ptFiducial_Center.Y - ptInspectedPos[3].ptFiducial_Center.Y) * (ptInspectedPos[2].ptFiducial_Center.X * ptInspectedPos[0].ptFiducial_Center.Y - ptInspectedPos[2].ptFiducial_Center.Y * ptInspectedPos[0].ptFiducial_Center.X)) /
                        ((ptInspectedPos[1].ptFiducial_Center.X - ptInspectedPos[3].ptFiducial_Center.X) * (ptInspectedPos[2].ptFiducial_Center.Y - ptInspectedPos[0].ptFiducial_Center.Y) - (ptInspectedPos[1].ptFiducial_Center.Y - ptInspectedPos[3].ptFiducial_Center.Y) * (ptInspectedPos[2].ptFiducial_Center.X - ptInspectedPos[0].ptFiducial_Center.X)));

            //  도면상 좌표 데이터의 교차점과 비전 검사로 얻은 좌표 데이터의 교차점간 오프셋 거리 계산
            double dOffsetX = 0.0;
            double dOffsetY = 0.0;
            dOffsetX = dDwgCrossX - dInspectedCrossX;
            dOffsetY = dDwgCrossY - dInspectedCrossY;

            //  도면상 좌표 데이터의 교차점과 비전 검사로 얻은 좌표 데이터의 교차점간 회전 각도 계산
            double dAngle = 0.0;
            double dDwgAngle = 0.0;
            double dInspectedAngle = 0.0;
            dDwgAngle = Math.Atan2(ptDwgPos[1].ptFiducial_Center.Y - ptDwgPos[3].ptFiducial_Center.Y, ptDwgPos[1].ptFiducial_Center.X - ptDwgPos[3].ptFiducial_Center.X);
            dInspectedAngle = Math.Atan2(ptInspectedPos[1].ptFiducial_Center.Y - ptInspectedPos[3].ptFiducial_Center.Y, ptInspectedPos[1].ptFiducial_Center.X - ptInspectedPos[3].ptFiducial_Center.X);
            dAngle = dDwgAngle - dInspectedAngle;

            //  결과값 저장  
            m_st4PointAlign_Result.dRotationCenterX = dDwgCrossX;
            m_st4PointAlign_Result.dRotationCenterY = dDwgCrossY;
            m_st4PointAlign_Result.dCenterOffsetX = dOffsetX;
            m_st4PointAlign_Result.dCenterOffsetY = dOffsetY;
            m_st4PointAlign_Result.dRotationAngle = dAngle;

            return m_st4PointAlign_Result;
        }

